INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, locations, experience, trust_score, is_verified) VALUES ('b-paranjape', 'Paranjape Schemes', 'paranjape-schemes', '/images/builders/paranjape-official.webp', 'https://www.pscl.in/wp-content/uploads/2025/10/ANK440_7834a_LR.webp', 'Founded in 1987 by Shrikant and Shashank Paranjape, Paranjape Schemes (Construction) Ltd (PSCL) is one of Maharashtra''s most pioneering real estate developers with over 200 delivered projects, 20,000+ satisfied families, iconic mega townships like Blue Ridge (Hinjewadi) and Forest Trails (Bhugaon), and pioneer senior citizen living communities under the Athashri brand across Pune and Mumbai MMR.', 1987, 18, 25, '["Hinjewadi", "Bavdhan", "Baner", "Khed Shivapur", "Karve Road", "Bandra East", "Andheri West", "Thane West", "Shrivardhan-Diveagar"]', 39, 9.7, 1);
INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, locations, experience, trust_score, is_verified) VALUES ('b-hiranandani', 'Hiranandani Group', 'hiranandani-group', '/images/builders/hiranandani-official.webp', 'https://www.hiranandani.com/img/gallery/gallery-powai-castle-rock-a/01.jpg', 'Hiranandani Group is one of India''s most prestigious real estate conglomerates, renowned for pioneering integrated mega-townships like Hiranandani Gardens Powai and Hiranandani Estate Thane. Founded in 1978 by Dr. Niranjan Hiranandani, the group has transformed urban living across Maharashtra with neoclassical architecture, world-class social infrastructure, lush green environments, and impeccable engineering.', 1978, 15, 18, '["Powai", "Thane", "Panvel", "Kandivali", "Chembur", "Pune"]', 46, 4.9, 1);
INSERT INTO builders (id, name, slug, logo, hero_image, description, established_year, total_projects, ongoing_projects, locations, experience, trust_score, is_verified) VALUES ('b-della', 'Della Townships', 'della-townships', '/images/builders/della-official.webp', 'https://www.dellaresorts.com/new-updated-image/enclave-villa-resort.webp', 'Della Townships and Luxury Villas, conceptualized and designed by visionary architect Jimmy Mistry, represents the pinnacle of experiential hillside living and ultra-luxury second homes in Maharashtra. Spread across scenic hill slopes in Kunegaon, Lonavala and Khandala, Della offers fully serviced bespoke villas integrated with 24x7 5-star resort hospitality, private heated pools, fine-dining restaurants, and India''s premier adventure sports park.', 1996, 4, 5, '["Kunegaon", "Lonavala", "Khandala", "Sahyadri Hills"]', 28, 4.9, 1);
