INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-godrej-hillside-3', 'Godrej Hillside 3', 'godrej-hillside-3', 'b-godrej', 'Mahalunge', '₹81.00 L - ₹1.06 Cr', '₹81.00 L', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', 'in 2027', 'https://keystoneliv.com/public/uploads/property/QQmMk6MksfNeJOsNyWH7z6Sry9x5MXzEGBPiWPLv.webp', 'https://keystoneliv.com/public/uploads/property/QQmMk6MksfNeJOsNyWH7z6Sry9x5MXzEGBPiWPLv.webp', 'https://keystoneliv.com/public/uploads/property/5oObZb7synV62rPVYqZAbCYsgqNubnGbhVrvmYj8.webp', '["https://keystoneliv.com/public/uploads/property/GygLc1rdjQ06VlpY0H6SSeiwGPlGQOAaiXpk2BXx.png", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1734594060428044806.jpeg"]', 'Godrej Hillside 3 by Godrej Properties represents modern residential excellence in Mahalunge, Pune. Strategically located with direct access to Pune''s prime business parks, tech hubs, and reputed educational institutions, this premium development offers meticulously designed 2 BHK, 3 BHK residences with optimal natural light and cross ventilation.
