INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-santiago-skyworld-2-0', 'Santiago Skyworld 2.0', 'santiago-skyworld-2-0', 'b-santiago-on-sector-7-road', 'Bhosari', '₹1.47 Cr - ₹2.11 Cr', '₹1.47 Cr', '["3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/2be1e665-b28e-4bf5-a42f-348a3a0fa8ff/gallery/mvu2wo4q-g2u1r4.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/2be1e665-b28e-4bf5-a42f-348a3a0fa8ff/gallery/mvu2wo4q-g2u1r4.webp', 'https://keystoneliv.com/public/uploads/property/c5iyPCgaCqPe2H7UgjtMuIlxz0gkapjWv7U5nlzE.webp', '["https://keystoneliv.com/public/uploads/property/image (17).webp"]', 'Santiago Skyworld 2.0 is a new 12-storey residential tower with ground-floor shops by Santiago on Sector 7 Road, Indrayani Nagar, Bhosari, in the Pradhikaran area of Pimpri-Chinchwad, and the second Skyworld project after Santiago Skyworld on Spine Road. It has only six homes per floor, all 3 BHK, which the developer calls 3 bed suites: homes of 1,332, 1,348 and 1,375 sq ft from ₹1.47 crore agreement value, and garden flats of 1,471 to 1,956 sq ft from ₹1.59 crore. Every home has three balconies plus a separate dry balcony, a private aangan at the entrance, a spacious designer kitchen and Vastu-compliant planning, and comes with two covered car parks. The building has two high-speed branded lifts and a wide staircase, a first-floor amenity level with a swimming pool, an indoor gym, indoor games, a library and a co-working space, and rooftop amenities with open views. The ground-floor commercial shops suit retail, showrooms and offices. The developer gives travel times of about 2 minutes to shopping malls, 5 minutes to COEP University, the PCMC court, Star Bazaar, schools, colleges and hospitals, and 10 minutes to more than ten hotels, with Spine Road and the highways close by; it also points to an upcoming IIM campus and metro station about 5 minutes away. Possession is planned for December 2028. The gallery shows artist''s impressions from the developer''s Santiago Skyworld brochure.', '["Gymnasium", "Library", "Co-working Lounge", "Swimming Pool", "Covered Parking"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "Verified Registered"}, {"label": "Direct Starting Price", "value": "₹1.47 Cr"}, {"label": "Configurations", "value": "3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Bhosari, Pune"}]', '["MahaRERA: Registered", "0% Brokerage & Direct Builder Booking", "Bhosari Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100048912', 11061, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/2be1e665-b28e-4bf5-a42f-348a3a0fa8ff/gallery/mvu2wo4q-g2u1r4.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/2be1e665-b28e-4bf5-a42f-348a3a0fa8ff/gallery/mvu2wo6t-5rao36.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/2be1e665-b28e-4bf5-a42f-348a3a0fa8ff/gallery/mvu2wo8r-d6rn8x.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/2be1e665-b28e-4bf5-a42f-348a3a0fa8ff/gallery/mvu2wob4-avxktr.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/2be1e665-b28e-4bf5-a42f-348a3a0fa8ff/gallery/mvu2wod6-g8nzbn.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/2be1e665-b28e-4bf5-a42f-348a3a0fa8ff/gallery/mvu2wof8-5apyo1.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/2be1e665-b28e-4bf5-a42f-348a3a0fa8ff