INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-kosha', 'Kosha', 'kosha', 'b-konbil-group', 'Koregaon Park', '₹5.91 Cr - ₹12.85 Cr', '₹5.91 Cr', '["4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/1fb3b136-50b8-4324-8729-93f941e2b964/gallery/mvu3597y-eky877.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/1fb3b136-50b8-4324-8729-93f941e2b964/gallery/mvu3597y-eky877.webp', 'https://keystoneliv.com/public/uploads/property/aWnxy62MDO1QX60oMsN6OrORW8XJAf2mAMh9MAgQ.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/17284659891506445855.jpg"]', 'Kosha is a luxury tower of 4.5 BHK homes on South Main Road, Koregaon Park, near Blossom Boulevard, by Konbil Group and Chandra Prabha Developers through Hydepark Developers LLP. With only four residences per floor and 3.9-metre floor-to-ceiling heights, it offers three kinds of home, each with four bedrooms and a house-help room: 4.5 BHK residences of about 2,257 to 2,943 sq ft of carpet area with long sit-outs; garden residences on the first floor with private gardens, quoted at about 3,582 to 4,398 sq ft; and duplex sky villas on the 20th and 21st floors with open-to-sky gardens and terraces, quoted at about 4,372 to 5,423 sq ft. On the current price sheet, bare-shell homes start at ₹5.91 crore for a 2,257 sq ft residence, ₹9.83 crore for a garden residence and ₹12.85 crore for a sky villa (agreement value, before GST, stamp duty and registration). Amenities spread across three levels include a swimming pool with a poolside deck, a gym, sauna, yoga deck, café, business centre, banquet hall, card room, senior citizens'' garden and landscaped recreation spaces, and a 360-degree skywalk around the building, with a grand entrance lobby and concierge. The tower has four levels of covered parking, high-speed elevators, slab-to-slab aluminium windows with high-performance glass, DG backup for the entire apartment, a BMS and control room, CCTV, access control at each common entrance, automatic biometric door locks and sprinklers and smoke detectors in every home. German Bakery, Osho Garden and Malaka Spice are within five minutes, The Westin, Conrad, Marriott Suites and Kalyani Nagar within ten, Poona Club and the Symbiosis institutes within fifteen, and Magarpatta, Hadapsar IT Park and The Bishop''s School within twenty. The project is registered with MahaRERA as PR1260002500453.', '["CCTV Surveillance", "Gymnasium", "Co-working Lounge", "Swimming Pool", "Power Backup", "Landscaped Garden", "Covered Parking", "Concierge"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1260002500453"}, {"label": "Direct Starting Price", "value": "₹5.91 Cr"}, {"label": "Configurations", "value": "4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Koregaon Park, Pune"}]', '["MahaRERA: PR1260002500453", "0% Brokerage & Direct Builder Booking", "Koregaon Park Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100060453', 26181, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/1fb3b136-50b8-4324-8729-93f941e2b964/gallery/mvu3597y-eky877.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1fb3b136-50b8-4324-8729-93f941e2b964/gallery/mvu3599w-d7fb9e.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1fb3b136-50b8-4324-8729-93f941e2b964/gallery/mvu359bv-d7sg0r.webp", "https://punehome.in/storage/v1/object/public/project-media/proje