INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-the-reserve-mundhwa', 'The Reserve', 'the-reserve-mundhwa', 'b-the-skies-group', 'Mundhwa', '₹2.35 Cr - ₹5.35 Cr', '₹2.35 Cr', '["3 BHK", "4 BHK"]', 'Under Construction', 'Residential', 'December 2029', 'https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aoaa-1tal46.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aoaa-1tal46.webp', 'https://keystoneliv.com/public/uploads/property/hgiRTenojaVcHglxBXqRVHfjihUs6wuNa8Yl46OW.png', '["https://keystoneliv.com/public/uploads/property/EqFhQWfr3lRMA1nua2t6lHamZuSarVQj6Xo2TWu5.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/ImDiujOwFBjJL4Fonv1zzS6x5tRznB71FrHLlhmt.webp"]', 'The Reserve is a low-density residential project by Lohia Jain Malpani Properties (promoter LJM Estate LLP, in association with Kodre Realty) at Pingale Wasti, Mundhwa, near the Mundhwa Passport Seva Kendra, in the stretch better known as Koregaon Park Annexe. Spread over 4.25 acres, it has three towers of 20 residential floors above two basement parking levels and a stilt floor, built with an earthquake-resistant RCC frame, aluminium formwork and AAC blocks, and a 3.30 m floor-to-floor height. The homes are 3 BHK apartments of 1,243, 1,413 and 1,417 sq ft from ₹2.35 crore, 4 BHK residences of 2,482 and 2,698 sq ft from ₹4.70 crore, which the brochure calls 4.5 BHK because each adds a servant''s room with its own toilet, and a select few 4 BHK duplexes of 2,696 sq ft at ₹5.35 crore. All prices are all-inclusive packages covering stamp duty, registration and GST; areas are the total carpet areas on the developer''s cost sheet. More than an acre of open space at ground level is kept free of vehicles, and amenities are spread across the ground, podium and terrace: a swimming pool, a gymnasium of over 2,000 sq ft, an open gym, a yoga pavilion, a glass pavilion, a multi-sports area and box cricket, a banquet hall with an attached garden, an amphitheatre, a kids'' play area, seating pods, a barbecue area, acupressure and jogging tracks, senior citizens'' sit-outs and rooms for drivers. Homes have 1200 x 1800 mm vitrified tile flooring, a fully loaded modular kitchen with a granite platform, powder-coated windows with double-glazed glass, Grohe or equivalent fittings, a shower panel in the master bathroom, a digital lock on the main door, a video door phone and three-level access control. Green features include a sewage treatment plant, rainwater harvesting, solar hot water in the master bathroom, a bore-water treatment plant, a garbage chute and EV charging points. The brochure places the offices of Bajaj Finance, Bharat Forge, Google and Poonawalla Fincorp within about 200 m, and Kopa mall and Koregaon Park''s cafés and restaurants less than a kilometre away, with Kalyani Nagar, Kharadi, Magarpatta and SP Infocity a short drive away. The project is registered with MahaRERA as PR1260002400065, with 290 homes; the developer is targeting possession in December 2029, and the RERA completion date is 30 April 2030.', '["CCTV Surveillance", "Gymnasium", "Rainwater Harvesting", "Sports Court", "Jogging Track", "Swimming Pool", "24x7 Security", "Landscaped Garden"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1260002400065"}, {"label": "Direct Starting Price", "value": "₹2.35 Cr"}, {"label": "Configurations", "value": "3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "December 2029"}, {"label": "Micro-Market", "value": "Mundhwa, Pune"}]', '["MahaRERA: PR1260002400065", "0% Brokerage & Direct Builder Booking", "Mundhwa Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100030065', 18905, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aoaa-1tal46.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aocv-dnqlcl.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aog3-t1u28.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aoih-81694z.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aokz-3hsu4y.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aomx-6842i7.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aooz-885gcn.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aord-5l6la1.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aotl-2mfwo0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aow1-7lc1zx.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aoxz-dvmgwg.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1aozy-einp8i.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bf83785b-7b34-4206-a1c4-1a538a8ce57a/gallery/mvu1ap2f-cfxkcr