INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-palladio-presidential-towers', 'Palladio Presidential Towers', 'palladio-presidential-towers', 'b-palladio-developers', 'Hadapsar', '₹1.35 Cr - ₹2.60 Cr', '₹1.35 Cr', '["2 BHK", "3 BHK", "4 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/765c8240-3fed-4d70-b271-5ecbd6547ee4/gallery/mvv5vy43-31pt59.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/765c8240-3fed-4d70-b271-5ecbd6547ee4/gallery/mvv5vy43-31pt59.webp', 'https://keystoneliv.com/public/liv-thumbs/640/uploads/property/f9GMlttRsqc66dOt6VQurFR4i48juAfzCiUaFmOs.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/udgWlmoH6ofCgYL184zKnPq8Zexr2l7fEoztyewT.webp", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1676437496513882194.jpg", "https://keystoneliv.com/public/uploads/property/sk7FyGScerfdwSXPmZkNYGxMsPJf0x63qGejfDTU.webp"]', 'Palladio Presidential Towers is a new residential project by Vilas Javdekar Developers (VJ), in association with Tupe Developers, in Sector 2 of the Hadapsar Central community beside Leisure Town, east of Amanora Park Town and Magarpatta City in Hadapsar. Six towers, T1 to T6, are planned with up to 38 or 39 habitable floors and about 1,000 homes; Phase 1, registered with MahaRERA as PM1260002602526 with 490 homes, launches towers T1, T2, T5 and T6 up to the 20th and 21st floors. It offers 2 BHK homes of 828 to 963 sq ft, 3 BHK homes of 996 to 1,282 sq ft and 4 BHK homes of 1,532 to 1,542 sq ft (RERA carpet plus enclosed and open balconies), six to a floor with four passenger lifts and a fire lift. Launch price ranges are ₹1.35 to 1.45 crore for a 2 BHK, ₹1.60 to 2.20 crore for a 3 BHK and ₹2.60 to 2.75 crore for a 4 BHK. Amenities are spread over the ground, podium and terrace levels, with a 26,000 sq ft, three-level President''s Club holding a banquet hall, co-working lounges, a library, a mini theatre, a squash court, gyms, yoga studios and a spa, while the gardens add sports courts, a jogging track, a pet park, play areas and sky decks. Homes come with imported marble flooring in the living, dining, kitchen and attached balcony, wooden flooring in the bedrooms, full home automation with a smart door lock, Jaquar thermostatic showers, UPVC windows and glass balcony railings. A 2 BHK gets one car park, a 3 BHK two and a 4 BHK three. The RERA completion date for Phase 1 is December 2032.', '["Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "24x7 Security"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "PM1260002602526"}, {"label": "Direct Starting Price", "value": "₹1.35 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Hadapsar, Pune"}]', '["MahaRERA: PM1260002602526", "0% Brokerage & Direct Builder Booking", "Hadapsar Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100022526', 16304, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/765c8240-3fed-4d70-b271-5ecbd6547ee4/gallery/mvv5vy43-31pt59.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765c8240-3fed-4d70-b271-5ecbd6547ee4/gallery/mvv5vy69-fity16.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765c8240-3fed-4d70-b271-5ecbd6547ee4/gallery/mvv5vy8e-fn5uw3.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765c8240-3fed-4d70-b271-5ecbd6547ee4/gallery/mvv5vyae-abqpbg.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765c8240-3fed-4d70-b271-5ecbd6547ee4/gallery/mvv5vycg-efvcr8.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765c8240-3fed-4d70-b271-5ecbd6547ee4/gallery/mvv5vyfj-ajtdd0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765c8240-3fed-4d70-b271-5ecbd6547ee4/gallery/mvv5vyhq-fiqw1v.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765c8240-3fed-4d70-b271-5ecbd6547ee4/gallery/mvv5vykp-4v8tfq.webp"]', 4.8, 100, 1, 0, 18.505, 73.9279, '[{"type": "2 BHK", "carpetArea": "708 sq.ft", "priceRange": "₹1.35 Cr - ₹1.69 Cr"}, {"type": "3 BHK", "carpetArea": "1072 sq.ft", "priceRange": "₹1.89 Cr - ₹2.43 Cr"}, {"type": "4 BHK", "carpetArea": "1746 sq.ft", "priceRange": "₹2.60 Cr"}]', '["Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "24x7 Security"]', '[{"question": "Where is Palladio Presidential Towers located?", "answer": "Palladio Presidential Towers is strategically located in prime Hadapsar, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Palladio Presidential Towers?", "answer": "Residences in Palladio Presidential Towers start from ₹1.35 Cr - ₹2.60 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Palladio Presidential Towers?", "answer": "Palladio Presidential Towers offers spacious 2 BHK, 3 BHK, 4 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Palladio Presidential Towers MahaRERA approved?", "answer": "Yes, Palladio Presidential Towers is officially registered under MahaRERA with registration number PM1260002602526. All approvals and certificates are verified."}, {"question": "What amenities are provided at Palladio Presidential Towers?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Gymnasium, Library, Sports Court, Co-working Lounge, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-tulip-infinity-evana-commercial', 'Tulip Infinity Evana Commercial', 'tulip-infinity-evana-commercial', 'b-tulip-realty', 'Punawale', '₹20.50 L - ₹4.08 Cr', '₹20.50 L', '["Shop", "Office"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/5709b783-9c9c-4c60-b4ed-4cef6de35826/gallery/mvwi01g5-1gw9fi.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/5709b783-9c9c-4c60-b4ed-4cef6de35826/gallery/mvwi01g5-1gw9fi.webp', 'https://keystoneliv.com/public/uploads/property/OrO96DlQ1BdtwMK7CAwta4xb2E56lGlQ1N3qwfrF.webp', '["https://keystoneliv.com/public/uploads/property/qXM8HRWxsHzEqzzkejOkuF5OA14I5dxYYMPiCfKC.webp", "https://keystoneliv.com/public/uploads/property/9bazfJfHebPTWOPKZhvlI5uteXcmfF57aTBYkICe.webp"]', 'Tulip Infinity Evana Commercial is the shops-and-offices part of Tulip Infinity Evana at Rasikwadi, Punawale, Pune, by Varma Corp (the new name of the Tulip Group) with S.M. Group. It fills the podium along the project''s main-road frontage, under the same MahaRERA registration, P52100078470, with a completion date of 30 October 2029, and sits about 200 metres from the Mumbai-Bengaluru highway service road near the Pawana river bridge at Ravet. The ground floor has 36 shops in an L-shape along two roads, each with a mezzanine above it and a 1-metre walkway in front. Shops on offer in October 2026 measure 369 to 1,652 sq ft of carpet area, counting the mezzanine. Floors one to four hold offices of 205 to 1,517 sq ft carpet with glazed fronts, a commercial lobby, three lifts and common washrooms on each floor, and most offices have their own toilet. The developer quotes about ₹35,000 per sq ft for shops and ₹10,000 to ₹14,000 per sq ft for offices, on carpet area and plus taxes, so a 369 sq ft shop starts at about ₹1.29 Cr and a 205 sq ft office at about ₹20.5 lakh before GST and stamp duty. The homes in the four towers above are listed separately as Tulip Infinity Evana.', '["Covered Parking"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100078470"}, {"label": "Direct Starting Price", "value": "₹20.50 L"}, {"label": "Configurations", "value": "Shop, Office"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Punawale, Pune"}]', '["MahaRERA: P52100078470", "0% Brokerage & Direct Builder Booking", "Punawale Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100078470', 10000, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/5709b783-9c9c-4c60-b4ed-4cef6de35826/gallery/mvwi01g5-1gw9fi.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5709b783-9c9c-4c60-b4ed-4cef6de35826/gallery/mvwi01hw-1a930v.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5709b783-9c9c-4c60-b4ed-4cef6de35826/gallery/mvwi01jo-81grmp.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5709b783-9c9c-4c60-b4ed-4cef6de35826/gallery/mvwi01li-a6o1fg.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5709b783-9c9c-4c60-b4ed-4cef6de35826/gallery/mvwi01n4-6caiqq.webp"]', 4.8, 100, 1, 0, 18.6294, 73.7329, '[{"type": "Shop", "carpetArea": "599 sq.ft", "priceRange": "₹20.50 L"}, {"type": "Office", "carpetArea": "584 sq.ft", "priceRange": "₹20.50 L - ₹4.08 Cr"}]', '["Covered Parking"]', '[{"question": "Where is Tulip Infinity Evana Commercial located?", "answer": "Tulip Infinity Evana Commercial is strategically located in prime Punawale, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Tulip Infinity Evana Commercial?", "answer": "Residences in Tulip Infinity Evana Commercial start from ₹20.50 L - ₹4.08 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Tulip Infinity Evana Commercial?", "answer": "Tulip Infinity Evana Commercial offers spacious Shop, Office apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Tulip Infinity Evana Commercial MahaRERA approved?", "answer": "Yes, Tulip Infinity Evana Commercial is officially registered under MahaRERA with registration number P52100078470. All approvals and certificates are verified."}, {"question": "What amenities are provided at Tulip Infinity Evana Commercial?", "answer": "The development features world-class lifestyle amenities including Covered Parking, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-vitthal-nirvana', 'Vitthal Nirvana', 'vitthal-nirvana', 'b-vissionary-developers', 'Nigdi', '₹1.40 Cr - ₹1.44 Cr', '₹1.40 Cr', '["3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/934ae67a-4206-4655-b43b-e446319056a8/gallery/mvuqeigv-choo9y.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/934ae67a-4206-4655-b43b-e446319056a8/gallery/mvuqeigv-choo9y.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-hilife-wakad-pune/Hilife_Master_Plan_5c82917d3b.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/17745428672075565255.jpg"]', 'Vitthal Nirvana is a residential project by Vissionary Developers on Plot 12, Sector 24, Nigdi Pradhikaran, near Geeta Pavbhaji and opposite Axis Bank, on a 24 m wide road. It is a seven-storey building with just 14 three-bedroom homes, two on each floor, above covered car parking on the ground floor. The two 3 BHK layouts have carpet areas of about 1,052 and 1,086 sq ft and cost ₹1.40 crore and ₹1.44 crore (agreement value), or about ₹1.57 crore and ₹1.62 crore with stamp duty, GST and registration. The rooftop has a gazebo, a senior citizens'' sitting area, a barbecue corner and a small stage and screening area. Homes get 4 x 2 ft vitrified flooring, three-track aluminium sliding windows with granite sills, Cera or Jaguar bathroom fittings, Legrand or L&T switches, a video door phone and glass railings on the balconies, and the building has an Otis lift with battery backup and rainwater harvesting.', '["Rainwater Harvesting", "Covered Parking"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "Verified Registered"}, {"label": "Direct Starting Price", "value": "₹1.40 Cr"}, {"label": "Configurations", "value": "3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Nigdi, Pune"}]', '["MahaRERA: Registered", "0% Brokerage & Direct Builder Booking", "Nigdi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100032914', 13299, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/934ae67a-4206-4655-b43b-e446319056a8/gallery/mvuqeigv-choo9y.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/934ae67a-4206-4655-b43b-e446319056a8/gallery/mvuqeij6-4zp12i.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/934ae67a-4206-4655-b43b-e446319056a8/gallery/mvuqeikx-2nng76.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/934ae67a-4206-4655-b43b-e446319056a8/gallery/mvuqeimm-8l4g8l.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/934ae67a-4206-4655-b43b-e446319056a8/gallery/mvuqeion-fj325b.webp"]', 4.8, 100, 1, 0, 18.661, 73.7661, '[{"type": "3 BHK Luxury Unit", "carpetArea": "1005 sq.ft", "priceRange": "₹1.40 Cr"}]', '["Rainwater Harvesting", "Covered Parking"]', '[{"question": "Where is Vitthal Nirvana located?", "answer": "Vitthal Nirvana is strategically located in prime Nigdi, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Vitthal Nirvana?", "answer": "Residences in Vitthal Nirvana start from ₹1.40 Cr - ₹1.44 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Vitthal Nirvana?", "answer": "Vitthal Nirvana offers spacious 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Vitthal Nirvana MahaRERA approved?", "answer": "Yes, Vitthal Nirvana is officially registered under MahaRERA with registration number MahaRERA Registered. All approvals and certificates are verified."}, {"question": "What amenities are provided at Vitthal Nirvana?", "answer": "The development features world-class lifestyle amenities including Rainwater Harvesting, Covered Parking, multi-tier security systems, and high-speed elevators."}]', '');
