INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-asap-tishya', 'ASAP Tishya', 'asap-tishya', 'b-asap-spaces', 'Aundh', '₹3.30 Cr - ₹4.21 Cr', '₹3.30 Cr', '["3 BHK", "4.5 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgwmc-fz80rc.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgwmc-fz80rc.webp', 'https://keystoneliv.com/public/uploads/property/OrO96DlQ1BdtwMK7CAwta4xb2E56lGlQ1N3qwfrF.webp', '["https://keystoneliv.com/public/uploads/property/image (81).webp", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1688036267101676629.jpg"]', 'ASAP Tishya, branded "Tishya – The Beginning", is a boutique residential tower by ASAP Spaces on Ashiyana Park Lane No. 2 in Aundh, Pune, near Baner Road. It holds just 12 homes on six residential floors, two to a floor: six 3 BHK homes of 1,667 sq ft total carpet area (2,251 sq ft saleable) and six 4.5 BHK homes of 2,183 sq ft total carpet area (2,947 sq ft saleable), where the half is a servant room with its own toilet. On the current price sheet, agreement values start at ₹3.30 crore for a 3 BHK and ₹4.21 crore for a 4.5 BHK, with two car parks for a 3 BHK and three for a 4.5 BHK. Homes get Italian marble in the living, dining, kitchen and bathrooms, wooden flooring in the bedrooms, ROCA sanitaryware with GESSI fittings, Tostem aluminium windows, heat-pump hot water, a smart main-door lock with video calling and pre-wired CAT 6A and fibre conduits. The ground floor has a main lobby, a kids'' play area, a party lawn and a multipurpose lounge, and the project adds a BBQ and café zone, a gym, sky lounges and green zones on each residential floor, a car-wash bay, EV charging provision and solar power for common areas. The tower is designed by VDA Designs, and the brochure gives its MahaRERA registration as PR1260002500977.', '["CCTV Surveillance", "Gymnasium", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking", "Kids'' Play Area", "EV Charging"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1260002500977"}, {"label": "Direct Starting Price", "value": "₹3.30 Cr"}, {"label": "Configurations", "value": "3 BHK, 4.5 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Aundh, Pune"}]', '["MahaRERA: PR1260002500977", "0% Brokerage & Direct Builder Booking", "Aundh Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100060977', 19796, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgwmc-fz80rc.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgwoq-5gg19v.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgwqp-4bzzwp.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgwsw-3zkmjf.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgwup-ghm126.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgwwn-75mp6o.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgwyj-30ap6p.webp", "https://puneh