INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-excellaa-virtu', 'Excellaa Virtu', 'excellaa-virtu', 'b-excellaa-realty', 'Pimple Nilakh', '₹1.27 Cr - ₹1.37 Cr', '₹1.27 Cr', '["3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1o7c-1x2u56.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1o7c-1x2u56.webp', 'https://keystoneliv.com/public/uploads/property/QUSiXbX1yIv3u1F0efgnLHyJgKsJfu0DIDG1r7Wi.webp', '["https://keystoneliv.com/public/uploads/property/2ocDxHCTXWnA2CnIKGCGcSwin1rTir1eCXkoMNzB.webp"]', 'Excellaa Virtu is a nearly complete project of exclusive 3 BHK homes on Jagtap Dairy Road in Vishal Nagar, Pimple Nilakh, Pune, by Excellaa Realty as part of its Gold Collection. It is registered with MahaRERA as P52100054268, and both the RERA date and the developer''s commitment for possession are December 2026. The building has two wings joined at the centre in a butterfly plan, with eight homes on each floor, two lifts and two staircases. Homes come in two sizes: 1,005 sq ft (932 sq ft carpet plus a 74 sq ft balcony) and 1,091 sq ft (1,027 plus 64). Both layouts have two master suites with attached bathrooms, a walk-in wardrobe, a private patio off the living and dining room, an L-shaped kitchen and AC points in every bedroom. Agreement values are ₹1.27 Cr and ₹1.37 Cr, or about ₹1.42 Cr and ₹1.54 Cr with stamp duty, registration and GST. The roof holds 25 amenities, including a climatised pool with a kids'' pool and deck, a glass-walled gym, a bonfire sky lounge, a sky lawn, an amphitheatre, a fenced junior play area, indoor games, working pods and herbal and aromatic gardens.', '["Gymnasium", "Co-working Lounge", "Swimming Pool", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100054268"}, {"label": "Direct Starting Price", "value": "₹1.27 Cr"}, {"label": "Configurations", "value": "3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Pimple Nilakh, Pune"}]', '["MahaRERA: P52100054268", "0% Brokerage & Direct Builder Booking", "Pimple Nilakh Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100054268', 12600, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1o7c-1x2u56.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1ob3-844sdq.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1od6-fl5izu.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1of6-eiqa27.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1oh8-2q96g2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1oj9-1z5rn0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1ol5-bll2zy.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1on9-40qjn3.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1f3df788-7035-4e21-8487-a66424ab8f1f/gallery/mvwl1opg-g44546.webp"]', 4.8, 100, 1, 0, 18.5869, 73.7948, '[{"type": "3 BHK Premium", "carpetArea": "1020 sq.ft", "priceRange": "₹1.27 Cr"}, {"type": "3 BHK Grande", "carpetArea": "1100 sq.ft", "priceRange": "₹1.37 Cr"}]', '["Gymnasium", "Co-working Lounge", "Swimming Pool", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"question": "Where is Excellaa Virtu located?", "answer": "Excellaa Virtu is strategically located in prime Pimple Nilakh, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Excellaa Virtu?", "answer": "Residences in Excellaa Virtu start from ₹1.27 Cr - ₹1.37 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Excellaa Virtu?", "answer": "Excellaa Virtu offers spacious 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Excellaa Virtu MahaRERA approved?", "answer": "Yes, Excellaa Virtu is officially registered under MahaRERA with registration number P52100054268. All approvals and certificates are verified."}, {"question": "What amenities are provided at Excellaa Virtu?", "answer": "The development features world-class lifestyle amenities including Gymnasium, Co-working Lounge, Swimming Pool, Power Backup, 24x7 Security, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-excellaa-tott', 'Excellaa TOTT', 'excellaa-tott', 'b-excellaa-realty', 'Maan', '₹89.00 L - ₹1.21 Cr', '₹89.00 L', '["2 BHK", "3 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwmbtqx-aken1v.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwmbtqx-aken1v.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-cielo-bavdhan-pune/Cielo_Master_Plan_5a82741b2c.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/1676437496754730563.jpg", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1776692151873809711.jpeg"]', 'Excellaa TOTT, launched under the name Codename TOTT ("Talk of the Town"), is a pre-launch residential project by Excellaa Realty on the 45-metre Hinjawadi–Maan Road in Maan, west of Hinjewadi Phase 1, Pune. Spread over more than 10 acres, the master layout shows seven buildings (A to G) around a large central open space with a clubhouse and swimming pool, more open spaces, and the Excellaa Highstreet shopping strip along the main road. It offers 2 BHK homes of 725 and 825 sq ft and 3 BHK homes of 1,000 and 1,100 sq ft (carpet area) in three layouts each, every one with a work-from-home nook, and the 3 BHK homes have three toilets. All-inclusive prices are ₹89 to 99 lakh for a 2 BHK and ₹1.21 to 1.37 crore for a 3 BHK, and the developer promises more than 50 lifestyle amenities. The developer''s distance chart puts Nexus Care Hospital 370 m away, MIS International School 1 km, Infosys Phase 1 2.5 km, the HCL and Wipro campuses 2.6 km, Hinjewadi Phase 2 2.9 km and Grand Highstreet Mall 3.4 km. Excellaa Realty reports a 34-year legacy, more than 22 projects and over 4,500 families. No MahaRERA registration number has been shared yet.', '["Clubhouse", "Swimming Pool", "Landscaped Garden"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "Verified Registered"}, {"label": "Direct Starting Price", "value": "₹89 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Maan, Pune"}]', '["MahaRERA: Registered", "0% Brokerage & Direct Builder Booking", "Maan Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100028741', 12275, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwmbtqx-aken1v.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwmbtv8-1ksf1d.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwmbtxr-a684rj.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwk2rzs-4x2dt5.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwmbu0r-1asovr.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwmbu3u-4xjxli.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwmbu6r-504gei.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwmbu8s-eg21rl.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3977a54a-a81a-4bb1-ba5d-bf1a6808e2ac/gallery/mvwk2s1x-1dkp34.webp"]', 4.8, 100, 1, 0, 18.588, 73.7127, '[{"type": "2 BHK", "carpetArea": "690 sq.ft", "priceRange": "₹89.00 L"}, {"type": "3 BHK", "carpetArea": "1073 sq.ft", "priceRange": "₹1.25 Cr - ₹1.60 Cr"}]', '["Clubhouse", "Swimming Pool", "Landscaped Garden"]', '[{"question": "Where is Excellaa TOTT located?", "answer": "Excellaa TOTT is strategically located in prime Maan, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Excellaa TOTT?", "answer": "Residences in Excellaa TOTT start from ₹89 L - ₹1.21 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Excellaa TOTT?", "answer": "Excellaa TOTT offers spacious 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Excellaa TOTT MahaRERA approved?", "answer": "Yes, Excellaa TOTT is officially registered under MahaRERA with registration number MahaRERA Registered. All approvals and certificates are verified."}, {"question": "What amenities are provided at Excellaa TOTT?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Swimming Pool, Landscaped Garden, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-the-vantage-wakad', 'The Vantage', 'the-vantage-wakad', 'b-kuber-properties', 'Wakad', '₹1.07 Cr - ₹2.69 Cr', '₹1.07 Cr', '["2 BHK", "3 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/a92fc5ac-8421-4852-af64-88fdc835cc3c/gallery/mvv3umst-naexw.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/a92fc5ac-8421-4852-af64-88fdc835cc3c/gallery/mvv3umst-naexw.webp', 'https://www.vtprealty.in/images/project/project-details/earth-one-by-vtp-luxe-mahalunge-pune/Earth_One_Master_Plan_307e5f524c.webp', '["https://keystoneliv.com/public/uploads/property/CmDFE12nnFIgAUpMaBjxRl9fnigcnkgzhwmPsgEZ.webp", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1734594038492844200.jpeg", "https://keystoneliv.com/public/uploads/property/hgiRTenojaVcHglxBXqRVHfjihUs6wuNa8Yl46OW.png"]', 'The Vantage is a residential and commercial project by Kuber Properties in Wakad, behind Hotel Tip Top International near the Mumbai-Bengaluru highway, on an 18 m access road towards Bhumkar Wasti Road. The architect''s master plan shows four residential towers of two basements, a podium and 13 floors, and a commercial building with retail at the entrance. It offers 2 BHK homes of 857 sq ft from ₹1.08 crore and 3 BHK homes of 1,198 sq ft at ₹1.48 crore, plus duplex homes on the 12th and 13th floors: 3 BHK duplexes of 1,639 sq ft at ₹2.17 crore and 4 BHK duplexes of 2,050 sq ft at ₹2.69 crore. Prices are agreement values including infrastructure charges (about ₹1.21 crore to ₹3.01 crore with stamp duty, GST and registration), and areas are usable area, RERA carpet plus balcony. The terrace amenity floor has a children''s play area, an open gym and yoga deck, a senior citizens'' plaza, a lawn and a party lawn, gazebos, a sand pit, a BBQ area, a sit-out and a stargazing deck, and 10% of the site is kept as open space on the ground. The project is registered with MahaRERA as PR1260002601066.', '["Gymnasium", "Landscaped Garden", "Covered Parking", "Kids'' Play Area", "Yoga Deck"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1260002601066"}, {"label": "Direct Starting Price", "value": "₹1.07 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Wakad, Pune"}]', '["MahaRERA: PR1260002601066", "0% Brokerage & Direct Builder Booking", "Wakad Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100021066', 12543, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/a92fc5ac-8421-4852-af64-88fdc835cc3c/gallery/mvv3umst-naexw.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a92fc5ac-8421-4852-af64-88fdc835cc3c/gallery/mvv3umv9-6n4kit.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a92fc5ac-8421-4852-af64-88fdc835cc3c/gallery/mvv3umxh-drntt8.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a92fc5ac-8421-4852-af64-88fdc835cc3c/gallery/mvv3umzk-2fhhin.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/dde4a6ce-f1b5-4b32-84c1-e8514171ca50/gallery/mtmpxi80-38i0gv.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/850377d9-38b6-4267-88da-eed7d19f924c/gallery/mvf42z4p-bwtdn0.webp"]', 4.8, 100, 1, 1, 18.6019, 73.7675, '[{"type": "2 BHK", "carpetArea": "746 sq.ft", "priceRange": "₹1.07 Cr - ₹1.34 Cr"}, {"type": "3 BHK", "carpetArea": "1049 sq.ft", "priceRange": "₹1.50 Cr - ₹1.93 Cr"}, {"type": "4 BHK", "carpetArea": "1691 sq.ft", "priceRange": "₹2.69 Cr"}]', '["Gymnasium", "Landscaped Garden", "Covered Parking", "Kids'' Play Area", "Yoga Deck"]', '[{"question": "Where is The Vantage located?", "answer": "The Vantage is strategically located in prime Wakad, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in The Vantage?", "answer": "Residences in The Vantage start from ₹1.07 Cr - ₹2.69 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in The Vantage?", "answer": "The Vantage offers spacious 2 BHK, 3 BHK, 4 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is The Vantage MahaRERA approved?", "answer": "Yes, The Vantage is officially registered under MahaRERA with registration number PR1260002601066. All approvals and certificates are verified."}, {"question": "What amenities are provided at The Vantage?", "answer": "The development features world-class lifestyle amenities including Gymnasium, Landscaped Garden, Covered Parking, Kids'' Play Area, Yoga Deck, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-sukhwani-gemz', 'Sukhwani Gemzs', 'sukhwani-gemz', 'b-prime-properties', 'Maan', '₹1.03 Cr - ₹1.30 Cr', '₹1.03 Cr', '["2 BHK", "2.5 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzfz9-39rbi.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzfz9-39rbi.webp', 'https://keystoneliv.com/public/uploads/property/9mQcxr2kQwdxOjKHIxo2zEp9jrfIGuIrQfIHkK7o.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/1734594164955974829.jpeg", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1776692151873809711.jpeg", "https://shapoorjirealestate.com/files/assets/jpegs/all_projects/wildernest/floorplans/4bhk-3.webp"]', 'Sukhwani Gemzs is a low-density residential project by Prime Properties, a Sukhwani Group company, on Thakar Nagar Road in Maan, near Hinjewadi. It is registered with MahaRERA as PR1260002601952. The 4,250 sq m (about 1.05 acre) parcel holds the homes and a separate amenity parcel, with about 4,500 sq ft of open space for amenities, parking on three levels (basement, ground and podium) and no MHADA component. It offers Vaastu-compliant 2 BHK homes of 730 sq ft, 2.5 BHK homes of 860 sq ft with a flex room, and 3 BHK homes of 923 sq ft (RERA carpet plus balconies), at all-inclusive prices of ₹1.03 crore, ₹1.21 crore and ₹1.30 crore. The all-inclusive price covers GST, stamp duty, registration, the corpus fund, two years'' maintenance, legal and society charges and parking. Amenities include a clubhouse, a gym, a multipurpose court, a children''s play area, sitout zones, walking paths and landscaped open space. Homes get 600 x 1200 mm vitrified tiles, a digital main-door lock and video door phone, a separate dry balcony with a sink, a granite kitchen platform and inverter provision. The brochure puts MIS School 1.1 km away, Elpro International School 2.6 km, Ruby Hall Clinic Hinjawadi 3.7 km, Grand Highstreet 4.4 km and the Wipro, TCS and Infosys campuses 5.2 to 6.4 km away. Possession is planned for June 2030.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Sports Court", "Jogging Track", "Power Backup", "24x7 Security", "Landscaped Garden"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1260002601952"}, {"label": "Direct Starting Price", "value": "₹1.03 Cr"}, {"label": "Configurations", "value": "2 BHK, 2.5 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Maan, Pune"}]', '["MahaRERA: PR1260002601952", "0% Brokerage & Direct Builder Booking", "Maan Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100021952', 14109, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzfz9-39rbi.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzg19-91tgdm.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzg3j-b0rove.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzg5s-4z36ym.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzg7w-b8bppg.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzg9s-b8qn2j.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzgbt-epagbh.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzgdu-9mdtxk.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a3cccdc6-45e5-43ed-9364-4fc12208ec47/gallery/mwbwzgfz-ace0ht.webp"]', 4.8, 100, 1, 0, 18.5897, 73.7121, '[{"type": "2 BHK", "carpetArea": "693 sq.ft", "priceRange": "₹1.03 Cr - ₹1.29 Cr"}, {"type": "2.5 BHK", "carpetArea": "740 sq.ft", "priceRange": "₹1.03 Cr - ₹1.29 Cr"}, {"type": "3 BHK", "carpetArea": "1038 sq.ft", "priceRange": "₹1.30 Cr"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Sports Court", "Jogging Track", "Power Backup", "24x7 Security", "Landscaped Garden"]', '[{"question": "Where is Sukhwani Gemzs located?", "answer": "Sukhwani Gemzs is strategically located in prime Maan, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Sukhwani Gemzs?", "answer": "Residences in Sukhwani Gemzs start from ₹1.03 Cr - ₹1.30 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Sukhwani Gemzs?", "answer": "Sukhwani Gemzs offers spacious 2 BHK, 2.5 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Sukhwani Gemzs MahaRERA approved?", "answer": "Yes, Sukhwani Gemzs is officially registered under MahaRERA with registration number PR1260002601952. All approvals and certificates are verified."}, {"question": "What amenities are provided at Sukhwani Gemzs?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Clubhouse, Gymnasium, Sports Court, Jogging Track, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-pristine-amore', 'Pristine Amore', 'pristine-amore', 'b-pristine-properties', 'Kalyani Nagar', '₹4.25 Cr - ₹10.00 Cr', '₹4.25 Cr', '["3 BHK", "4.5 BHK", "5 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwt43-7q82bw.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwt43-7q82bw.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-cielo-bavdhan-pune/Cielo_Master_Plan_5a82741b2c.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/16842409551257395540.jpg", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/XuDMBetWz7JMao7EtAKipFvMdJLCxZvvdmU1XTf4.webp", "https://keystoneliv.com/public/uploads/property/XDKgaRfa1mQu0BrmAy2NCDrLJUSJqdBCMUuH63dB.webp", "https://keystoneliv.com/public/uploads/property/iQeFKSkfJMsMn9Q736Gsy56RUc1DUApUpYlXsjXI.webp"]', 'Pristine Amore is a luxury residential project by Pristine Properties on Late Sopanrao Trimbakrao Mulik Road in Kalyani Nagar, opposite Cerebrum IT Park. It is registered with MahaRERA as PR1261012600653, with Pristine Landmark Spaces LLP as the promoter, and possession is planned for December 2030. Designed by UHA London, the 4.12-acre master layout shows about 300 homes in five wings: A and B with four homes a floor and C, D and E with two; the Wing B plan set marks Wings C and D as future development. The wings rise to 24 floors above three basements, ceilings are 3.35 m high and there is no MHADA component. Wing B offers 3 BHK homes of 1,659 and 1,681 sq ft, 4.5 BHK homes (four bedrooms and a servant room) of 1,975 and 2,003 sq ft, 3,247 sq ft 5 BHK homes on the refuge floors, and duplexes on the 22nd and 23rd floors: 4 BHK of 2,720 to 2,746 sq ft and 5 BHK of 3,472 to 3,485 sq ft. Sizes are RERA carpet plus balconies, and quoted prices start at ₹4.25 crore. Amenities sit on three levels: a rooftop infinity pool, spa, salon and screening room on the terrace; a podium lawn, gym, Pilates and dance studios, library and crèche on the third floor; and, on the second floor, an emergency room, consultation room, pharmacy and physiotherapy centre backed by 24x7 nursing and ambulance service. A high street of showrooms and shops sits at the base.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Co-working Lounge", "Swimming Pool", "Landscaped Garden"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1261012600653"}, {"label": "Direct Starting Price", "value": "₹4.25 Cr"}, {"label": "Configurations", "value": "3 BHK, 4.5 BHK, 5 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Kalyani Nagar, Pune"}]', '["MahaRERA: PR1261012600653", "0% Brokerage & Direct Builder Booking", "Kalyani Nagar Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100060653', 25617, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwt43-7q82bw.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwt69-6s6nfo.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwt9r-1w9q7y.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwtbt-c7e8op.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwtdw-gbt67r.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwtfz-bqasf8.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwti3-49oiri.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwtk1-dz59hy.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/9e955491-de5d-45c8-a1e5-b959ff896266/gallery/mwbxwtm3-a6pob0.webp"]', 4.8, 100, 1, 0, 18.5428, 73.906, '[{"type": "3 BHK", "carpetArea": "1097 sq.ft", "priceRange": "₹4.25 Cr"}, {"type": "4.5 BHK", "carpetArea": "1831 sq.ft", "priceRange": "₹9.35 Cr - ₹11.90 Cr"}, {"type": "5 BHK", "carpetArea": "1825 sq.ft", "priceRange": "₹9.35 Cr - ₹11.90 Cr"}, {"type": "4 BHK", "carpetArea": "1685 sq.ft", "priceRange": "₹10.00 Cr"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Co-working Lounge", "Swimming Pool", "Landscaped Garden"]', '[{"question": "Where is Pristine Amore located?", "answer": "Pristine Amore is strategically located in prime Kalyani Nagar, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Pristine Amore?", "answer": "Residences in Pristine Amore start from ₹4.25 Cr - ₹10 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Pristine Amore?", "answer": "Pristine Amore offers spacious 3 BHK, 4.5 BHK, 5 BHK, 4 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Pristine Amore MahaRERA approved?", "answer": "Yes, Pristine Amore is officially registered under MahaRERA with registration number PR1261012600653. All approvals and certificates are verified."}, {"question": "What amenities are provided at Pristine Amore?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Clubhouse, Gymnasium, Rainwater Harvesting, Library, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-pristine-amore-highstreet', 'Pristine Amore Highstreet', 'pristine-amore-highstreet', 'b-uha-london', 'Kalyani Nagar', '₹4.75 Cr - ₹23.56 Cr', '₹4.75 Cr', '["Showroom", "Shop"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/fe3bba83-c3a1-4ebc-a7d3-38119f5f80bd/gallery/mwbxypu9-f14zae.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/fe3bba83-c3a1-4ebc-a7d3-38119f5f80bd/gallery/mwbxypu9-f14zae.webp', 'https://keystoneliv.com/public/uploads/property/iTt80ob6Q847pdqJo6QxQYX9jjyINihAoQvfFwpB.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/5e7ymEkZGYztA1gQgHtHN8r5SiHG3A5Er84IsIij.webp", "https://keystoneliv.com/public/uploads/property/image (18).webp"]', 'Pristine Amore Highstreet is the retail podium of Pristine Amore, a Pristine Properties project on Late Sopanrao Trimbakrao Mulik Road in Kalyani Nagar, opposite Cerebrum IT Park. It fronts the 18 m Cerebrum Road and an 18 m driveway, shares the homes'' MahaRERA registration (PR1261012600653) and has the same December 2030 possession date. The ground floor holds showrooms 1 to 24, each with a mezzanine; the current price list offers ten of them, from 1,315 to 4,005 sq ft (ground-floor carpet plus mezzanine), at ₹6.64 crore to ₹23.56 crore. Shops 28 to 51 sit on the level above the mezzanines (the price list calls it the first floor, the drawings the 2nd floor), and the list offers eleven sizes from 944 to 3,260 sq ft at ₹4.75 crore to ₹13.67 crore. The brochure pitches the spaces at restaurants, fashion, jewellery and automotive brands, and at larger stores or offices, with high-street visibility across several levels. Above the shops are about 300 homes in five wings designed by UHA London, with their own healthcare floor, podium lawn and rooftop amenities, so the high street has a resident catchment on site. The brochure''s location map also shows Cerebrum IT Park, DMart, Kopa Mall, Brahma Suncity, Cybage and the Kalyani Nagar and Ramwadi metro stations nearby.', '["CCTV Surveillance", "Rainwater Harvesting"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1261012600653"}, {"label": "Direct Starting Price", "value": "₹4.75 Cr"}, {"label": "Configurations", "value": "Showroom, Shop"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Kalyani Nagar, Pune"}]', '["MahaRERA: PR1261012600653", "0% Brokerage & Direct Builder Booking", "Kalyani Nagar Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100060653', 50317, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/fe3bba83-c3a1-4ebc-a7d3-38119f5f80bd/gallery/mwbxypu9-f14zae.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/fe3bba83-c3a1-4ebc-a7d3-38119f5f80bd/gallery/mwbxypw9-5o774q.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/fe3bba83-c3a1-4ebc-a7d3-38119f5f80bd/gallery/mwbxypyp-3juq7a.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/fe3bba83-c3a1-4ebc-a7d3-38119f5f80bd/gallery/mwbxyq0p-dl12i9.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/fe3bba83-c3a1-4ebc-a7d3-38119f5f80bd/gallery/mwbxyq2m-657qp.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/fe3bba83-c3a1-4ebc-a7d3-38119f5f80bd/gallery/mwbxyq4i-eekjo4.webp"]', 4.8, 100, 1, 0, 18.5475, 73.8987, '[{"type": "Showroom", "carpetArea": "714 sq.ft", "priceRange": "₹4.75 Cr - ₹23.56 Cr"}, {"type": "Shop", "carpetArea": "630 sq.ft", "priceRange": "₹23.56 Cr"}]', '["CCTV Surveillance", "Rainwater Harvesting"]', '[{"question": "Where is Pristine Amore Highstreet located?", "answer": "Pristine Amore Highstreet is strategically located in prime Kalyani Nagar, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Pristine Amore Highstreet?", "answer": "Residences in Pristine Amore Highstreet start from ₹4.75 Cr - ₹23.56 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Pristine Amore Highstreet?", "answer": "Pristine Amore Highstreet offers spacious Showroom, Shop apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Pristine Amore Highstreet MahaRERA approved?", "answer": "Yes, Pristine Amore Highstreet is officially registered under MahaRERA with registration number PR1261012600653. All approvals and certificates are verified."}, {"question": "What amenities are provided at Pristine Amore Highstreet?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Rainwater Harvesting, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-que-101', 'QUE 101', 'que-101', 'b-unique-properties', 'Dhanori', '₹80.03 L - ₹2.77 Cr', '₹80.03 L', '["2 BHK", "3 BHK", "4 BHK", "5 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/991a2afa-8abc-43d8-a7a9-e2374e67d2b8/gallery/mwbvbhe8-d8o2s4.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/991a2afa-8abc-43d8-a7a9-e2374e67d2b8/gallery/mwbvbhe8-d8o2s4.webp', 'https://www.vtprealty.in/images/project/project-details/flamante-by-vtp-luxe-kharadi-pune/Flamante_Master_Plan_7a81294c5d.webp', '["https://keystoneliv.com/public/uploads/property/PGlvfFmgy2VHokL2QsHGliY2jw1aMvsk3u0b9uB8.webp", "https://keystoneliv.com/public/uploads/property/gu9bQayoV6LdnMMIPWE4YCnur8rK2HqDUWUnOUJr.webp", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/16842409081778200113.jpg", "https://keystoneliv.com/public/uploads/property/OCn2152ubIWYsNscRoF5YYxsHbSz1zNbLdTEKCEn.webp"]', 'QUE 101 is a 12-acre residential community by Unique Properties on Bharat Mata Road in Dhanori, north-east Pune, about 6 km from Pune airport. Phase I is registered with MahaRERA as PM1261012602127 (promoter ANNR Unique Realty LLP). The master plan shows 12 towers, A to L, around a 40,000 sq ft central park, with 21,000 sq ft of semi-covered and indoor amenities and a retail street along the main road. Homes include 2 BHK flats of 828 to 838 sq ft and 3 BHK flats of 963 to 1,110 sq ft, second-floor homes with private terraces, duplexes of 3, 4 and 5 BHK from 1,370 to 2,049 sq ft on the ground and upper-ground floors, and 3 BHK row houses of 2,201 and 2,210 sq ft with front and back yards (all total areas). Agreement values on the November 2026 cost sheets start at ₹80.03 lakh for a 2 BHK, ₹91.94 lakh for a 3 BHK flat, ₹1.58 crore for a duplex and ₹2.76 crore for a row house. The amenity list runs to more than 65 items, including a clubhouse with an air-conditioned gym, swimming and kids'' pools, pickleball and half-basketball courts, a pet park, co-working and business lounges, podcast and creator studios, a mini theatre, a salon and spa, and an ice-bath recovery zone. Homes get 600 x 1200 mm vitrified tiles, biometric main-door locks, glass balcony railings, a video door phone and AC points in the living room and main bedroom. Possession is planned for December 2028.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Sports Court", "Co-working Lounge", "Jogging Track"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PM1261012602127"}, {"label": "Direct Starting Price", "value": "₹80.03 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK, 5 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Dhanori, Pune"}]', '["MahaRERA: PM1261012602127", "0% Brokerage & Direct Builder Booking", "Dhanori Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100062127', 9665, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/991a2afa-8abc-43d8-a7a9-e2374e67d2b8/gallery/mwbvbhe8-d8o2s4.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/991a2afa-8abc-43d8-a7a9-e2374e67d2b8/gallery/mwbvbhhd-8d9h8u.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/991a2afa-8abc-43d8-a7a9-e2374e67d2b8/gallery/mwbvbhjh-b67vwl.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/991a2afa-8abc-43d8-a7a9-e2374e67d2b8/gallery/mwbvbhll-6er8b.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/991a2afa-8abc-43d8-a7a9-e2374e67d2b8/gallery/mwbvbhnj-59y2v1.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/991a2afa-8abc-43d8-a7a9-e2374e67d2b8/gallery/mwbvbhpo-5hs49b.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/991a2afa-8abc-43d8-a7a9-e2374e67d2b8/gallery/mwbvbhrv-e17cva.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/991a2afa-8abc-43d8-a7a9-e2374e67d2b8/gallery/mwbvbhtr-uok2k.webp"]', 4.8, 100, 1, 0, 18.5849, 73.8961, '[{"type": "2 BHK", "carpetArea": "739 sq.ft", "priceRange": "₹80.03 L"}, {"type": "3 BHK", "carpetArea": "1102 sq.ft", "priceRange": "₹1.12 Cr - ₹1.44 Cr"}, {"type": "4 BHK", "carpetArea": "1723 sq.ft", "priceRange": "₹1.76 Cr - ₹2.24 Cr"}, {"type": "5 BHK", "carpetArea": "1672 sq.ft", "priceRange": "₹2.77 Cr"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Sports Court", "Co-working Lounge", "Jogging Track"]', '[{"question": "Where is QUE 101 located?", "answer": "QUE 101 is strategically located in prime Dhanori, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in QUE 101?", "answer": "Residences in QUE 101 start from ₹80.03 L - ₹2.77 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in QUE 101?", "answer": "QUE 101 offers spacious 2 BHK, 3 BHK, 4 BHK, 5 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is QUE 101 MahaRERA approved?", "answer": "Yes, QUE 101 is officially registered under MahaRERA with registration number PM1261012602127. All approvals and certificates are verified."}, {"question": "What amenities are provided at QUE 101?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Clubhouse, Gymnasium, Rainwater Harvesting, Library, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-amorapolis', 'Amorapolis', 'amorapolis', 'b-krisna-nirmaan-skyscraper-llp', 'Dhanori', '₹68.39 L - ₹99.19 L', '₹68.39 L', '["2 BHK", "3 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpc9-6l1q7t.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpc9-6l1q7t.webp', 'https://keystoneliv.com/public/uploads/property/fx4tJjRmJedaJ69GSAzp9y1Po3iHhu7xv951qJNV.webp', '["https://keystoneliv.com/public/uploads/property/HNvTc3nVkYmFjSbMvb2D2yLmiDCkAwa79zcs9svU.webp", "https://keystoneliv.com/public/uploads/property/image (21).webp"]', 'Amorapolis is a Nirman Greens residential community at Survey No. 12, Dhanori, Pune 411015, built in phases by Krisna Nirmaan Skyscraper LLP. Its earlier wings are registered with MahaRERA, and the newest, Wing I, is now on sale. Wing I''s typical floor plan has six homes a floor: two 2 BHK homes of 698 sq ft and four 3 BHK homes of 1,012 sq ft, each the carpet area plus an open balcony. The launch cost sheet also lists a 2 BHK Grand of 825 sq ft, which is not on the typical floor plan. Agreement values are ₹68.39 lakh for the 698 sq ft 2 BHK, ₹80.85 lakh for the 825 sq ft 2 BHK and ₹99.19 lakh for the 3 BHK; with 7% stamp duty, 5% GST and ₹31,000 registration, the totals come to ₹76.91 lakh, ₹90.86 lakh and ₹1.11 crore. The 2 BHK has a 15''6" x 16'' living and dining room and a sit-out; the 3 BHK has a 16''6" x 16''6" living and dining room, a kitchen with a utility area, a sit-out and a balcony. The developer''s renders show a clubhouse with a swimming pool, a basketball court, a children''s play area, landscaped gardens with an open-air stage, and a gated entrance, and it lists a surveillance system and 24x7 security. It places the project about 5 to 7 km from Pune International Airport and 6 to 8 km from Kharadi IT Park. Ask for Wing I''s MahaRERA registration and possession date before booking.', '["CCTV Surveillance", "Clubhouse", "Sports Court", "Swimming Pool", "24x7 Security", "Landscaped Garden", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "Verified Registered"}, {"label": "Direct Starting Price", "value": "₹68.39 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Dhanori, Pune"}]', '["MahaRERA: Registered", "0% Brokerage & Direct Builder Booking", "Dhanori Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100049120', 9797, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpc9-6l1q7t.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpe8-dijks2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpg7-2i76u1.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpi3-7cxk1w.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpk7-8fjp66.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpmj-74x1hp.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpp7-f8j5vw.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpr8-1w6qad.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydptb-561y23.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/cd6d53c1-cdb6-454a-b6d2-2a4fc40a4a86/gallery/mwbydpve-96ynpd.webp"]', 4.8, 100, 1, 0, 18.5823, 73.8911, '[{"type": "2 BHK", "carpetArea": "753 sq.ft", "priceRange": "₹68 L - ₹85 L"}, {"type": "3 BHK", "carpetArea": "1074 sq.ft", "priceRange": "₹99.19 L"}]', '["CCTV Surveillance", "Clubhouse", "Sports Court", "Swimming Pool", "24x7 Security", "Landscaped Garden", "Kids'' Play Area"]', '[{"question": "Where is Amorapolis located?", "answer": "Amorapolis is strategically located in prime Dhanori, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Amorapolis?", "answer": "Residences in Amorapolis start from ₹68.39 L - ₹99.19 L with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Amorapolis?", "answer": "Amorapolis offers spacious 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Amorapolis MahaRERA approved?", "answer": "Yes, Amorapolis is officially registered under MahaRERA with registration number MahaRERA Registered. All approvals and certificates are verified."}, {"question": "What amenities are provided at Amorapolis?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Clubhouse, Sports Court, Swimming Pool, 24x7 Security, multi-tier security systems, and high-speed elevators."}]', '');
