INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-pride-world-city-montreal', 'Pride World City Montreal', 'pride-world-city-montreal', 'b-pride-purple', 'Charholi', '₹1.49 Cr - ₹2.08 Cr', '₹1.49 Cr', '["3 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/d9c0b86f-9488-44d4-ae7e-3a967766730a/gallery/mvv3sv7b-4lv9b6.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/d9c0b86f-9488-44d4-ae7e-3a967766730a/gallery/mvv3sv7b-4lv9b6.webp', '/images/projects/anp-atlantis/master-layout.webp', '["https://keystoneliv.com/public/uploads/property/Oz85QLYWtUPkHjRU5N2NHLOOg2Z4WBzI9bJT6qeD.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/8KKQNl9pXNBZ6numJWe8UNpGknzVelIS0Qg1KIWp.webp"]', 'Pride World City Montreal is a cluster of duplex homes in Pride Group''s 400-acre Pride World City township at Charholi Budruk in north-east Pune. On about 10 acres, it is planned as eight towers of 28 floors with about 900 homes, each a true two-floor duplex with a double-height living room and an internal staircase. It is registered with MahaRERA as P52100053279 for towers A to D, due in December 2027, and P52100077138 for towers E and H, due in December 2028. The duplexes on offer are 3 BHK of about 1,352 to 1,357 sq ft from about ₹1.49 crore and 4 BHK of about 1,919 to 1,949 sq ft from about ₹2.08 crore (indicative all-inclusive prices, September 2026); 2 BHK duplexes of about 1,010 sq ft were also offered. Homes have smart home automation and superior specifications, and the more than 40 amenities include a mini Olympic pool, a clubhouse with a lounge, multipurpose hall, gym and indoor games, aerobics and zumba, a yoga zone, a futsal court, a mini cricket ground, an amphitheatre, a jogging track and children''s play areas.', '["Clubhouse", "Gymnasium", "Sports Court", "Jogging Track", "Swimming Pool", "Landscaped Garden", "Kids'' Play Area", "Amphitheatre"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100053279"}, {"label": "Direct Starting Price", "value": "₹1.49 Cr"}, {"label": "Configurations", "value": "3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Charoli, Pune"}]', '["MahaRERA: P52100053279", "0% Brokerage & Direct Builder Booking", "Charoli Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100053279', 11020, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/d9c0b86f-9488-44d4-ae7e-3a967766730a/gallery/mvv3sv7b-4lv9b6.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d9c0b86f-9488-44d4-ae7e-3a967766730a/gallery/mvv3sv9g-d8gp3f.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d9c0b86f-9488-44d4-ae7e-3a967766730a/gallery/mvv3svbj-33au24.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d9c0b86f-9488-44d4-ae7e-3a967766730a/gallery/mvv3svdu-76b4m9.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d9c0b86f-9488-44d4-ae7e-3a967766730a/gallery/mvv3svgb-evx753.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d9c0b86f-9488-44d4-ae7e-3a967766730a/gallery/mvv3svnb-bxe21n.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d9c0b86f-9488-44d4-ae7e-3a967766730a/gallery/mvv3svt1-dof4ek.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d9c0b86f-9488-44d4-ae7e-3a967766730a/gallery/mvv3svw5-4o4fqh.webp"]', 4.8, 100, 1, 0, 18.6489, 73.8964,