INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-55-twilight', '55 Twilight', '55-twilight', 'b-blue-pearl-group', 'Baner', '₹37.50 L', '₹37.50 L', '["Studio"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/84580f53-f3be-4a1b-94b5-c387737e5da0/gallery/mwc182b1-6xmrng.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/84580f53-f3be-4a1b-94b5-c387737e5da0/gallery/mwc182b1-6xmrng.webp', 'https://keystoneliv.com/public/liv-thumbs/640/uploads/property/9fgd1dc8OsLM6h4q6lT60MbRpIA4vwCadScNvqMA.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/16764375951689467383.jpg"]', '55 Twilight is a seven-storey building of 56 studio apartments by Blue Pearl at No. 55, Baner Annex Road, before Nyati Emerald and near Nanaware Chowk in Baner, with frontage on a 24-metre DP road. Each floor has eight studios of 200 sq ft, each with a 14''4" x 12''8" room, a 4''9" x 7''1" toilet, a kitchenette counter, a study corner and a balcony. The studios are sold unfurnished for self-use, at a launch price of ₹37.50 lakh. The developer and its partner Dweller Pro offer help with property management, renting and short-stay (Airbnb) operator tie-ups for owners who want to let their studio, and the brochure suggests rents of up to ₹35,000 a month, marked as indicative. It lists a gym, a cafeteria and an indoor games room, shown with stock images. The project is marketed as "MahaRERA compliant" but no registration number is printed, and no possession date has been published. By the brochure''s drive times, Nanaware Chowk and the Mumbai–Bengaluru highway are a minute away, Amar Madhuban Tech Park 2 minutes, Balewadi High Street 5 minutes, and Hinjewadi IT Park and Baner metro 10 minutes.', '["Gymnasium"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "Verified Registered"}, {"label": "Direct Starting Price", "value": "₹37.50 L"}, {"label": "Configurations", "value": "Studio"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Baner, Pune"}]', '["MahaRERA: Registered", "0% Brokerage & Direct Builder Booking", "Baner Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100042180', 8200, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/84580f53-f3be-4a1b-94b5-c387737e5da0/gallery/mwc182b1-6xmrng.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/84580f53-f3be-4a1b-94b5-c387737e5da0/gallery/mwc182el-6cxicd.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/84580f53-f3be-4a1b-94b5-c387737e5da0/gallery/mwc182h4-1dd7pj.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/84580f53-f3be-4a1b-94b5-c387737e5da0/gallery/mwc182j5-cma5cx.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/84580f53-f3be-4a1b-94b5-c387737e5da0/gallery/mwc182l0-g1su3d.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/84580f53-f3be-4a1b-94b5-c387737e5da0/gallery/mwc182n0-ehztpq.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/84580f53-f3be-4a1b-94b5-c387737e5da0/gallery/mwc182ox-87ut9l.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/84580f53-f3be-4a1b-94b5-c387737e5da0/gallery/mwc182qq-auevkl.webp"]', 4.8, 100, 1, 1, 18.5621, 73.7857, '[{"type": "Studio", "carpetArea": "555 sq.ft", "priceRange": "₹37.50 L"}]', '["Gymnasium"]', '[{"question": "Where is 55 Twilight located?", "answer": "55 Twilight is strategically located in prime Baner, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in 55 Twilight?", "answer": "Residences in 55 Twilight start from ₹37.50 L with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in 55 Twilight?", "answer": "55 Twilight offers spacious Studio apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is 55 Twilight MahaRERA approved?", "answer": "Yes, 55 Twilight is officially registered under MahaRERA with registration number MahaRERA Registered. All approvals and certificates are verified."}, {"question": "What amenities are provided at 55 Twilight?", "answer": "The development features world-class lifestyle amenities including Gymnasium, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-pride-world-city-wellington', 'Pride World City Wellington', 'pride-world-city-wellington', 'b-three-lifts', 'Charholi', '₹1.16 Cr - ₹1.26 Cr', '₹1.16 Cr', '["3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/681ee323-40a2-43c6-aa6b-b1b628b41ded/gallery/mvv3sx8p-fro66f.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/681ee323-40a2-43c6-aa6b-b1b628b41ded/gallery/mvv3sx8p-fro66f.webp', 'https://www.vtprealty.in/images/project/project-details/velvet-villas-by-vtp-luxe-kharadi-pune/Velvet_Villas_Master_Plan_8c72834b1a.webp', '["https://keystoneliv.com/public/uploads/property/Yh0MhqcWjQpkHVPH3DjAEWr0zVrTSWadIZUjfemG.webp"]', 'Pride World City Wellington is one of the largest clusters in Pride Group''s 400-acre Pride World City township at Charholi Budruk in north-east Pune: about 12 acres and 14 towers of three podium levels and 23 floors, with only six apartments a floor served by three lifts. The towers stand around an expansive 7-acre podium with the cluster''s amenities, among them a clubhouse with a swimming pool, children''s play areas, gazebos and a cricket ground. Wellington is built in phases; the developer lists MahaRERA registrations P52100031008, P52100045786, P52100048477, P52100052379 and P52100054534, and the latest phases, E-H-J-K and F-G, are due in December 2027. The current offer is 3 BHK homes in two sizes, 3 BHK L of about 1,056 sq ft from about ₹1.16 crore and 3 BHK XL of about 1,156 sq ft from about ₹1.26 crore (indicative all-inclusive prices, August 2026); earlier phases also had 2 BHK and 4 BHK homes. Homes have smart, spacious layouts and premium finishes.', '["Clubhouse", "Sports Court", "Swimming Pool", "Landscaped Garden", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100052379"}, {"label": "Direct Starting Price", "value": "₹1.16 Cr"}, {"label": "Configurations", "value": "3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Charoli, Pune"}]', '["MahaRERA: P52100052379", "0% Brokerage & Direct Builder Booking", "Charoli Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100052379', 10984, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/681ee323-40a2-43c6-aa6b-b1b628b41ded/gallery/mvv3sx8p-fro66f.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/681ee323-40a2-43c6-aa6b-b1b628b41ded/gallery/mvv3sxat-epplql.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/681ee323-40a2-43c6-aa6b-b1b628b41ded/gallery/mvv3sxcr-4pnxm6.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/681ee323-40a2-43c6-aa6b-b1b628b41ded/gallery/mvv3sxep-cys157.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/681ee323-40a2-43c6-aa6b-b1b628b41ded/gallery/mvv3sxgp-4p1m3f.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/681ee323-40a2-43c6-aa6b-b1b628b41ded/gallery/mvv3sxj2-ff99cs.webp"]', 4.8, 100, 1, 0, 18.6429, 73.8897, '[{"type": "3 BHK Premium", "carpetArea": "1126 sq.ft", "priceRange": "₹1.16 Cr"}, {"type": "3 BHK Grande", "carpetArea": "1223 sq.ft", "priceRange": "₹1.26 Cr"}]', '["Clubhouse", "Sports Court", "Swimming Pool", "Landscaped Garden", "Kids'' Play Area"]', '[{"question": "Where is Pride World City Wellington located?", "answer": "Pride World City Wellington is strategically located in prime Charoli, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Pride World City Wellington?", "answer": "Residences in Pride World City Wellington start from ₹1.16 Cr - ₹1.26 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Pride World City Wellington?", "answer": "Pride World City Wellington offers spacious 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Pride World City Wellington MahaRERA approved?", "answer": "Yes, Pride World City Wellington is officially registered under MahaRERA with registration number P52100052379. All approvals and certificates are verified."}, {"question": "What amenities are provided at Pride World City Wellington?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Sports Court, Swimming Pool, Landscaped Garden, Kids'' Play Area, multi-tier security systems, and high-speed elevators."}]', '');
