INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-santiago-moonrise', 'Santiago Moonrise', 'santiago-moonrise', 'b-santiago-realty', 'Chikhali', '₹55.00 L', '₹55.00 L', '["2 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/a29ec45e-adb5-4102-8301-1359013fc422/gallery/mwbu7slc-a0l7qs.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/a29ec45e-adb5-4102-8301-1359013fc422/gallery/mwbu7slc-a0l7qs.webp', 'https://keystoneliv.com/public/liv-thumbs/640/uploads/property/9fgd1dc8OsLM6h4q6lT60MbRpIA4vwCadScNvqMA.webp', '["https://keystoneliv.com/public/uploads/property/BdOHFAflcjgXwOB8Bd1Rh03LxMxYzglkJcavsSBS.webp"]', 'Santiago Moonrise is a residential tower of 2 BHK homes by Santiago Realty at Gat No. 13 on Dehu–Alandi Road in central Chikhali, Pimpri-Chinchwad, registered with MahaRERA as P52100080764 (promoter Shree Datta Developers). The typical floor plan shows six homes a floor, flats 101 to 606, around a lift and a 1.5 m wide corridor. The homes are about 693 sq ft of carpet area and start at ₹55 lakh, and most layouts have two balconies, one off the living room and one off the main bedroom. Homes get 600 x 600 mm vitrified flooring, a quartz kitchen platform with a steel sink, Jaguar or Cera bathroom fittings, Legrand or equivalent switches, three-track aluminium windows with mosquito mesh, an AC point in the main bedroom and inverter backup in each flat. The amenities are on the roof: a lawn and party area, a children''s play area, a mandir, an open gym, meditation and senior citizens'' courts, gazebo and outdoor co-working seating, a barbecue counter and kite-flying and stargazing areas. The building adds CCTV, a video door phone, generator backup, fire fighting, rainwater harvesting and a bus and cab pick-up point. The brochure puts D-Mart, City Pride School, SNBP International School and the district court 5 to 10 minutes away, and Talawade MIDC, Bhosari MIDC and Spine City Mall 10 to 15 minutes away. Possession is due in April 2028.', '["CCTV Surveillance", "Gymnasium", "Rainwater Harvesting", "Co-working Lounge", "Power Backup", "24x7 Security", "Landscaped Garden", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100080764"}, {"label": "Direct Starting Price", "value": "₹55 L"}, {"label": "Configurations", "value": "2 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Chikhali, Pune"}]', '["MahaRERA: P52100080764", "0% Brokerage & Direct Builder Booking", "Chikhali Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100080764', 7936, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/a29ec45e-adb5-4102-8301-1359013fc422/gallery/mwbu7slc-a0l7qs.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a29ec45e-adb5-4102-8301-1359013fc422/gallery/mwbu7spr-3blhg0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a29ec45e-adb5-4102-8301-1359013fc422/gallery/mwbu7suc-829tm.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a29ec45e-adb5-4102-8301-1359013fc422/gallery/mwbu7sy0-66gqz2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a29ec45e-adb5-4102-8301-1359013fc422/gallery/mwbu7t09-7atvi0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a29ec45e-adb5-4102-8301-1359013fc422/gallery/mwbu7t25-woduj.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a29ec45e-adb5-