INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-yoo-one', 'YOO One', 'yoo-one', 'b-dasscon-realty', 'NIBM', '₹3.01 Cr - ₹3.69 Cr', '₹3.01 Cr', '["3.5 BHK", "4.5 BHK"]', 'Ready to Move', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqe85-503eob.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqe85-503eob.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-altamira-kharadi-pune/Altamira_Master_Plan_166b88523c.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/16880362831588698124.jpg", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/CRFwCIeZDlS2wIt2FCjHtVPHQkc9Bh2S4PO5qe0k.webp"]', 'YOO One is a luxury residential project at NIBM, Pune, by Dasscon Realty, the luxury development arm of the construction company Tricon, with interiors by Sussanne Khan for YOO, the international design brand. The 6.75-acre development looks over about 200 acres of reserved forest. This listing covers Tower 2, Serenity: a 21-storey tower with four homes on each floor, registered with MahaRERA as PR1262022600430 (YOO One Phase II), with a RERA completion date of April 2030. Serenity has 3.5 BHK homes of 1,689 and 1,694 sq ft from ₹3.01 Cr and 4.5 BHK homes of 2,103 and 2,333 sq ft from ₹3.69 Cr, all inclusive; sizes are RERA carpet plus balcony. Every home has a servant''s room with its own toilet and a utility balcony, a living and dining room opening onto a private deck, floor-to-ceiling windows and a 3.375 m floor-to-floor height, and the forest-facing bedrooms look over the reserve. Buyers get space for a VRF/VRV air-conditioning system, a fingerprint digital lock and freedom to personalise their interiors, plus two car parks per home. The amenities include a 1.5-acre rooftop with a restaurant, sky bar, infinity-edge pool, spa, indoor and outdoor gyms and an amphitheatre; about an acre of podium amenities with pickleball and multipurpose courts, a mini golf course and a kids'' play area; and an 8,500 sq ft clubhouse. A show flat is ready to visit.', '["Clubhouse", "Gymnasium", "Sports Court", "Jogging Track", "Swimming Pool", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "Ready to Move"}, {"label": "MahaRERA ID", "value": "PR1262022600430"}, {"label": "Direct Starting Price", "value": "₹3.01 Cr"}, {"label": "Configurations", "value": "3.5 BHK, 4.5 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "NIBM, Pune"}]', '["MahaRERA: PR1262022600430", "0% Brokerage & Direct Builder Booking", "NIBM Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100030430', 17821, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqe85-503eob.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqeaa-7iwvbb.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqech-e17d1y.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqeej-4wv98n.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqegu-c9y79g.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqeix-a47dhx.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqel1-99ww1k.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqen0-dsxv4.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqepa-6w3yux.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqes7-c18mem.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqeuj-b0lcyw.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqewh-5touhd.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqeya-3gja4v.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7544fa37-d446-4c0f-b468-f46524919acb/gallery/mwevqf06-adcvbe.webp"]', 4.8, 100, 1, 0, 18.4767, 73.8937, '[{"type": "3.5 BHK", "carpetArea": "1100 sq.ft", "priceRange": "₹3.01 Cr"}, {"type": "4.5 BHK", "carpetArea": "1688 sq.ft", "priceRange": "₹3.69 Cr"}]', '["Clubhouse", "Gymnasium", "Sports Court", "Jogging Track", "Swimming Pool", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"question": "Where is YOO One located?", "answer": "YOO One is strategically located in prime NIBM, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in YOO One?", "answer": "Residences in YOO One start from ₹3.01 Cr - ₹3.69 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in YOO One?", "answer": "YOO One offers spacious 3.5 BHK, 4.5 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is YOO One MahaRERA approved?", "answer": "Yes, YOO One is officially registered under MahaRERA with registration number PR1262022600430. All approvals and certificates are verified."}, {"question": "What amenities are provided at YOO One?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Gymnasium, Sports Court, Jogging Track, Swimming Pool, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-codename-district-studio', 'Codename District Studio', 'codename-district-studio', 'b-a-lift-and-a-fire-lift', 'Tathawade', '₹26.36 L - ₹40.06 L', '₹26.36 L', '["Studio"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/3f30183c-dee9-474d-aa2e-283b5b964ca4/gallery/mwc1yu9z-32chh9.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/3f30183c-dee9-474d-aa2e-283b5b964ca4/gallery/mwc1yu9z-32chh9.webp', 'https://keystoneliv.com/public/uploads/property/QUSiXbX1yIv3u1F0efgnLHyJgKsJfu0DIDG1r7Wi.webp', '["https://keystoneliv.com/public/uploads/property/pliB773ywyiq6gouzMfqh80mTXjNcrEm9jmjmD0R.webp"]', 'Codename District Studio, sold as Smarto Tower, is a building of studio apartments in Pune. Each typical floor has nine studios along a 1.5 m passage, served by a lift and a fire lift, and the cost sheet lists nine studio types from 202 to 307 sq ft of carpet. Each studio has a room of about 10''6" wide and 14''7" to 18'' long, a toilet, a kitchenette counter and a small balcony. Agreement values run from ₹26.36 lakh for the 202 sq ft studio to ₹40.06 lakh for 307 sq ft. With 7% stamp duty, 1% GST and ₹31,000 registration, the totals are ₹28.78 lakh to ₹43.58 lakh; GST is charged at the 1% affordable-housing rate because each studio is small and priced under ₹45 lakh. The cost sheet we have was valid until 30 October 2026, so ask for the current one. The material does not give the site address, a MahaRERA registration number or a possession date; get all three before paying anything.', '["Clubhouse", "Gymnasium", "Swimming Pool", "Landscaped Garden", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "Verified Registered"}, {"label": "Direct Starting Price", "value": "₹26.36 L"}, {"label": "Configurations", "value": "Studio"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Tathawade, Pune"}]', '["MahaRERA: Registered", "0% Brokerage & Direct Builder Booking", "Tathawade Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100053120', 13050, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/3f30183c-dee9-474d-aa2e-283b5b964ca4/gallery/mwc1yu9z-32chh9.webp", "https://keystoneliv.com/public/uploads/property/udgWlmoH6ofCgYL184zKnPq8Zexr2l7fEoztyewT.webp", "https://keystoneliv.com/public/uploads/property/XuDMBetWz7JMao7EtAKipFvMdJLCxZvvdmU1XTf4.webp", "https://keystoneliv.com/public/uploads/property/ATBSWRDRKSRmbyRoiopB8HwrRQIgzAkuoILwvdpl.webp", "https://keystoneliv.com/public/uploads/property/Tma48Vkc54lmiZ0fVKe7BOE9Mekbtpx5PgEUl8pW.webp", "https://keystoneliv.com/public/uploads/property/Q39esXojW09bMJ6Mdrck23emKYk4oMPhiZEBA16j.webp"]', 4.8, 100, 1, 0, 18.6202, 73.751, '[{"type": "Studio Premium", "carpetArea": "646 sq.ft", "priceRange": "₹26.36 L"}, {"type": "Studio Grande", "carpetArea": "904 sq.ft", "priceRange": "₹40.06 L"}]', '["Clubhouse", "Gymnasium", "Swimming Pool", "Landscaped Garden", "Kids'' Play Area"]', '[{"question": "Where is Codename District Studio located?", "answer": "Codename District Studio is strategically located in prime Tathawade, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Codename District Studio?", "answer": "Residences in Codename District Studio start from ₹26.36 L - ₹40.06 L with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Codename District Studio?", "answer": "Codename District Studio offers spacious Studio apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Codename District Studio MahaRERA approved?", "answer": "Yes, Codename District Studio is officially registered under MahaRERA with registration number MahaRERA Registered. All approvals and certificates are verified."}, {"question": "What amenities are provided at Codename District Studio?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Gymnasium, Swimming Pool, Landscaped Garden, Kids'' Play Area, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-k-pune-bavdhan', 'K Pune', 'k-pune-bavdhan', 'b-tayal-corp', 'Bavdhan', '₹1.30 Cr - ₹1.98 Cr', '₹1.30 Cr', '["3 BHK", "4 BHK"]', 'Under Construction', 'Residential', '31 July 2029', 'https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxot5-2uipt2.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxot5-2uipt2.webp', 'https://keystoneliv.com/public/uploads/property/56RUcH2FcTi4nhHkw0gG3jrlWip1SBX7GquQbPQ9.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/1728477684130993331.png", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1761227063802632599.png"]', 'K Pune is a residential project by Tayal Corp under its K Better Homes brand at Sr. No. 45/1 and 45/2, Bavdhan, about 1.7 km from Chandni Chowk. Spread over 10 acres, it has seven towers of 21 storeys, a high street of 62 showrooms and landscape design by Landscape Tectonix of Bangkok. Phase II (buildings C, D and E) is registered with MahaRERA as P52100077301, with VMC Landmark Realty LLP as the promoter and a proposed completion date of 31 July 2029; Phase I is registered as P52100047630. The current cost sheet lists 3 BHK homes of 1,116 sq ft in buildings C and D and 1,251 and 1,361 sq ft in building E, and 4 BHK homes of 1,708 sq ft in building E, sizes that include the balconies. Agreement values start at ₹1.30 crore for a 1,116 sq ft 3 BHK and ₹1.975 crore for the 4 BHK, rising by ₹50,000 for each higher floor band. Amenities include a two-level cascading pool with a leisure pool, a clubhouse with a multipurpose hall and crèche, a multi-sport court, a kids'' play area, a step amphitheatre, terrace gardens, a co-working space, a reading space, a games zone and a sports and wellness area, with four levels of car parking. Homes get an Aluform structure, gypsum-finished walls, UPVC windows with mosquito mesh, solar-heated water and AC points in the living room and master bedroom.', '["Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Swimming Pool", "Landscaped Garden", "Covered Parking"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100077301"}, {"label": "Direct Starting Price", "value": "₹1.30 Cr"}, {"label": "Configurations", "value": "3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "31 July 2029"}, {"label": "Micro-Market", "value": "Bavdhan, Pune"}]', '["MahaRERA: P52100077301", "0% Brokerage & Direct Builder Booking", "Bavdhan Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100077301', 11648, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxot5-2uipt2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxov3-a4em43.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxoxm-b0ow5a.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxozu-avje2y.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxp24-8dki54.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxp4n-apctum.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxp6t-8rnxew.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxp8q-af7au1.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxpao-f5mpj2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxpck-3xdh1i.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxpej-8ww2b.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxpgr-c4dyml.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxpik-7gnm7q.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxpkf-abmj9p.webp"]', 4.8, 100, 1, 1, 18.5194, 73.7655, '[{"type": "3 BHK", "carpetArea": "1082 sq.ft", "priceRange": "₹1.30 Cr"}, {"type": "4 BHK", "carpetArea": "1840 sq.ft", "priceRange": "₹1.98 Cr"}]', '["Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Swimming Pool", "Landscaped Garden", "Covered Parking"]', '[{"question": "Where is K Pune located?", "answer": "K Pune is strategically located in prime Bavdhan, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in K Pune?", "answer": "Residences in K Pune start from ₹1.30 Cr - ₹1.98 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in K Pune?", "answer": "K Pune offers spacious 3 BHK, 4 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is K Pune MahaRERA approved?", "answer": "Yes, K Pune is officially registered under MahaRERA with registration number P52100077301. All approvals and certificates are verified."}, {"question": "What amenities are provided at K Pune?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Gymnasium, Library, Sports Court, Co-working Lounge, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-vtp-codename-never-before-west', 'VTP Codename Never Before West', 'vtp-codename-never-before-west', 'b-vtp-luxe', 'Mahalunge', '₹3.60 Cr - ₹4.82 Cr', '₹3.60 Cr', '["3 BHK", "4 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/d19a8bbe-9e37-4dbf-a9fc-76590fd6a791/gallery/mvhz2yqd-eaboou.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/d19a8bbe-9e37-4dbf-a9fc-76590fd6a791/gallery/mvhz2yqd-eaboou.webp', 'https://keystoneliv.com/public/uploads/property/3nwgH4M3KYSuaKfXTtDhRqNLtwWRw8zijkrDpzRL.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1761227063505755514.jpg", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/167643721815289486.jpg"]', 'VTP Codename Never Before West is an upcoming VTP Luxe project of duplex ''villas in the sky'' in VTP''s Township Codename Blue Waters at Mahalunge (Baner Next), West Pune, on the Mula riverfront beside Earth 1 by VTP Luxe. The tentative master plan shows four 36-storey towers with 18 lower and 18 upper villa levels and a landscaped riverside promenade. Homes come in four duplex types: Privé Villa and Privé Villa Max (3 BHK, about 1,835 and 2,044 sq ft carpet) and Aristo Villa and Aristo Villa Max (4 BHK with a servant room, about 2,453 and 2,531 sq ft). Every villa has a private lift, a double-height living room of about 21 ft, a puja area, marble flooring in the living and dining, a whirlpool bath in the master washroom and smart home controls. Each tower has a grand drop-off and a double-height entrance lobby, and every floor a double-height lift lobby. Amenities include a private clubhouse, swimming pool, steam and sauna, gym, putt-putt golf, box cricket, kids'' play area, a multipurpose court, a tennis court, an open-air event lawn and generous parking for large cars. Residents also get township facilities such as high-street shopping, a school, sports academies and landscaped zones. Indicative prices start at about ₹3.60 Cr. The project is in pre-launch: it is not yet registered with MahaRERA and no possession date has been announced.', '["Clubhouse", "Gymnasium", "Sports Court", "Swimming Pool", "24x7 Security", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "Verified Registered"}, {"label": "Direct Starting Price", "value": "₹3.60 Cr"}, {"label": "Configurations", "value": "3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Mahalunge, Pune"}]', '["MahaRERA: Registered", "0% Brokerage & Direct Builder Booking", "Mahalunge Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100051285', 19618, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/d19a8bbe-9e37-4dbf-a9fc-76590fd6a791/gallery/mvhz2yqd-eaboou.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d19a8bbe-9e37-4dbf-a9fc-76590fd6a791/gallery/mvhz2zbw-amtgjd.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d19a8bbe-9e37-4dbf-a9fc-76590fd6a791/gallery/mvhz2zwf-dua9bi.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d19a8bbe-9e37-4dbf-a9fc-76590fd6a791/gallery/mvhz30gl-g0whng.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d19a8bbe-9e37-4dbf-a9fc-76590fd6a791/gallery/mvhz310v-8kz768.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d19a8bbe-9e37-4dbf-a9fc-76590fd6a791/gallery/mvhz31lv-6tgpry.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d19a8bbe-9e37-4dbf-a9fc-76590fd6a791/gallery/mvhz32bx-ghg5gi.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/d19a8bbe-9e37-4dbf-a9fc-76590fd6a791/gallery/mvhz32w6-116jx4.webp"]', 4.8, 100, 1, 0, 18.571, 73.7501, '[{"type": "3 BHK", "carpetArea": "1076 sq.ft", "priceRange": "₹3.60 Cr"}, {"type": "4 BHK", "carpetArea": "1656 sq.ft", "priceRange": "₹4.82 Cr"}]', '["Clubhouse", "Gymnasium", "Sports Court", "Swimming Pool", "24x7 Security", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"question": "Where is VTP Codename Never Before West located?", "answer": "VTP Codename Never Before West is strategically located in prime Mahalunge, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in VTP Codename Never Before West?", "answer": "Residences in VTP Codename Never Before West start from ₹3.60 Cr - ₹4.82 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in VTP Codename Never Before West?", "answer": "VTP Codename Never Before West offers spacious 3 BHK, 4 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is VTP Codename Never Before West MahaRERA approved?", "answer": "Yes, VTP Codename Never Before West is officially registered under MahaRERA with registration number MahaRERA Registered. All approvals and certificates are verified."}, {"question": "What amenities are provided at VTP Codename Never Before West?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Gymnasium, Sports Court, Swimming Pool, 24x7 Security, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-arvaana', 'Arvaana', 'arvaana', 'b-kundan', 'Balewadi', '₹3.46 Cr - ₹3.65 Cr', '₹3.46 Cr', '["4 BHK", "4.5 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/8f30251d-2a71-4822-b50e-d56af0eef85d/gallery/mwev2ocq-dgorvp.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/8f30251d-2a71-4822-b50e-d56af0eef85d/gallery/mwev2ocq-dgorvp.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-monarque-hinjawadi-pune/Monarque_Master_Plan_27199f1f86.webp', '["https://keystoneliv.com/public/uploads/property/elwH47XcqSfm9Wr8ZOTnPUJV0L8hZ3Mzc0A6AnnL.webp", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1676437496754730563.jpg"]', 'Arvaana is a single residential tower in Balewadi, Pune, by Kundan Spaces, with only two homes on each floor. The tower rises three basements, a ground floor and 33 floors on a plot of about one acre, for 66 homes in all, and is open on the east and west sides. It is registered with MahaRERA as PR1260002600277, and the developer gives possession as December 2030. There are two home types. The 4.5 BHK homes measure 2,235 to 2,269 sq ft of total carpet area and have four bedrooms, a double-height family room, a sit-out, a servant''s room with its own toilet, a dry balcony and a store. The 4 BHK homes, 2,147 and 2,160 sq ft, have the same four bedrooms with a double-height sit-out in place of the family room. Floors are 11 ft high, each typical floor is served by four lifts, power backup covers the whole building and every home gets three car parks. Agreement values start at ₹3.46 Cr for the 4 BHK and ₹3.60 Cr for the 4.5 BHK; with stamp duty, registration and GST the packages are about ₹3.87 Cr to ₹4.09 Cr. The amenity floor at the top holds a temperature-controlled covered pool with a kids'' pool, a mini theatre, a co-working room, an indoor games room and a green lounge, and the roof has a party deck and a viewing deck. The site is on a 30 m road, about two minutes from Balewadi High Street, with Baner, Aundh, Pimpri-Chinchwad and the Mumbai-Bengaluru highway close by.', '["Gymnasium", "Co-working Lounge", "Swimming Pool", "Power Backup", "Landscaped Garden", "Covered Parking"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1260002600277"}, {"label": "Direct Starting Price", "value": "₹3.46 Cr"}, {"label": "Configurations", "value": "4 BHK, 4.5 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Balewadi, Pune"}]', '["MahaRERA: PR1260002600277", "0% Brokerage & Direct Builder Booking", "Balewadi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100020277', 16100, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/8f30251d-2a71-4822-b50e-d56af0eef85d/gallery/mwev2ocq-dgorvp.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/8f30251d-2a71-4822-b50e-d56af0eef85d/gallery/mwev2oej-40u8gr.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/8f30251d-2a71-4822-b50e-d56af0eef85d/gallery/mwev2oge-cb3pj4.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/8f30251d-2a71-4822-b50e-d56af0eef85d/gallery/mwev2oia-o47yz.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/8f30251d-2a71-4822-b50e-d56af0eef85d/gallery/mwev2okd-49qqvg.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/8f30251d-2a71-4822-b50e-d56af0eef85d/gallery/mwev2omb-e33qdv.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/8f30251d-2a71-4822-b50e-d56af0eef85d/gallery/mwev2oob-6p8mi8.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/8f30251d-2a71-4822-b50e-d56af0eef85d/gallery/mwev2oq8-d7mbyi.webp"]', 4.8, 100, 1, 1, 18.579, 73.7711, '[{"type": "4 BHK", "carpetArea": "1753 sq.ft", "priceRange": "₹3.46 Cr"}, {"type": "4.5 BHK", "carpetArea": "1781 sq.ft", "priceRange": "₹3.65 Cr"}]', '["Gymnasium", "Co-working Lounge", "Swimming Pool", "Power Backup", "Landscaped Garden", "Covered Parking"]', '[{"question": "Where is Arvaana located?", "answer": "Arvaana is strategically located in prime Balewadi, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Arvaana?", "answer": "Residences in Arvaana start from ₹3.46 Cr - ₹3.65 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Arvaana?", "answer": "Arvaana offers spacious 4 BHK, 4.5 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Arvaana MahaRERA approved?", "answer": "Yes, Arvaana is officially registered under MahaRERA with registration number PR1260002600277. All approvals and certificates are verified."}, {"question": "What amenities are provided at Arvaana?", "answer": "The development features world-class lifestyle amenities including Gymnasium, Co-working Lounge, Swimming Pool, Power Backup, Landscaped Garden, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-vtop-velesta', 'VTOP Velesta', 'vtop-velesta', 'b-vtop-spaces', 'Punawale', '₹81.00 L - ₹1.08 Cr', '₹81.00 L', '["2 BHK", "3 BHK"]', 'Ready to Move', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqikj-7c7wfj.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqikj-7c7wfj.webp', 'https://keystoneliv.com/public/uploads/property/Ptw9XmFBU5IeYvADN8ruLftUvTCTToYOMifOkh2x.webp', '["https://shapoorjirealestate.com/files/assets/jpegs/all_projects/wildernest/floorplans/4bhk-3.webp", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1734594164312359922.jpeg"]', 'VTOP Velesta is a new launch of 2 and 3 BHK homes in Punawale, Pune, by VTOP Spaces, on the 100 ft DP road that runs from Punawale towards Jambhe and Hinjawadi, about 600 m from the Mumbai-Bengaluru highway. It is registered with MahaRERA as PR1260002601596, with a RERA completion date of December 2030. On a 3.11-acre site it has two 29-storey towers with only six homes on each floor and four lifts, built with aluminium formwork (Mivan). There are three home sizes: a 2 BHK of 710 sq ft, a larger 2 BHK of 790 sq ft and a Smart 3 BHK of 952 sq ft, each figure being carpet area plus balcony. Every home has a dedicated pooja space, which the developer calls "BHK P". Prices start at ₹81 lakh for the 710 sq ft home, ₹90 lakh for the 790 sq ft home and ₹1.08 Cr for the 3 BHK on floors 1 to 10, rising by ₹3 lakh for each higher band of floors. The amenities shown in the layout are ready to use: a clubhouse, swimming pool, amphitheatre, play area, multipurpose court, box cricket and a Ganesh temple, along with an indoor games room, co-working space, library, creche, gym and guest rooms. A sample flat is ready to visit.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Sports Court", "Co-working Lounge", "Jogging Track"]', '[{"label": "Project Status", "value": "Ready to Move"}, {"label": "MahaRERA ID", "value": "PR1260002601596"}, {"label": "Direct Starting Price", "value": "₹81 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Punawale, Pune"}]', '["MahaRERA: PR1260002601596", "0% Brokerage & Direct Builder Booking", "Punawale Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100021596', 11408, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqikj-7c7wfj.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqimp-8i5hdz.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqioq-6y99us.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqiqp-31a1rl.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqisv-phq7a.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqiup-b8kl9z.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqiwm-u1vk3.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqiyi-8msfx3.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqj0l-edk7w1.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e5f322d4-5af4-4386-95f4-9858807fdc3d/gallery/mwevqj2h-ayt1zx.webp"]', 4.8, 100, 1, 0, 18.6234, 73.7381, '[{"type": "2 BHK", "carpetArea": "753 sq.ft", "priceRange": "₹81.00 L"}, {"type": "3 BHK", "carpetArea": "1024 sq.ft", "priceRange": "₹1.13 Cr - ₹1.46 Cr"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Sports Court", "Co-working Lounge", "Jogging Track"]', '[{"question": "Where is VTOP Velesta located?", "answer": "VTOP Velesta is strategically located in prime Punawale, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in VTOP Velesta?", "answer": "Residences in VTOP Velesta start from ₹81 L - ₹1.08 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in VTOP Velesta?", "answer": "VTOP Velesta offers spacious 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is VTOP Velesta MahaRERA approved?", "answer": "Yes, VTOP Velesta is officially registered under MahaRERA with registration number PR1260002601596. All approvals and certificates are verified."}, {"question": "What amenities are provided at VTOP Velesta?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Clubhouse, Gymnasium, Rainwater Harvesting, Library, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-18-magnitude', '18 Magnitude', '18-magnitude', 'b-gd-square-spaces', 'Punawale', '₹75.21 L - ₹1.23 Cr', '₹75.21 L', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/e15cd083-ae07-4325-a450-25bf2e8a9fe5/gallery/mvgyqfx3-c7yqyo.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/e15cd083-ae07-4325-a450-25bf2e8a9fe5/gallery/mvgyqfx3-c7yqyo.webp', 'https://keystoneliv.com/public/uploads/property/y23eQolQreeZxbOCvNAmA6XXJRnsVLTyeeJxCyN9.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/cu7T1exp3WjBAuIjjcAQclhBnDwVt0x1lCTQkwlS.webp", "https://keystoneliv.com/public/uploads/property/Yh0MhqcWjQpkHVPH3DjAEWr0zVrTSWadIZUjfemG.webp"]', '18 Magnitude is a residential project by GD Square Spaces at Punawale (Kate Wasti), Pune 411033, next to 18 Latitude Mall. It is planned as four towers of ground plus two podium levels plus 14 floors on about 2.35 acres, with 486 apartments listed under MahaRERA. Homes are 2 BHK with carpet areas of 685 to 857 sq ft and 3 BHK of 1,130 to 1,135 sq ft. Asking prices on property portals in October 2026 start at ₹75.21 L for a 2 BHK and ₹1.23 Cr for a 3 BHK; confirm the current price sheet with the sales team. Amenities listed include a gymnasium, kids'' play area, amphitheatre, yoga zone, jogging track, multipurpose play court, multipurpose lawn, co-working spaces and two-level parking. Nearby, 18 Latitude Mall is about 180 m away, the Mumbai-Bengaluru highway about 1 km and Akurdi railway station about 5 km. The pro