INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-tapovan-moshi', 'Tapovan', 'tapovan-moshi', 'b-life-spaces-realty', 'Moshi', '₹53.01 L - ₹68.95 L', '₹53.01 L', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '30 April 2029', 'https://punehome.in/storage/v1/object/public/project-media/projects/7961ad75-4a1a-477e-a5ef-29a8b2422b2c/gallery/mwevkifz-70hrok.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/7961ad75-4a1a-477e-a5ef-29a8b2422b2c/gallery/mwevkifz-70hrok.webp', 'https://www.vtprealty.in/images/project/project-details/flamante-by-vtp-luxe-kharadi-pune/Flamante_Master_Plan_7a81294c5d.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/CRFwCIeZDlS2wIt2FCjHtVPHQkc9Bh2S4PO5qe0k.webp", "https://keystoneliv.com/public/uploads/property/9bazfJfHebPTWOPKZhvlI5uteXcmfF57aTBYkICe.webp"]', 'Tapovan is a residential tower by Life Spaces Realty at Gat No. 253 on the Moshi–Alandi Road, near Vedshree Tapovan in Moshi, registered with MahaRERA as PM1260002501333 with a proposed completion date of 30 April 2029. It is a mixed-use building: shops on the ground floor and offices on the second, with 2 BHK and 3 BHK homes from the 1st to the 14th floor and refuge floors at the 7th and 12th. The 2 BHK homes measure 722 to 739 sq ft and cost ₹53.01 lakh to ₹54.16 lakh, and the 3 BHK homes measure 896 to 924 sq ft and cost ₹66.44 lakh to ₹68.95 lakh, as agreement values. The rooftop has a children''s play area, a toddlers'' play area, an open gym, a yoga deck, a party area, a gazebo and senior citizens'' sit-outs, a sunset deck and an acupressure walkway. The tower has a road-facing elevation with toughened glass, and homes get an earthquake-resistant RCC frame with AAC block walls, vitrified tiles throughout, a black pearl granite kitchen counter with a stainless steel sink, sliding aluminium windows with mosquito nets, solar hot water in the master bathroom and an AC point in the master bedroom. By the brochure, MIT College and the Shri Gajanan Maharaj temple are 5 minutes away, Moshi bus stop 8 minutes, and Alandi and DMart 10 minutes.', '["Gymnasium", "Covered Parking", "Kids'' Play Area", "Yoga Deck"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PM1260002501333"}, {"label": "Direct Starting Price", "value": "₹53.01 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "30 April 2029"}, {"label": "Micro-Market", "value": "Moshi, Pune"}]', '["MahaRERA: PM1260002501333", "0% Brokerage & Direct Builder Booking", "Moshi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100061333', 7342, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/7961ad75-4a1a-477e-a5ef-29a8b2422b2c/gallery/mwevkifz-70hrok.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7961ad75-4a1a-477e-a5ef-29a8b2422b2c/gallery/mwevkiig-dtwmm7.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7961ad75-4a1a-477e-a5ef-29a8b2422b2c/gallery/mwevkil1-1miqjy.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7961ad75-4a1a-477e-a5ef-29a8b2422b2c/gallery/mwevkio3-etppsp.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7961ad75-4a1a-477e-a5ef-29a8b2422b2c/gallery/mwevkiqg-gh7aqh.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7961ad75-4a1a-477e-a5ef-29a8b2422b2c/gallery/mwevkisp-8jfjpx.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/7961ad75-4a1a-477e-a5ef-29a8b2422b