INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-sai-kripa', 'Sai Kripa', 'sai-kripa', 'b-sai-nisarg-landmark', 'Ravet', '₹1.06 Cr - ₹1.09 Cr', '₹1.06 Cr', '["3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/609dca63-0f91-4e39-9c90-d3d97ab38d32/gallery/mvu255jt-g29cd4.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/609dca63-0f91-4e39-9c90-d3d97ab38d32/gallery/mvu255jt-g29cd4.webp', 'https://keystoneliv.com/public/liv-thumbs/640/uploads/property/iTt80ob6Q847pdqJo6QxQYX9jjyINihAoQvfFwpB.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/1728465989381290610.jpg"]', 'Sai Kripa by Krishna Rama Developer is a boutique residential building on Plot No. 415, Sector 29, Ganesh Nagar, Ravet, in the Pradhikaran area of Pimpri-Chinchwad, facing a 10.5 m road. Six residential floors hold just 36 homes, all 3 BHK and six to a floor: 1,053 sq ft homes (938 sq ft carpet plus 115 sq ft of balconies) and 1,085 sq ft homes (970 sq ft carpet plus 115 sq ft of balconies). Every home has three bedrooms, two of them with attached toilets, a living room opening onto a 12 ft balcony, a dining area and a kitchen with a dry balcony; the first-floor homes also open onto terraces. The rooftop is given over to amenities: a gym, a lawn, a yoga deck, a jogging track around the edge, a kids'' play area, an indoor games room and club house, and a multipurpose hall with a pantry and stage. Homes come with a 35 mm main door with a biometric lock, a video door bell, UPVC windows and balcony doors, 600 x 1200 mm vitrified tiles, Jaquar or Hindware fittings, geyser provision in every bathroom and AC provision in the living room and all bedrooms, and the building has high-speed lifts, an EV charging point and solar power generation. The eight shops on the ground floor are listed separately as Sai Kripa Commercial. D. Y. Patil Dnyanshanti School, PCCOE, DMart Ravet, Global Hospital, Akurdi railway station and the Pradhikaran gardens are about 5 minutes away, Chinchwad station about 12 and the old Mumbai-Pune highway and NH-48 about 10. Agreement values start from ₹1.06 crore for a 3 BHK (about ₹1.19 crore including GST, stamp duty and registration). Possession is planned for December 2030 (RERA completion date April 2031). MahaRERA PM1260002500965.', '["Clubhouse", "Gymnasium", "Jogging Track", "Landscaped Garden", "Covered Parking", "Kids'' Play Area", "Yoga Deck", "EV Charging"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PM1260002500965"}, {"label": "Direct Starting Price", "value": "₹1.06 Cr"}, {"label": "Configurations", "value": "3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Ravet, Pune"}]', '["MahaRERA: PM1260002500965", "0% Brokerage & Direct Builder Booking", "Ravet Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100060965', 10085, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/609dca63-0f91-4e39-9c90-d3d97ab38d32/gallery/mvu255jt-g29cd4.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/609dca63-0f91-4e39-9c90-d3d97ab38d32/gallery/mvu255me-9zzidi.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/609dca63-0f91-4e39-9c90-d3d97ab38d32/gallery/mvu255qg-dabobr.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/609dca63-0f91-4e39-9c90-d3d97ab38d32/gallery/mvu255s8-19mlw2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/60