INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-estofa-one-home', 'Estofa One Home', 'estofa-one-home', 'b-estofa-realty', 'Hinjewadi', '₹58.00 L - ₹1.00 Cr', '₹58.00 L', '["1 BHK", "2 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/dbe6d4d7-22d8-411f-ac8e-0c297a741dec/gallery/mvj3dtph-e0p9h9.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/dbe6d4d7-22d8-411f-ac8e-0c297a741dec/gallery/mvj3dtph-e0p9h9.webp', 'https://keystoneliv.com/public/uploads/property/AEV4Alkp45KgjGoLG3i2wOtoKOjfuY7T0aplVMNP.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/1728465957321177475.jpg", "https://keystoneliv.com/public/uploads/property/b8feIUVDt3lYstN0BMwcKjsjQarsPnZ4QBTS8zNj.webp"]', 'Estofa One Home is a pre-launch residential project by Estofa Realty, a Goyal & Planedge initiative, near Kasturi Chowk in Hinjawadi, Pune. It is planned as a single tower of 24 floors above two basements and a stilt level, with a recreational floor and a G+1 clubhouse set in landscaped open space. The project is built around compact 1 BHK suites of 416 sq ft total carpet area (386 sq ft RERA carpet plus a 30 sq ft balcony), each with a living and dining room, kitchen, bedroom, two toilets and a balcony. A limited series of combined 2 BHK flats joins two suites into one 839 sq ft home with a walk-in wardrobe and a 20-foot balcony. Pre-launch prices start at ₹58 lakh for a 1 BHK suite (₹58–60 lakh), and the combined 2 BHK flats are priced at about ₹1–1.06 crore. The location suits IT professionals and investors looking for rental demand: Shivaji Chowk metro station is about 2 minutes away, Infosys, Wipro and IBM about 5 minutes, and D-Mart, Xion Mall and Grand Highstreet within 3–4 minutes. The project is not yet RERA registered; the registration number and possession date will be added once they are announced.', '["Clubhouse", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "Verified Registered"}, {"label": "Direct Starting Price", "value": "₹58 L"}, {"label": "Configurations", "value": "1 BHK, 2 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Hinjewadi, Pune"}]', '["MahaRERA: Registered", "0% Brokerage & Direct Builder Booking", "Hinjewadi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100054899', 13942, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/dbe6d4d7-22d8-411f-ac8e-0c297a741dec/gallery/mvj3dtph-e0p9h9.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/dbe6d4d7-22d8-411f-ac8e-0c297a741dec/gallery/mvj3dufg-d93a6h.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgx4k-rh7tj.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgx29-ersahn.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgx0f-5agc9m.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6f179efc-b2df-49a3-b42b-b7335719d627/gallery/mvwhgwyj-30ap6p.webp"]', 4.8, 100, 1, 1, 18.5953, 73.7385, '[{"type": "1 BHK", "carpetArea": "430 sq.ft", "priceRange": "₹58.00 L"}, {"type": "2 BHK", "carpetArea": "719 sq.ft", "priceRange": "₹1.00 Cr"}]', '["Clubhouse", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking"]', '[{"question": "Where is Estofa One Home located?", "answer": "Estofa One Home is strategically located in prime Hinjewadi, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Estofa One Home?", "answer": "Residences in Estofa One Home start from ₹58 L - ₹1 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Estofa One Home?", "answer": "Estofa One Home offers spacious 1 BHK, 2 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Estofa One Home MahaRERA approved?", "answer": "Yes, Estofa One Home is officially registered under MahaRERA with registration number MahaRERA Registered. All approvals and certificates are verified."}, {"question": "What amenities are provided at Estofa One Home?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Power Backup, 24x7 Security, Landscaped Garden, Covered Parking, multi-tier security systems, and high-speed elevators."}]', '');
