INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-escala', 'Escala', 'escala', 'b-escala-developers', 'Kharadi', '₹2.46 Cr - ₹4.48 Cr', '₹2.46 Cr', '["Office"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/a5446ba3-bd84-43ba-9078-c482ca87653f/gallery/mwc2g7zr-3i7hkc.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/a5446ba3-bd84-43ba-9078-c482ca87653f/gallery/mwc2g7zr-3i7hkc.webp', 'https://keystoneliv.com/public/uploads/property/3dehuUq2Po5NML9mJlmIQO5xPl9IF2CTVSuFPjDO.webp', '["https://shapoorjirealestate.com/files/assets/jpegs/all_projects/wildernest/floorplans/4bhk-2.webp"]', 'Escala is a commercial building by Shroff Group and RHS Developments opposite EON IT Park in EON Free Zone, Kharadi, registered with MahaRERA as P52100045636, with Rising Prime Developers LLP as the promoter. It rises from two basements through a ground floor, a mezzanine and two parking podiums to ten office floors, with a glass and aluminium-panel facade, double-height showrooms at the base, a double-height entrance lobby with a waiting lounge, three lifts and a break-out area on the terrace. A typical office floor has seven offices: one of 1,171 sq ft, one of 2,133 sq ft, four of 899 sq ft and one of 1,557 sq ft of carpet. The current costing quotes ₹2.46 crore for a 1,171 sq ft office, ₹3.27 crore for 1,557 sq ft and ₹4.48 crore for 2,133 sq ft, including parking and infrastructure charges, with one or two car spaces; stamp duty, registration and legal fees are extra. Offices get vitrified flooring, glass entrance doors, power supplied to each unit and AC and fire-fighting provision, with generator backup. By the brochure, EON IT Park is 100 m away, the World Trade Centre 500 m, Seasons Mall and Amanora 4 km and Pune airport 8.4 km. MahaRERA''s proposed completion date was 31 March 2026.', '["Rainwater Harvesting", "Power Backup", "24x7 Security", "Covered Parking"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100045636"}, {"label": "Direct Starting Price", "value": "₹2.46 Cr"}, {"label": "Configurations", "value": "Office"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Kharadi, Pune"}]', '["MahaRERA: P52100045636", "0% Brokerage & Direct Builder Booking", "Kharadi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100045636', 27361, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/a5446ba3-bd84-43ba-9078-c482ca87653f/gallery/mwc2g7zr-3i7hkc.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a5446ba3-bd84-43ba-9078-c482ca87653f/gallery/mwc2g82p-edzkw3.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a5446ba3-bd84-43ba-9078-c482ca87653f/gallery/mwc2g854-3nrc46.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a5446ba3-bd84-43ba-9078-c482ca87653f/gallery/mwc2g87c-8mpr9o.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a5446ba3-bd84-43ba-9078-c482ca87653f/gallery/mwc2g89c-7kytyq.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a5446ba3-bd84-43ba-9078-c482ca87653f/gallery/mwc2g8bb-fgieae.webp"]', 4.8, 100, 1, 1, 18.5476, 73.9372, '[{"type": "Office Premium", "carpetArea": "622 sq.ft", "priceRange": "₹2.46 Cr"}, {"type": "Office Grande", "carpetArea": "870 sq.ft", "priceRange": "₹4.48 Cr"}]', '["Rainwater Harvesting", "Power Backup", "24x7 Security", "Covered Parking"]', '[{"question": "Where is Escala located?", "answer": "Escala is strategically located in prime Kharadi, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Escala?", "answer": "Residences in Escala start from ₹2.46 Cr - ₹4.48 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Escala?", "answer": "Escala offers spacious Office apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Escala MahaRERA approved?", "answer": "Yes, Escala is officially registered under MahaRERA with registration number P52100045636. All approvals and certificates are verified."}, {"question": "What amenities are provided at Escala?", "answer": "The development features world-class lifestyle amenities including Rainwater Harvesting, Power Backup, 24x7 Security, Covered Parking, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-vanaha-verdant', 'Vanaha Verdant', 'vanaha-verdant', 'b-shapoorji-pallonji', 'Lavale', '₹1.05 Cr - ₹1.55 Cr', '₹1.05 Cr', '["2 BHK", "3 BHK", "Jodi"]', 'New Launch', 'Residential', '31 July 2032', 'https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewan2f-5n6nc0.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewan2f-5n6nc0.webp', 'https://keystoneliv.com/public/uploads/property/pkJxGd1gHFGu7mmQK9QruOkJwCN6UjcR7yv24TqQ.webp', '["https://keystoneliv.com/public/uploads/property/image - 2026-05-19T152510.033.webp", "https://keystoneliv.com/public/uploads/property/LlTxJHtDg73ynmCPMzwDQD1pDvn5dQpm7OIdijJ7.webp", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1676437625251825814.jpg"]', 'Vanaha Verdant is a residential project by Shapoorji Pallonji in Vanaha, the group''s integrated township of about 1,000 acres off the Pune–Bengaluru highway near the Oxford Golf Resort, in Lavale village (Mulshi), marketed as Vanaha Bavdhan. Towers 3 and 4 have just launched; MahaRERA registers them as Vanaha Verdant Elm I & II (PR1260002500649), with Image Realty Private Limited as the promoter and a proposed completion date of 31 July 2032. The project has four towers of 30 to 31 floors above stilts on about 6.5 acres, around a forest garden of about 1.5 acres planted with native species. Homes are 2 BHK of 868 and 874 sq ft from ₹1.05 crore, 3 BHK of 1,171 sq ft from ₹1.55 crore, and 2+2 BHK Jodi homes of 1,736 sq ft from ₹2.20 crore, laid out as 3.5 or 4.5 BHK with four decks. The 45-plus amenities include a 25 m lap pool, a kids'' pool and spa pool, a watch tower, a 500 m elevated cycling track, a breezeway, a party lawn, a barbecue court and outdoor work desks, with a jogging track, a multiplay court, a futsal court, a yoga lawn and a half basketball court on the roof of the multi-level car park. A 64 m retail promenade lines the entrance. The township includes a 150-acre golf course, and FLAME University and Symbiosis International University''s Lavale campus are nearby.', '["Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "Landscaped Garden", "Covered Parking", "Kids'' Play Area", "Yoga Deck"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "PR1260002500649"}, {"label": "Direct Starting Price", "value": "₹1.05 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, Jodi"}, {"label": "Possession Date", "value": "31 July 2032"}, {"label": "Micro-Market", "value": "Lavale, Pune"}]', '["MahaRERA: PR1260002500649", "0% Brokerage & Direct Builder Booking", "Lavale Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100060649', 12096, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewan2f-5n6nc0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewan66-2djfmm.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewana0-d55s20.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewandz-fxfthj.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewang6-9klq2p.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewanii-cicmml.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewankq-cti29j.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewanmw-1nhaak.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewanoz-2cjtpl.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewanr0-3n7gbs.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3f50d75f-ca48-494b-946f-240dd8c3adf7/gallery/mwewantb-393csr.webp"]', 4.8, 100, 1, 0, 18.5453, 73.7101, '[{"type": "2 BHK", "carpetArea": "748 sq.ft", "priceRange": "₹1.05 Cr - ₹1.31 Cr"}, {"type": "3 BHK", "carpetArea": "1019 sq.ft", "priceRange": "₹1.47 Cr - ₹1.89 Cr"}, {"type": "Jodi", "carpetArea": "601 sq.ft", "priceRange": "₹1.55 Cr"}]', '["Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "Landscaped Garden", "Covered Parking", "Kids'' Play Area", "Yoga Deck"]', '[{"question": "Where is Vanaha Verdant located?", "answer": "Vanaha Verdant is strategically located in prime Lavale, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Vanaha Verdant?", "answer": "Residences in Vanaha Verdant start from ₹1.05 Cr - ₹1.55 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Vanaha Verdant?", "answer": "Vanaha Verdant offers spacious 2 BHK, 3 BHK, Jodi apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Vanaha Verdant MahaRERA approved?", "answer": "Yes, Vanaha Verdant is officially registered under MahaRERA with registration number PR1260002500649. All approvals and certificates are verified."}, {"question": "What amenities are provided at Vanaha Verdant?", "answer": "The development features world-class lifestyle amenities including Sports Court, Co-working Lounge, Jogging Track, Swimming Pool, Landscaped Garden, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-kunal-manthan', 'Kunal Manthan', 'kunal-manthan', 'b-kunal-landmarks', 'Rahatani', '₹85.00 L', '₹85.00 L', '["2 BHK", "2.5 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/06e74847-186b-4b70-886e-b1e9e8ea59c6/gallery/mvjcr8zz-3mph1i.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/06e74847-186b-4b70-886e-b1e9e8ea59c6/gallery/mvjcr8zz-3mph1i.webp', 'https://keystoneliv.com/public/uploads/property/AEV4Alkp45KgjGoLG3i2wOtoKOjfuY7T0aplVMNP.webp', '["https://keystoneliv.com/public/uploads/property/3nwgH4M3KYSuaKfXTtDhRqNLtwWRw8zijkrDpzRL.webp", "https://keystoneliv.com/public/uploads/property/JRdpFkkMaBqWUV91UsxTA5PmT4jrWULe6bfbdGr3.webp", "https://keystoneliv.com/public/uploads/property/DqZiV2LxEwtgObiiMdb3ecrNCjeh3UtIWNZLlTtx.webp"]', 'Kunal Manthan is a residential project by Kunal Landmarks in Rahatani, Pune. It is a 14-storey tower on a 38 guntha (about 0.95 acre) land parcel, with three levels of parking, 11 apartments on each floor, 4 high-speed elevators and 2 staircases, and open views on three sides. The tower offers 2 BHK homes of 675, 725 and 750 sq ft, a compact 2.5 BHK of 845 sq ft and 3 BHK homes of 1,012 and 1,035 sq ft (total area including balconies). Amenities are spread over the podium and the rooftop: a grand clubhouse, indoor and open gym, co-working space, yoga and meditation zone, jogging track, children''s play area, badminton court, box cricket, party lawn, gazebo seating, an indoor games hall and a society office. Solar PV panels generate renewable energy for the common areas. The developer indicates possession within 2 years. Prices are on request, and the MahaRERA registration number will be added once it is available.', '["Clubhouse", "Gymnasium", "Sports Court", "Co-working Lounge", "Jogging Track", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1260002601428"}, {"label": "Direct Starting Price", "value": "Price on Request"}, {"label": "Configurations", "value": "2 BHK, 2.5 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Rahatani, Pune"}]', '["MahaRERA: PR1260002601428", "0% Brokerage & Direct Builder Booking", "Rahatani Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100021428', 8200, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/06e74847-186b-4b70-886e-b1e9e8ea59c6/gallery/mvjcr8zz-3mph1i.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/06e74847-186b-4b70-886e-b1e9e8ea59c6/gallery/mvjcr9rp-3jbwpr.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/06e74847-186b-4b70-886e-b1e9e8ea59c6/gallery/mvjcrate-dd71an.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/06e74847-186b-4b70-886e-b1e9e8ea59c6/gallery/mvjcrbl2-8xmpo4.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/06e74847-186b-4b70-886e-b1e9e8ea59c6/gallery/mvjcrc8n-4kl8s5.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/06e74847-186b-4b70-886e-b1e9e8ea59c6/gallery/mvjcrd5k-e16wg9.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/06e74847-186b-4b70-886e-b1e9e8ea59c6/gallery/mvjcrdtc-6z71ug.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/06e74847-186b-4b70-886e-b1e9e8ea59c6/gallery/mvjcregh-2xb2xw.webp", "https://punehome.in/stora