INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-kings-grace', 'King''s Grace', 'kings-grace', 'b-krishna-rrealty', 'Rahatani', '₹1.15 Cr - ₹1.69 Cr', '₹1.15 Cr', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/92685a0d-2bbc-4399-bf68-87ff551065bc/gallery/mvfck3l0-9s42q5.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/92685a0d-2bbc-4399-bf68-87ff551065bc/gallery/mvfck3l0-9s42q5.webp', 'https://keystoneliv.com/public/uploads/property/AEV4Alkp45KgjGoLG3i2wOtoKOjfuY7T0aplVMNP.webp', '["https://keystoneliv.com/public/uploads/property/J9Ip37z2Wzgx196NQyLrRvd22LBOy1PXHkFuPfuN.webp", "https://keystoneliv.com/public/uploads/property/LlTxJHtDg73ynmCPMzwDQD1pDvn5dQpm7OIdijJ7.webp"]', 'King''s Grace by Krishna Rrealty is a new residential address in Rahatani, near Kokane Chowk on the Pimple Saudagar–Rahatani border in Pimpri-Chinchwad. It has two wings: B wing with 2 BHK homes of 781 and 809 sq ft, and A wing with 3 BHK homes of 1,095 to 1,148 sq ft (usable area, i.e. carpet plus balcony and terrace; RERA carpet 704–1,009 sq ft). Showrooms sit at ground level and parking is on two basement levels, with one covered car park for every home. The 3 BHK homes on the typical floors include a walk-in wardrobe, and the building has a gym and a kids'' play area. Sparsh Hospital, Synergy Heart Institute and SNBP International School are about 1 km away, Kokane Chowk and Shivar Chowk within 1.5 km, the Aundh–Ravet BRTS road about 2 km and Wakad about 4 km, with Hinjewadi Phase 1 about 7 km away. Agreement values start from ₹1.15 Cr for a 2 BHK (₹14,700 per sq ft of usable area) on a construction-linked payment plan with a ₹5 lakh booking amount. MahaRERA PR1260002602278; RERA completion date December 2029.', '["CCTV Surveillance", "Gymnasium", "Rainwater Harvesting", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1260002602278"}, {"label": "Direct Starting Price", "value": "₹1.15 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Rahatani, Pune"}]', '["MahaRERA: PR1260002602278", "0% Brokerage & Direct Builder Booking", "Rahatani Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100022278', 14700, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/92685a0d-2bbc-4399-bf68-87ff551065bc/gallery/mvfck3l0-9s42q5.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/92685a0d-2bbc-4399-bf68-87ff551065bc/gallery/mvfck5m6-9fhkmx.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/92685a0d-2bbc-4399-bf68-87ff551065bc/gallery/mvfck83x-acahjh.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/92685a0d-2bbc-4399-bf68-87ff551065bc/gallery/mvfcka1x-7x5bl1.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a6dc0c88-7cbe-43d4-9bc3-4158339ebef6/gallery/mvghnc3y-3uy8yq.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a6dc0c88-7cbe-43d4-9bc3-4158339ebef6/gallery/mvghnbi8-2g2sm4.webp"]', 4.8, 100, 1, 0, 18.6059, 73.7915, '[{"type": "2 BHK", "carpetArea": "722 sq.ft", "priceRange": "₹1.15 Cr - ₹1.44 Cr"}, {"type": "3 BHK", "carpetArea": "1118 sq.ft", "priceRange": "₹1.69 Cr"}]', '["CCTV Surveillance", "Gymnasium", "Rainwater Harvesting", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"question": "Where is King''s Grace located?", "answer": "King''s Grace is strategically located in prime Rahatani, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in King''s Grace?", "answer": "Residences in King''s Grace start from ₹1.15 Cr - ₹1.69 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in King''s Grace?", "answer": "King''s Grace offers spacious 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is King''s Grace MahaRERA approved?", "answer": "Yes, King''s Grace is officially registered under MahaRERA with registration number PR1260002602278. All approvals and certificates are verified."}, {"question": "What amenities are provided at King''s Grace?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Gymnasium, Rainwater Harvesting, Power Backup, 24x7 Security, multi-tier security systems, and high-speed elevators."}]', '');
