INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-ra-urbania', 'RA Urbania', 'ra-urbania', 'b-croissance-buildcon', 'Ravet', '₹78.00 L - ₹96.82 L', '₹78.00 L', '["2 BHK", "3 BHK"]', 'Ready to Move', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/3302b32c-7d28-4e95-8ff5-6f646428c415/gallery/mvgyqu7b-6afjkz.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/3302b32c-7d28-4e95-8ff5-6f646428c415/gallery/mvgyqu7b-6afjkz.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-altitude-wakad-pune/Altitude_Master_Plan_2a71829c4d.webp', '["https://keystoneliv.com/public/uploads/property/tJoMXAcz93Q3AzNSRbGl2rqXifgKmka5ixZgZ61W.webp", "https://keystoneliv.com/public/uploads/property/c5iyPCgaCqPe2H7UgjtMuIlxz0gkapjWv7U5nlzE.webp"]', 'RA Urbania is a residential project in Ganesh Nagar, Ravet, Pimpri-Chinchwad, Pune 412101, on Survey No. 148 near Shinde Vasti and Pipeline Road. It is developed by Croissance Buildcon, a Pune partnership firm. The project is a single tower of 2 parking levels, ground and 17 floors, with 8 flats per floor, on a plot of about 0.74 acre (2,999 sq m as filed with MahaRERA). Homes are 2 BHK with carpet areas of 742 and 772 sq ft and 3 BHK of about 993 sq ft. Listings quote about Rs 78 lakh all-inclusive for the 772 sq ft 2 BHK and about Rs 96.82 lakh for the 3 BHK, and the project is described as built and ready to move in. Amenities listed include a swimming pool, gymnasium, jogging track, garden, yoga deck, amphitheatre, library and 24x7 security with CCTV. Listings place S B Patil Public School about 0.8 km away, Venkatesh Hospital about 0.9 km, D-Mart about 2.5 km and Akurdi railway station about 3.4 km. The project is registered with MahaRERA under number P52100050429. Contact the Pune Home team for availability and a site visit.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Sports Court", "Co-working Lounge", "Jogging Track"]', '[{"label": "Project Status", "value": "Ready to Move"}, {"label": "MahaRERA ID", "value": "P52100050429"}, {"label": "Direct Starting Price", "value": "₹78 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Ravet, Pune"}]', '["MahaRERA: P52100050429", "0% Brokerage & Direct Builder Booking", "Ravet Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100050429', 10512, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/3302b32c-7d28-4e95-8ff5-6f646428c415/gallery/mvgyqu7b-6afjkz.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3302b32c-7d28-4e95-8ff5-6f646428c415/gallery/mvgyquky-9evu53.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxpao-f5mpj2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxpck-3xdh1i.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxpej-8ww2b.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6fea60cd-7889-4d14-94ee-e56af9f959a1/gallery/mweuxpgr-c4dyml.webp"]', 4.8, 100, 1, 0, 18.6469, 73.7452, '[{"type": "2 BHK", "carpetArea": "697 sq.ft", "priceRange": "₹78 L - ₹98 L"}, {"type": "3 BHK", "carpetArea": "982 sq.ft", "priceRange": "₹96.82 L"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Sports Court", "Co-working Lounge", "Jogging Track"]', '[{"question": "Where is RA Urbania located?", "answer": "RA Urbania is strategically located in prime Ravet, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in RA Urbania?", "answer": "Residences in RA Urbania start from ₹78 L - ₹96.82 L with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in RA Urbania?", "answer": "RA Urbania offers spacious 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is RA Urbania MahaRERA approved?", "answer": "Yes, RA Urbania is officially registered under MahaRERA with registration number P52100050429. All approvals and certificates are verified."}, {"question": "What amenities are provided at RA Urbania?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Clubhouse, Gymnasium, Rainwater Harvesting, Library, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-sky-world', 'Sky World', 'sky-world', 'b-siyaram-developers', 'Wakad', '₹79.20 L - ₹1.51 Cr', '₹79.20 L', '["1 RK", "2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/a411bc50-3b7f-4951-9ae1-80c0863adb52/gallery/mvgyrjr4-c3kus9.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/a411bc50-3b7f-4951-9ae1-80c0863adb52/gallery/mvgyrjr4-c3kus9.webp', 'https://www.vtprealty.in/images/project/project-details/flamante-by-vtp-luxe-kharadi-pune/Flamante_Master_Plan_7a81294c5d.webp', '["https://keystoneliv.com/public/uploads/property/NdXJ20cXwaIEvbNcLMqICBTXnHFUDHwqN8v3pGx2.png", "https://keystoneliv.com/public/uploads/property/H6VFHKV0W11g8lU1zZ673X0MpRc8hR1uyGujlBwz.webp", "https://keystoneliv.com/public/uploads/property/EVDSKyNRMmSSf7oqrNNRpKJnAT7ktaXYDp3VM2Yf.webp"]', 'Sky World is a residential project by Siyaram Developers on Pink City Road near EuroSchool in Wakad, Pune 411057. It is registered with MahaRERA under P52100052484 on about 1.58 acres, with four buildings and 64 apartments filed in the registration. The homes are 2 BHK and 3 BHK layouts, with 2 BHK carpet areas from about 549 to 879 sq ft and 3 BHK carpet areas of about 1,058 to 1,068 sq ft; a few compact 1 RK units are also listed. Listed amenities include a landscaped garden, kids play area, gymnasium, jogging track, covered parking, CCTV surveillance, power backup for common areas and rainwater harvesting. Asking prices on property portals in October 2026 start at ₹79.2 L for a 2 BHK and ₹1.51 Cr for a 3 BHK; confirm the current price sheet with the sales team. The MahaRERA certificate is valid from 8 September 2023 to 18 October 2026, which is also the proposed possession date, so buyers should check the latest completion status on the MahaRERA website before booking. Book a site visit through Pune Home.', '["CCTV Surveillance", "Gymnasium", "Rainwater Harvesting", "Jogging Track", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100052484"}, {"label": "Direct Starting Price", "value": "₹79.20 L"}, {"label": "Configurations", "value": "1 RK, 2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Wakad, Pune"}]', '["MahaRERA: P52100052484", "0% Brokerage & Direct Builder Booking", "Wakad Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100052484', 24520, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/a411bc50-3b7f-4951-9ae1-80c0863adb52/gallery/mvgyrjr4-c3kus9.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a411bc50-3b7f-4951-9ae1-80c0863adb52/gallery/mvgyrksi-7mwzph.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/33dcd66b-17e3-45d1-9b85-289549670757/gallery/mtppxbb3-d52iec.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/33dcd66b-17e3-45d1-9b85-289549670757/gallery/mtppx9v0-7fopcl.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/4935e56d-e052-4b3a-ba34-d00862501f24/gallery/mul8321h-imtlk.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/4935e56d-e052-4b3a-ba34-d00862501f24/gallery/mul8305v-dzap26.webp"]', 4.8, 100, 1, 1, 18.6016, 73.7645, '[{"type": "1 RK", "carpetArea": "562 sq.ft", "priceRange": "₹79.20 L"}, {"type": "2 BHK", "carpetArea": "709 sq.ft", "priceRange": "₹79 L - ₹99 L"}, {"type": "3 BHK", "carpetArea": "1007 sq.ft", "priceRange": "₹1.51 Cr"}]', '["CCTV Surveillance", "Gymnasium", "Rainwater Harvesting", "Jogging Track", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking"]', '[{"question": "Where is Sky World located?", "answer": "Sky World is strategically located in prime Wakad, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Sky World?", "answer": "Residences in Sky World start from ₹79.20 L - ₹1.51 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Sky World?", "answer": "Sky World offers spacious 1 RK, 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Sky World MahaRERA approved?", "answer": "Yes, Sky World is officially registered under MahaRERA with registration number P52100052484. All approvals and certificates are verified."}, {"question": "What amenities are provided at Sky World?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Gymnasium, Rainwater Harvesting, Jogging Track, Power Backup, multi-tier security systems, and high-speed elevators."}]', '');
