INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-city-one-panache-2-0', 'City One Panache 2.0', 'city-one-panache-2-0', 'b-city-one', 'Ravet', '₹1.54 Cr - ₹2.25 Cr', '₹1.54 Cr', '["3 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/24c463c6-f0f4-4e2f-9bd9-efb3b864ab1a/gallery/mwbw9wx3-byrg1y.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/24c463c6-f0f4-4e2f-9bd9-efb3b864ab1a/gallery/mwbw9wx3-byrg1y.webp', 'https://keystoneliv.com/public/uploads/property/dUBwkAaG7EfnFh6NDymuNR5UNLD1e3QTLxUcN08I.webp', '["https://keystoneliv.com/public/uploads/property/image (85).webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/hBhWq7z67MCde6MvvhDvmu4lEKeJpH2zLkqJlrml.webp"]', 'City One Panache 2.0 is a 26-storey residential tower by City One in Sector 29 of the Pradhikaran area of Ravet, Pimpri-Chinchwad, registered with MahaRERA as PM1260002600510 (promoter Cityone Skycastle LLP). It offers 3 BHK homes, which the developer calls Sky Suites, of 1,300 sq ft and 4 BHK suites of 1,624 and 1,635 sq ft, marketed with private elevators and 270-degree views. Prices start at ₹1.54 crore for a 3 BHK and ₹2.19 crore for a 4 BHK. The tower rises above a glass-fronted podium of shops and offices, sold separately as City One Panache Commercial. The developer''s amenity list includes a swimming pool, a breezy gymnasium, a yoga, Zumba and aerobics zone, a barbecue lounge, a kids'' play area, a multipurpose court and a senior citizens'' zone. The developer puts EuroKids preschool 2 minutes away, Ojas Multispeciality Hospital in Ravet 3 minutes, the Sant Tukaram Maharaj bridge 4 minutes, PCCOE and Akurdi railway station 5 minutes, Oxycare Superspeciality Hospital 6 minutes, Orchids The International School 10 minutes, and Aditya Birla Hospital and Lokmanya Hospital Chinchwad about 15 minutes away. Possession is planned for December 2028.', '["Gymnasium", "Sports Court", "Swimming Pool", "Kids'' Play Area", "Yoga Deck"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PM1260002600510"}, {"label": "Direct Starting Price", "value": "₹1.54 Cr"}, {"label": "Configurations", "value": "3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Ravet, Pune"}]', '["MahaRERA: PM1260002600510", "0% Brokerage & Direct Builder Booking", "Ravet Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100020510', 11846, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/24c463c6-f0f4-4e2f-9bd9-efb3b864ab1a/gallery/mwbw9wx3-byrg1y.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/24c463c6-f0f4-4e2f-9bd9-efb3b864ab1a/gallery/mwbw9wz1-d50fhj.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/24c463c6-f0f4-4e2f-9bd9-efb3b864ab1a/gallery/mwbw9x0w-b1ys1b.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/24c463c6-f0f4-4e2f-9bd9-efb3b864ab1a/gallery/mwbw9x34-dohwei.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/24c463c6-f0f4-4e2f-9bd9-efb3b864ab1a/gallery/mwbw9x58-75b7av.webp"]', 4.8, 100, 1, 0, 18.6509, 73.7431, '[{"type": "3 BHK", "carpetArea": "1077 sq.ft", "priceRange": "₹1.54 Cr"}, {"type": "4 BHK", "carpetArea": "1655 sq.ft", "priceRange": "₹2.25 Cr"}]', '["Gymnasium", "Sports Court", "Swimming Pool", "Kids'' Play Area", "Yoga Deck"]', '[{"question": "Where is City One Panache 2.0 located?", "answer": "City One Panache 2.0 is strategically located