INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-santiago-sunrise', 'Santiago Sunrise', 'santiago-sunrise', 'b-santiago-realty', 'Aundh', '₹80.00 L - ₹1.07 Cr', '₹80.00 L', '["2 BHK", "3 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/5ee883dd-7d70-442e-8d8a-f747c2418338/gallery/mvghm8cf-4dt4kg.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/5ee883dd-7d70-442e-8d8a-f747c2418338/gallery/mvghm8cf-4dt4kg.webp', 'https://keystoneliv.com/public/uploads/property/pkJxGd1gHFGu7mmQK9QruOkJwCN6UjcR7yv24TqQ.webp', '["https://keystoneliv.com/public/uploads/property/evR9QMKWYPJ7mfXswMgWcM03r9vtzVYrhTLN1Yn2.png", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/17345941441006008973.jpeg"]', 'Santiago Sunrise is a residential project by Santiago Realty (Santiago Realtech Ventures) on Survey No. 12/1, Plot No. 74 in Old Sangvi, Pune 411027, which the developer also describes as New Aundh. It is a single-tower development on about 0.28 acre, launched in October 2024. The developer lists 2 BHK homes of about 683 and 693 sq ft and 3 BHK homes of about 908 and 991 sq ft, designed to be Vastu-compliant with covered parking for each flat, large balconies and three-side open views. Listed starting prices are around Rs 80 lakh for 2 BHK and Rs 1.07 crore for 3 BHK; please contact the Pune Home sales team for the current price sheet. Amenities include a gymnasium, kids'' play area, yoga area, jogging track, landscaped garden, rainwater harvesting, CCTV surveillance, 24x7 security and power backup. Listings place Dolphins International School and Dr Khandge Hospital about 300 m away, a park about 600 m, and Dapodi metro station about 2.5 km away. The project is registered under MahaRERA number P52100077792 with a possession date of December 2027.', '["CCTV Surveillance", "Gymnasium", "Rainwater Harvesting", "Jogging Track", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "P52100077792"}, {"label": "Direct Starting Price", "value": "₹80 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Aundh, Pune"}]', '["MahaRERA: P52100077792", "0% Brokerage & Direct Builder Booking", "Aundh Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100077792', 11713, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/5ee883dd-7d70-442e-8d8a-f747c2418338/gallery/mvghm8cf-4dt4kg.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5ee883dd-7d70-442e-8d8a-f747c2418338/gallery/mvghmaa9-1l40s9.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5ee883dd-7d70-442e-8d8a-f747c2418338/gallery/mvghmc5i-d7jzaw.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5ee883dd-7d70-442e-8d8a-f747c2418338/gallery/mvghmdjz-avxlwr.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/c0b41260-7975-4e4d-9645-a646df00ee15/gallery/msd7tien-cydnt3.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/c0b41260-7975-4e4d-9645-a646df00ee15/gallery/msd7tgn3-4id07l.webp"]', 4.8, 100, 1, 0, 18.5532, 73.812, '[{"type": "2 BHK", "carpetArea": "728 sq.ft", "priceRange": "₹80.00 L"}, {"type": "3 BHK", "carpetArea": "1072 sq.ft", "priceRange": "₹1.07 Cr"}]', '["CCTV Surveillance", "Gymnasium", "Rainwater Harvesting", "Jogging Track", "Power Backup", "24x7 Security