INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-tulip-infinity-avana', 'Tulip Infinity Avana', 'tulip-infinity-avana', 'b-tulip-group', 'Punawale', '₹1.04 Cr - ₹2.20 Cr', '₹1.04 Cr', '["2 BHK", "3 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc6xbx-17wr8.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc6xbx-17wr8.webp', 'https://keystoneliv.com/public/uploads/property/dVV2cx7KeQONobjzrxtwJm7Z6viFIsjkYb5lBMOc.webp', '["/images/projects/anp-autograph/floor-plan-2bhk.webp", "https://keystoneliv.com/public/uploads/property/tD46gBsL9QvyzIsy8OQPgFbjZ6g6kTlrPFfXPod3.webp", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1774955201963424212.png"]', 'Tulip Infinity Avana is a residential project by Tulip Group, now Varma Corp, on the Aundh-Ravet BRTS Road at Vishnu Dev Nagar, Punawale, on the Tathawade side of Pimpri-Chinchwad, Pune 411033. It is planned as four high-rise towers of about 33 floors on roughly 3.2 acres. Homes are 2, 3 and 4 BHK with carpet areas of about 796 to 938 sq ft, 1,045 to 1,266 sq ft and 1,485 sq ft. The developer publishes all-inclusive estimates from about 1.04 crore for a 2 BHK, 1.40 crore for a 3 BHK and 2.20 crore for a 4 BHK; confirm the current cost sheet. Amenities include two swimming pools, a 40-seat mini theatre, a multi-zone gymnasium, rooftop co-working spaces, a library, a half basketball court and landscaped gardens. Listing sites place Gagangiri Hospital about 0.5 km away, Jeevan Shikshan Vidya Mandir school 0.6 km and the Mumbai-Bangalore highway about 1.5 km. The project is registered with MahaRERA under P52100047662 with possession due in December 2026.', '["Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "Landscaped Garden", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100047662"}, {"label": "Direct Starting Price", "value": "₹1.04 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Punawale, Pune"}]', '["MahaRERA: P52100047662", "0% Brokerage & Direct Builder Booking", "Punawale Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100047662', 13065, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc6xbx-17wr8.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc6ya2-436ell.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc6z3a-crr5dc.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc708k-g7zxe2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc711g-3uxqs7.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc71sv-17zt21.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc72ju-1oylua.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc73gb-cyp544.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc74yk-ag8xbh.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc75u9-85j08m.webp"]', 4.8, 100, 1, 0, 18.6242, 73.7375, '[{"type": "2 BHK", "carpetArea": "736 sq.ft", "priceRange": "₹1.04 Cr - ₹1.30 Cr"}, {"type": "3 BHK", "carpetArea": "1003 sq.ft", "priceRange": "₹1.46 Cr - ₹1.87 Cr"}, {"type": "4 BHK", "carpetArea": "1826 sq.ft", "priceRange": "₹2.20 Cr"}]', '["Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "Landscaped Garden", "Kids'' Play Area"]', '[{"question": "Where is Tulip Infinity Avana located?", "answer": "Tulip Infinity Avana is strategically located in prime Punawale, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Tulip Infinity Avana?", "answer": "Residences in Tulip Infinity Avana start from ₹1.04 Cr - ₹2.20 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Tulip Infinity Avana?", "answer": "Tulip Infinity Avana offers spacious 2 BHK, 3 BHK, 4 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Tulip Infinity Avana MahaRERA approved?", "answer": "Yes, Tulip Infinity Avana is officially registered under MahaRERA with registration number P52100047662. All approvals and certificates are verified."}, {"question": "What amenities are provided at Tulip Infinity Avana?", "answer": "The development features world-class lifestyle amenities including Gymnasium, Library, Sports Court, Co-working Lounge, Jogging Track, multi-tier security systems, and high-speed elevators."}]', '');
