INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-newton-homes-royale', 'Newton Homes Royale', 'newton-homes-royale', 'b-newton-developers', 'Mundhwa', '₹92.50 L - ₹1.25 Cr', '₹92.50 L', '["2 BHK", "2.5 BHK", "3 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhpt6ph-7h7vlt.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhpt6ph-7h7vlt.webp', 'https://keystoneliv.com/public/uploads/property/dUBwkAaG7EfnFh6NDymuNR5UNLD1e3QTLxUcN08I.webp', '["https://keystoneliv.com/public/uploads/property/image (96).webp", "https://shapoorjirealestate.com/files/assets/jpegs/all_projects/wildernest/floorplans/3bhk-1.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/Ti87vi13I6M0IRd0wREubyKxdc8T4Nkn8g7wE844.webp"]', 'Newton Homes Royale by Ravima Ventures is a new launch on the Hadapsar–Magarpatta Road side of Mundhwa, next to the Kharadi–Hadapsar Bypass Road in East Pune. On a 2-acre plot, two 23-storey towers hold 226 homes – 2, 2.5 and 3 BHK residences of 796 to 1,072 sq ft carpet area, plus combined 4 BHK homes – with five corner homes on every floor and four levels of podium parking. Homes are planned with zero passage wastage, and every home gets a smart digital door lock, a video door phone and app-based security alerts. The structure is an Aluform and AAC block hybrid with an earthquake-resistant RCC frame. More than 50 lifestyle amenities are spread over four levels: a ground level with a pickleball court, a multipurpose sports court and a children''s play zone; a 23rd-floor terrace of about 12,000 sq ft with a swimming pool, jacuzzi, kids'' pool, adventure park, stargazing zone, amphitheatre and party lawn; and 4,500 sq ft of indoor centres – the Newton Creativity Center, a recreational center, a business center with co-working, a fitness center with gym, spa and yoga studio, and a community center with banquet hall. Magarpatta City, Amanora and Seasons malls are about 5 minutes away, Koregaon Park about 10 minutes, EON IT Park about 15 minutes, and the upcoming Hadapsar Railway Metro station about 5 minutes. Agreement values start from ₹92.5 Lakh for a 2 BHK (about ₹1.04 Cr including GST, stamp duty and registration), with one covered car park included. MahaRERA PR1261012500924.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "PR1261012500924"}, {"label": "Direct Starting Price", "value": "₹92.50 L"}, {"label": "Configurations", "value": "2 BHK, 2.5 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Mundhwa, Pune"}]', '["MahaRERA: PR1261012500924", "0% Brokerage & Direct Builder Booking", "Mundhwa Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100030924', 11620, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhpt6ph-7h7vlt.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhpt7gr-d5piyo.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhpt810-35y8c5.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhpt8ry-dr82md.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhpt9cp-76mhi0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhpta8t-ckbazu.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhptayv-gfcr64.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhptboz-453qck.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhptcrp-7spsaf.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/79ad62b1-963d-43e6-92e9-7d2a50735dc5/gallery/mvhptdgh-awu2f9.webp"]', 4.8, 100, 1, 1, 18.5347, 73.9171, '[{"type": "2 BHK", "carpetArea": "708 sq.ft", "priceRange": "₹92.50 L"}, {"type": "2.5 BHK", "carpetArea": "699 sq.ft", "priceRange": "₹93 L - ₹1.16 Cr"}, {"type": "3 BHK", "carpetArea": "1009 sq.ft", "priceRange": "₹1.30 Cr - ₹1.67 Cr"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool"]', '[{"question": "Where is Newton Homes Royale located?", "answer": "Newton Homes Royale is strategically located in prime Mundhwa, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Newton Homes Royale?", "answer": "Residences in Newton Homes Royale start from ₹92.50 L - ₹1.25 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Newton Homes Royale?", "answer": "Newton Homes Royale offers spacious 2 BHK, 2.5 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Newton Homes Royale MahaRERA approved?", "ans