INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-eh-towers-commercial', 'EH Towers Commercial', 'eh-towers-commercial', 'b-eh-developers', 'Tathawade', '₹25.02 L - ₹10.89 Cr', '₹25.02 L', '["Shop", "Office"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/2f5ab14e-ab29-40f3-941d-8b954612d18f/gallery/mwc3conf-7rrdfv.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/2f5ab14e-ab29-40f3-941d-8b954612d18f/gallery/mwc3conf-7rrdfv.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-bellissimo-hinjewadi-pune/Bellissimo_Master_Plan_1a82937c5f.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1728465957455076846.jpg", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/17284759001887960407.png"]', 'EH Towers Commercial is the shops-and-offices wing of EH Towers, the mixed-use project by Engineers Horizon on the Mumbai–Pune bypass (NH-48) in Jeevan Nagar, Tathawade. It is registered with MahaRERA as P52100079038, with EH Reality LLP as the promoter. Above three basement parking levels, the ground floor has seven double-height shops, six of them with a mezzanine, facing the highway; the first floor has ten shops and the second twenty. Offices fill the 3rd to 8th floors, 25 to a typical floor, from 119 to 677 sq ft, some with attached washrooms. A restaurant unit of 3,127 sq ft with a formed terrace sits on the 7th floor, and a second restaurant unit opens onto terrace seating on the 8th. The current cost sheet prices offices at ₹14,000 per sq ft of saleable area and shops at ₹18,000 on the second floor, ₹25,000 on the first and ₹35,000 on the ground, with saleable area 1.5 times the carpet. Agreement values start at ₹25.0 lakh for a 119 sq ft office and ₹28.8 lakh for a 107 sq ft second-floor shop. The brochure lists lifts and escalators, a separate service entry, sprinklers and fire alarms, CCTV in common areas, generator backup, a common washroom on each floor, rainwater harvesting and an STP. Possession is planned for December 2027.', '["CCTV Surveillance", "Rainwater Harvesting", "Power Backup", "Covered Parking"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100079038"}, {"label": "Direct Starting Price", "value": "₹25.02 L"}, {"label": "Configurations", "value": "Shop, Office"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Tathawade, Pune"}]', '["MahaRERA: P52100079038", "0% Brokerage & Direct Builder Booking", "Tathawade Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100079038', 8200, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/2f5ab14e-ab29-40f3-941d-8b954612d18f/gallery/mwc3conf-7rrdfv.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/ab077809-93b0-4f54-9449-8e1bb8b8e2f8/gallery/mtqwys31-6ctdzo.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/ab077809-93b0-4f54-9449-8e1bb8b8e2f8/gallery/mtqwyow7-3w4t85.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/ab077809-93b0-4f54-9449-8e1bb8b8e2f8/gallery/mtqwylhc-57ldp2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc75u9-85j08m.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/765110d3-cf60-4fb1-af72-fbed7d22491d/gallery/mvfc74yk-ag8xbh.webp"]', 4.8, 100, 1, 0, 18.6203, 73.7554, '[{"type": "Shop", "carpetArea": "569 sq.ft", "priceRange": "₹25.02 L"}, {"type": "Office", "carpetArea": "746 sq.ft", "priceRange": "₹25.02 L - ₹10.89 Cr"}]', '["CCTV Surveillance", "Rainwater Harvesting", "Power Backup", "Covered Parking"]', '[{"question": "Where is EH Towers Commercial located?", "answer": "EH Towers Commercial is strategically located in prime Tathawade, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in EH Towers Commercial?", "answer": "Residences in EH Towers Commercial start from ₹25.02 L - ₹10.89 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in EH Towers Commercial?", "answer": "EH Towers Commercial offers spacious Shop, Office apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is EH Towers Commercial MahaRERA approved?", "answer": "Yes, EH Towers Commercial is officially registered under MahaRERA with registration number P52100079038. All approvals and certificates are verified."}, {"question": "What amenities are provided at EH Towers Commercial?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Rainwater Harvesting, Power Backup, Covered Parking, multi-tier security systems, and high-speed elevators."}]', '');
