INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-kohinoor-wakad-downtown', 'Kohinoor Downtown', 'kohinoor-wakad-downtown', 'b-kohinoor', 'Wakad', '₹1.18 Cr - ₹1.65 Cr', '₹1.18 Cr', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/4179c154-ccad-4f97-8c34-322d3cb2f974/gallery/mvfbfbvh-9n7u0x.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/4179c154-ccad-4f97-8c34-322d3cb2f974/gallery/mvfbfbvh-9n7u0x.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-aethereus-high-street-mahalunge-pune/Aethereus_Master_Plan_3b81729c1a.webp', '["https://keystoneliv.com/public/uploads/property/8L6yo8fke1Wz7a9c7D8pNIZ2pR09E2Yl5a6H2JkU.webp", "https://keystoneliv.com/public/uploads/property/9bazfJfHebPTWOPKZhvlI5uteXcmfF57aTBYkICe.webp"]', 'Kohinoor Downtown is a residential project by Kohinoor Group in Wakad, Pune, near Shani Mandir Road and Dattwadi. The developer''s own website presents it as Kohinoor Regalia Towers in Downtown Wakad. It has two towers on a plot of about 3.5 acres as listed by the developer, with a B+G+4 podium+21 floor structure and homes from the 8th floor. The homes are 2 BHK of about 740 to 798 sq ft carpet area and 3 BHK of about 1,076 sq ft carpet area. Listings show starting prices of about Rs 1.18 crore for 2 BHK and Rs 1.65 crore for 3 BHK, so please confirm current rates with the sales team. Amenities include a covered infinity-edge swimming pool, gymnasium, spa, jacuzzi, mini theatre, co-working spaces, kids'' zones and a jogging track. The Mumbai-Bangalore Highway is about 450 