INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-nirvana-nothing-beyond', 'Nirvana Nothing Beyond', 'nirvana-nothing-beyond', 'b-nirman-greens', 'Baner', '₹5.61 Cr - ₹6.91 Cr', '₹5.61 Cr', '["4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/6a469bd5-0b64-456f-8384-8f3f67ea2ac4/gallery/mvu43szg-2yrh1i.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/6a469bd5-0b64-456f-8384-8f3f67ea2ac4/gallery/mvu43szg-2yrh1i.webp', 'https://keystoneliv.com/public/uploads/property/fx4tJjRmJedaJ69GSAzp9y1Po3iHhu7xv951qJNV.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/16880358391198400905.jpg"]', 'Nirvana by Nirman Greens is a luxury residential project on Survey No. 224/1, Aundh-Baner Link Road, Baner, bordering the green expanse of Pallod Farms. It has three towers. Tower A rises 31 floors with just two homes per floor: a 4 BHK of 2,550 sq ft and a 4.5 BHK with a family lounge of 3,179 sq ft. Towers B and C, of 14 floors each, have two 3 BHK homes of 1,445 sq ft per floor. The 4 BHK is offered at ₹5.61 crore and the 4.5 BHK at ₹6.91 crore, all inclusive, each with three covered car parks, and the project is nearing possession, planned for December 2026. The 4.5 BHK has two master suites, one with a jacuzzi, two more bedrooms, a 12''9" x 18''3" family area, a 38 ft living and dining room, a helper room and a 23''9" sit-out; the 4 BHK has a 30 ft living and family area, a separate dining room, two master suites with walk-in wardrobes and a 30 ft sit-out. Homes have marble flooring in the living room, dining, kitchen, bedrooms and bathrooms, a fully furnished modular kitchen with a hob, chimney, water purifier and oven, system windows, veneer-finished doors, home automation in the living and dining area, air conditioning in the living room, dining and bedrooms, boilers in all bathrooms and 100% generator backup. The clubhouse has a lap pool with an infinity edge, a kids'' bubbler pool, a rock-climbing wall, a multipurpose hall, a cricket pitch and a sports court; the ground level adds a gym and sauna, spa rooms, a squash court, a jogging loop, a billiards deck, a leisure lounge, outdoor work stations, a crèche, indoor and outdoor kids'' play areas and a vehicle-free zone. Tower A''s rooftop has a covered infinity-edge pool and an infinity sky bar with a stargazing lounge and barbecue courtyard, and Towers B and C share a rooftop yoga deck, outdoor fitness station and sky garden lounge. The project is registered with MahaRERA as P52100047528.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Sports Court", "Jogging Track", "Swimming Pool", "Power Backup"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100047528"}, {"label": "Direct Starting Price", "value": "₹5.61 Cr"}, {"label": "Configurations", "value": "4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Baner, Pune"}]', '["MahaRERA: P52100047528", "0% Brokerage & Direct Builder Booking", "Baner Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100047528', 22000, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/6a469bd5-0b64-456f-8384-8f3f67ea2ac4/gallery/mvu43szg-2yrh1i.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6a469bd5-0b64-456f-8384-8f3f67ea2ac4/gallery/mvu43th9-8na46q.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/6a469bd5-0b64-456f-8384-8f3f67ea2ac4/gallery/mvu43tjz-