INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-my-home-sanctuary', 'My Home Sanctuary', 'my-home-sanctuary', 'b-goyal-properties', 'Mamurdi', '₹67.00 L - ₹86.00 L', '₹67.00 L', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/a7b64a6e-86ac-40ef-887f-e964bd4a4fc8/gallery/mvf7bzjg-eiosdy.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/a7b64a6e-86ac-40ef-887f-e964bd4a4fc8/gallery/mvf7bzjg-eiosdy.webp', 'https://keystoneliv.com/public/uploads/property/fx4tJjRmJedaJ69GSAzp9y1Po3iHhu7xv951qJNV.webp', '["https://keystoneliv.com/public/uploads/property/iTt80ob6Q847pdqJo6QxQYX9jjyINihAoQvfFwpB.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/j6Wb9cOhThHs5G5EODyVRF8nmtjnP9T0wBWO4MqP.webp"]', 'My Home Sanctuary is a residential township by Goyal Properties at Survey No. 8 (P), Mamurdi, Haveli taluka, Pune, on about 40,000 sq m of land and registered with MahaRERA as Phase I. The RERA record lists six buildings: towers A, B, C, D and a MHADA tower L of up to 31 floors, plus a multi-level car park, with 704 sanctioned apartments. Homes are 2 BHK of 638 to 760 sq ft and 3 BHK of 848 to 1,036 sq ft carpet area, offered in Classic, Premier and Signature variants. The developer promotes over 75 amenities, including a swimming pool, futsal and pickleball courts, an amphitheatre, urban forest, botanical garden, podcast studio, yoga and meditation deck, party lawn and a temple. By the developer''s own listing, SNBP International School is about a minute away, Symbiosis Skills and Professional University five minutes, MCA Stadium seven minutes and Inox Megaplex ten minutes. Asking prices on property portals in October 2026 start at ₹67 L for a 2 BHK and ₹86 L for a 3 BHK; confirm the current price sheet with the sales team. The MahaRERA number is PR1261012502725 and the registered completion date is 31 December 2031.', '["Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "Landscaped Garden"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1261012502725"}, {"label": "Direct Starting Price", "value": "₹67 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Mamurdi, Pune"}]', '["MahaRERA: PR1261012502725", "0% Brokerage & Direct Builder Booking", "Mamurdi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100032725', 10501, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/a7b64a6e-86ac-40ef-887f-e964bd4a4fc8/gallery/mvf7bzjg-eiosdy.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a7b64a6e-86ac-40ef-887f-e964bd4a4fc8/gallery/mvf7c0i0-3jg0d.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a7b64a6e-86ac-40ef-887f-e964bd4a4fc8/gallery/mvf7c15s-5mugnn.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a7b64a6e-86ac-40ef-887f-e964bd4a4fc8/gallery/mvf7c1th-1vr9a4.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a7b64a6e-86ac-40ef-887f-e964bd4a4fc8/gallery/mvf7c2i0-4ckirr.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a7b64a6e-86ac-40ef-887f-e964bd4a4fc8/gallery/mvf7c7id-dtjw30.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a7b64a6e-86ac-40ef-887f-e964bd4a4fc8/gallery/mvf7c8wf-ak2xt2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/a7b64a6e-86ac-40ef-887f-e964bd4a4fc8/gallery/mvf7ca96-5alwql.webp"]', 4.8, 100, 1, 0, 18.6624, 73.7236, '[{"type": "2 BHK", "carpetArea": "693 sq.ft", "priceRange": "₹67 L - ₹84 L"}, {"type": "3 BHK", "carpetArea": "1124 sq.ft", "priceRange": "₹86.00 L"}]', '["Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "Landscaped Garden"]', '[{"question": "Where is My Home Sanctuary located?", "answer": "My Home Sanctuary is strategically located in prime Mamurdi, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in My Home Sanctuary?", "answer": "Residences in My Home Sanctuary start from ₹67 L - ₹86 L with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in My Home Sanctuary?", "answer": "My Home Sanctuary offers spacious 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is My Home Sanctuary MahaRERA approved?", "answer": "Yes, My Home Sanctuary is officially registered under MahaRERA with registration number PR1261012502725. All approvals and certificates are verified."}, {"question": "What amenities are provided at My Home Sanctuary?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Gymnasium, Library, Sports Court, Co-working Lounge, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-majestique-evolvus', 'Majestique Evolvus', 'majestique-evolvus', 'b-asian-sleek', 'Kharadi', '₹1.84 Cr - ₹2.85 Cr', '₹1.84 Cr', '["3 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/4f7bcab2-80fd-4317-b7bd-1c87cf827a62/gallery/mvhs3d3y-b0frjo.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/4f7bcab2-80fd-4317-b7bd-1c87cf827a62/gallery/mvhs3d3y-b0frjo.webp', 'https://keystoneliv.com/public/uploads/property/MePjpM2o9KQjJ6xTMr6aFlHFsoAzGOb15Qt42xOo.webp', '["https://keystoneliv.com/public/uploads/property/1hrp8Z2H37hCLmuwIlHXP5eaxifc5wiCotUH5cVM.webp", "https://keystoneliv.com/public/uploads/property/tUBr7yI4J0rcf1m7F6WmNhcMFvrZvPOrpLkLA0xd.webp"]', 'Majestique Evolvus by Majestique Landmarks is a 10-acre landmark development in Central Kharadi, near the Kharadi bypass and next to BNY Mellon, with the EON Free Zone and World Trade Center close by. Its towers rise G + 26 floors above five levels of car parking, over a retail high street planned to stretch more than a kilometre. The current release offers luxurious 3 BHK homes of 1,149 to 1,300 sq ft and 4 BHK homes of 1,565 to 1,715 sq ft carpet area, with premium specifications – a modular kitchen by Asian Sleek in the 3 and 4 BHK homes, a dishwasher provision, piped gas, a separate drinking-water line and Kone or equivalent elevators. More than 70 lifestyle amenities are spread across the ground level, a central podium and a premier terrace: a ~27,000 sq ft clubhouse with a double-height banquet hall, theatre, co-working space, gym and CrossFit zone, library, female spa and kids'' play areas; a swimming pool with a juice bar and restaurant; basketball, multipurpose and box-cricket courts and a skating rink; a temple, pet park and bonfire area; ~33,400 sq ft of gardens; and an open-to-sky terrace walkway and jogging track of about 850 m with yoga space, a gazebo with water body, a fine-dine area and a sky lounge under a night-sky glass ceiling. Viman Nagar, Kalyani Nagar and Koregaon Park are close by, with Amanora Mall, Seasons Mall and Phoenix Marketcity within easy reach. Prices start from ₹1.84 Cr for a 3 BHK and ₹2.65 Cr for a 4 BHK (plus floor rise). MahaRERA P52100054253 (Evolvus Phase I).', '["Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "24x7 Security"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100054253"}, {"label": "Direct Starting Price", "value": "₹1.84 Cr"}, {"label": "Configurations", "value": "3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Kharadi, Pune"}]', '["MahaRERA: P52100054253", "0% Brokerage & Direct Builder Booking", "Kharadi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100054253', 16013, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/4f7bcab2-80fd-4317-b7bd-1c87cf827a62/gallery/mvhs3d3y-b0frjo.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/4f7bcab2-80fd-4317-b7bd-1c87cf827a62/gallery/mvhs3e3w-csaej8.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/4f7bcab2-80fd-4317-b7bd-1c87cf827a62/gallery/mvhs3f1j-75y8r8.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/4f7bcab2-80fd-4317-b7bd-1c87cf827a62/gallery/mvhs3fyi-81otq7.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/4f7bcab2-80fd-4317-b7bd-1c87cf827