INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-mantra-mistara', 'Mantra Mistara', 'mantra-mistara', 'b-mantra-properties', 'Baner', '₹74.00 L - ₹98.00 L', '₹74.00 L', '["2 BHK", "3 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/24b3750c-74e9-4d15-9651-6165d58555e5/gallery/mvf7cwip-bln5z0.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/24b3750c-74e9-4d15-9651-6165d58555e5/gallery/mvf7cwip-bln5z0.webp', 'https://keystoneliv.com/public/uploads/property/AEV4Alkp45KgjGoLG3i2wOtoKOjfuY7T0aplVMNP.webp', '["https://keystoneliv.com/public/uploads/property/BvTZeUCeXNM68BIMHLlqJbvYdggPCaAGorJHvwi8.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/QbhYUbAfFrqgKArEMujIovb4jaOm9oYk4M7GmYWA.webp"]', 'Mantra Mistara by Mantra Properties is a residential project at Sus Hillside, off Rajgad Bunglow Road near Parkhe Vasti, Sus, Pune 411021. It is planned as two towers of three basement levels plus 28 floors on about 2.45 acres, with seven flats and two lifts per floor, and hillside views to the south, east and west. Only the first tower is being launched now. Homes include 2 BHK Optima (about 714 sq ft carpet), 2 BHK Ultima (about 761 sq ft) and 3 BHK Premium (about 946 sq ft). Amenities sit under the M Club banner: gymnasium, yoga and zumba studio, co-working spaces, swimming pool with kids'' pool, play area, squash and badminton courts, party lawn, banquet hall and pet park. Parking is in the basement levels, and doors carry digital locks. Listings place Sus Pashan Bridge about 3 km away and Maruti Chowk about 3.1 km away, with Orchids The International School and Sus Hospital close by. The project is under construction and registered under MahaRERA number PR1261012600816, with possession listed as December 2030. Listing portals quote all-inclusive prices of about ₹74 lakh to ₹98 lakh, so confirm the current price sheet with the sales team.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "Power Backup"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "PR1261012600816"}, {"label": "Direct Starting Price", "value": "₹74 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Baner, Pune"}]', '["MahaRERA: PR1261012600816", "0% Brokerage & Direct Builder Booking", "Baner Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100060816', 10364, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/24b3750c-74e9-4d15-9651-6165d58555e5/gallery/mvf7cwip-bln5z0.webp", "https://keystoneliv.com/public/uploads/property/Mc9E5NBWOsI1NtldSLZmgKPoYKU0CWl7tF5vDeCQ.webp", "https://keystoneliv.com/public/uploads/property/nmPzChK44V7G0iiNdq6UHi8c9Yqa7WJWDA6qDGUb.webp", "https://keystoneliv.com/public/uploads/property/QujUjJZ0G5zvpoujbJlR7mziw17Whp3rqma1HfW4.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/00789064-ebcf-4e95-99f3-6f00b908eae3/gallery/msob4dr4-28dyoq.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/00789064-ebcf-4e95-99f3-6f00b908eae3/gallery/msob4i1j-8d0n7t.webp"]', 4.8, 100, 1, 1, 18.5567, 73.7848, '[{"type": "2 BHK", "carpetArea": "744 sq.ft", "priceRange": "₹74 L - ₹93 L"}, {"type": "3 BHK", "carpetArea": "1110 sq.ft", "priceRange": "₹98.00 L"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "Pow