INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-neco-park-central', 'Neco Park Central', 'neco-park-central', 'b-neco-developers', 'Kharadi', '₹1.19 Cr - ₹2.39 Cr', '₹1.19 Cr', '["2 BHK", "3 BHK", "3.5 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/3c62297e-cf76-40e6-be1b-9863a18f21a4/gallery/mvhqtpdg-2wwccl.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/3c62297e-cf76-40e6-be1b-9863a18f21a4/gallery/mvhqtpdg-2wwccl.webp', 'https://keystoneliv.com/public/liv-thumbs/640/uploads/property/2ocDxHCTXWnA2CnIKGCGcSwin1rTir1eCXkoMNzB.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/1676437496754730563.jpg", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1776692151873809711.jpeg", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1684239435908877360.jpg", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/16842409081778200113.jpg"]', 'Neco Park Central by Vasupujya Corporation is an IGBC Platinum pre-certified residential project off Old Mundhwa Road in Kharadi, East Pune, behind BG Tatva Society and near Bollywood Multiplex. The site sits in one of the greenest pockets of Kharadi, beside Oxygen Park, a public playground and reserved gardens, within PMC limits and about 400 m from the proposed 30 m DP road. On a land parcel of about 2.5 acres, three wings rise 18 storeys above three levels of parking, with 2, 3, 3.5 and 4 BHK homes of 849 to 1,865 sq ft (carpet plus balcony) and a 60 ft entrance boulevard. Amenities are spread over three levels: a clubhouse with party lawn, amphitheatre, cricket/football ground, badminton/basketball court, outdoor gym, jogging track, children''s play area, pet zone and senior citizens'' sit-out at ground level; a podium with a swimming pool and baby pool, landscaped lawn, gymnasium, yoga and meditation room, indoor games room, co-working space and toddlers'' creche; and a rooftop community lounge. Green features include solar hot water, rooftop solar PV for common areas, rainwater harvesting, an STP that recycles water for flushing and gardening, and heat-insulating glass. Homes come with a smart lock on the main door, a video door phone, 600 x 1200 mm vitrified tiles, Jaquar/Kohler-class fittings and AC provision in every bedroom and the living room. Four proposed metro stations lie within about 2 km, and the IT parks of Kharadi, Viman Nagar, Yerwada, Mundhwa and Magarpatta are about 10 minutes away. All-inclusive prices start at ₹1.19 Cr for a 2 BHK with one car park. MahaRERA P52100077542.', '["Clubhouse", "Gymnasium", "Rainwater Harvesting", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "Power Backup"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100077542"}, {"label": "Direct Starting Price", "value": "₹1.19 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 3.5 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Kharadi, Pune"}]', '["MahaRERA: P52100077542", "0% Brokerage & Direct Builder Booking", "Kharadi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100077542', 14016, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/3c62297e-cf76-40e6-be1b-9863a18f21a4/gallery/mvhqtpdg-2wwccl.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3c62297e-cf76-40e6-be1b-9863a18f21a4/gallery/mvhqtq2g-33imyr.webp", "https://punehome.in/storage/v1/o