INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-sai-ratan', 'Sai Ratan', 'sai-ratan', 'b-sai-nisarg-landmark', 'Ravet', '₹77.00 L - ₹1.03 Cr', '₹77.00 L', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthrdh-8tggr3.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthrdh-8tggr3.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-altamira-kharadi-pune/Altamira_Master_Plan_166b88523c.webp', '["https://keystoneliv.com/public/uploads/property/tUBr7yI4J0rcf1m7F6WmNhcMFvrZvPOrpLkLA0xd.webp", "https://keystoneliv.com/public/uploads/property/1hrp8Z2H37hCLmuwIlHXP5eaxifc5wiCotUH5cVM.webp"]', 'Sai Ratan is a new mixed-use project in Sector 29, Ravet Pradhikaran, by Sai Associates with Krishna Rama Developer and Ratan Homes. Its terracotta-and-grey building has 21 double-height shops with mezzanines along a 10.5 m road and three residential wings (A, B and C) above – 102 homes in all: 2 BHK of 777 sq ft and 3 BHK of 1,020 sq ft (carpet plus balcony). Amenities include a gymnasium, indoor games room, banquet hall, rooftop party lawn, landscaped rooftop sit-outs and a children''s play area. Homes get a 35 mm main door with a biometric lock, a video door bell, UPVC windows and balcony doors, 600 x 1200 mm vitrified tiles, Jaquar/Hindware fittings, geysers in every bathroom and AC provision in the living room and all bedrooms; the building has EV charging and solar power. D. Y. Patil Dnyanshanti School, PCCOE, DMart Ravet, Global Hospital and Akurdi railway station are about 5 minutes away, with the old Mumbai–Pune Highway and NH-48 about 10 minutes. Agreement values start from ₹77 L for a 2 BHK (about ₹86.5 L including GST, stamp duty and registration). MahaRERA PM1260002600399.', '["Clubhouse", "Gymnasium", "Landscaped Garden", "Kids'' Play Area", "EV Charging"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PM1260002600399"}, {"label": "Direct Starting Price", "value": "₹77 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Ravet, Pune"}]', '["MahaRERA: PM1260002600399", "0% Brokerage & Direct Builder Booking", "Ravet Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100020399', 9909, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthrdh-8tggr3.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhths9u-dvexpu.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthszm-31px5c.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthu0j-7jqxou.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthv4k-3x7nnx.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthw99-9b0l00.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthx7e-fx36dr.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthy53-a479z9.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthz29-n6qjt.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhthzs8-jnbn3.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhti0k8-ewlyem.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhti1ba-5awr7n.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhti26l-976i46.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/3266ed23-72ff-41aa-9c4b-6bcd594ab0c8/gallery/mvhti32p-2fncet.webp"]', 4.8, 100, 1, 0, 18.6533, 73.7481, '[{"type": "2 BHK", "carpetArea": "681 sq.ft", "priceRange": "₹77 L - ₹96 L"}, {"type": "3 BHK", "carpetArea": "1046 sq.ft", "priceRange": "₹1.08 Cr - ₹1.39 Cr"}]', '["Clubhouse", "Gymnasium", "Landscaped Garden", "Kids'' Play Area", "EV Charging"]', '[{"question": "Where is Sai Ratan located?", "answer": "Sai Ratan is strategically located in prime Ravet, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Sai Ratan?", "answer": "Residences in Sai Ratan start from ₹77 L - ₹1.03 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Sai Ratan?", "answer": "Sai Ratan offers spacious 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Sai Ratan MahaRERA approved?", "answer": "Yes, Sai Ratan is officially registered under MahaRERA with registration number PM1260002600399. All approvals and certificates are verified."}, {"question": "What amenities are provided at Sai Ratan?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Gymnasium, Landscaped Garden, Kids'' Play Area, EV Charging, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-l-axis', 'L Axis', 'l-axis', 'b-pharande-spaces', 'Moshi', '₹1.09 Cr - ₹2.04 Cr', '₹1.09 Cr', '["2 BHK", "3 BHK", "4 BHK"]', 'Ready to Move', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc64td-5k9jp8.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc64td-5k9jp8.webp', 'https://keystoneliv.com/public/uploads/property/Ptw9XmFBU5IeYvADN8ruLftUvTCTToYOMifOkh2x.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/udgWlmoH6ofCgYL184zKnPq8Zexr2l7fEoztyewT.webp", "https://keystoneliv.com/public/uploads/property/bS9eQ4haaMridWuxHQiTNBS2XRx3BSSXIqsk3oVh.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/yiPGuOJ5Fhyx0YB3EzGkjiPFft7mIQsii4HFZdjW.webp"]', 'L Axis by Pharande Spaces is a large residential community on Spine Road, Sector 6, PCNTDA, Moshi, Pimpri-Chinchwad, spread over about 11 acres and built in phases and clusters, with the earlier phases already occupied. The current phases offer 2, 3 and 4 BHK apartments in high-rise towers using Mivan technology, with 40% open space and a four-tier security system. Carpet areas listed by the developer are 819 to 835 sq ft for 2 BHK, 1,121 to 1,290 sq ft for 3 BHK and 1,479 sq ft for 4 BHK. Asking prices on property portals in October 2026 start at ₹1.09 Cr for a 2 BHK, ₹1.51 Cr for a 3 BHK and ₹2.04 Cr for a 4 BHK; confirm the current price sheet with the sales team. Amenities include a swimming pool, a fitness centre, an amphitheatre, a basketball court, games rooms and a senior citizen area. Spine City Mall is about 1.1 km away, Talawade IT Park about 10 km and PCMC Metro station about 8.4 km. Phase III Cluster B is registered under MahaRERA number P52100077434, with possession targeted for December 2029.', '["Clubhouse", "Gymnasium", "Sports Court", "Jogging Track", "Swimming Pool", "Power Backup", "24x7 Security", "Landscaped Garden"]', '[{"label": "Project Status", "value": "Ready to Move"}, {"label": "MahaRERA ID", "value": "P52100077434"}, {"label": "Direct Starting Price", "value": "₹1.09 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Moshi, Pune"}]', '["MahaRERA: P52100077434", "0% Brokerage & Direct Builder Booking", "Moshi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100077434', 13308, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc64td-5k9jp8.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc65py-flh1vc.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc66gb-416402.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc67eg-bmc3ac.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc68ef-awr801.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc696v-ep50j9.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc69tu-9b7ivq.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc6ab3-8vynhb.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc6bdv-4b5law.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/01d2e9f1-dad0-43fa-8906-61a24bfcd0dd/gallery/mvfc6buf-5czv3t.webp"]', 4.8, 100, 1, 0, 18.6724, 73.8443, '[{"type": "2 BHK", "carpetArea": "734 sq.ft", "priceRange": "₹1.09 Cr - ₹1.36 Cr"}, {"type": "3 BHK", "carpetArea": "1017 sq.ft", "priceRange": "₹1.53 Cr - ₹1.96 Cr"}, {"type": "4 BHK", "carpetArea": "1597 sq.ft", "priceRange": "₹2.04 Cr"}]', '["Clubhouse", "Gymnasium", "Sports Court", "Jogging Track", "Swimming Pool", "Power Backup", "24x7 Security", "Landscaped Garden"]', '[{"question": "Where is L Axis located?", "answer": "L Axis is strategically located in prime Moshi, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in L Axis?", "answer": "Residences in L Axis start from ₹1.09 Cr - ₹2.04 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in L Axis?", "answer": "L Axis offers spacious 2 BHK, 3 BHK, 4 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is L Axis MahaRERA approved?", "answer": "Yes, L Axis is officially registered under MahaRERA with registration number P52100077434. All approvals and certificates are verified."}, {"question": "What amenities are provided at L Axis?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Gymnasium, Sports Court, Jogging Track, Swimming Pool, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-mantra-melange', 'Mantra Melange', 'mantra-melange', 'b-mantra-properties', 'Kharadi', '₹1.22 Cr - ₹1.72 Cr', '₹1.22 Cr', '["2 BHK", "3 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc0yi3-d2qb7x.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc0yi3-d2qb7x.webp', 'https://keystoneliv.com/public/uploads/property/image (40).webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/3K1d5aSB23mtWUwKhqAuWcReKd3jpS1SygdeiM9N.webp", "https://keystoneliv.com/public/uploads/property/image - 2026-05-28T164742.622.webp"]', 'Mantra Melange is a riverside residential project by Mantra Properties in Kharadi Riverside, Wadgaon Sheri, Pune, on the banks of the Mula Mutha river. The development spreads over 8.75 acres, with a master layout of 11 landmark towers. The current launch brings 6 new towers with only 4 homes per floor, offering 2 BHK and 3 BHK apartments. A 2 BHK has a usable area of 843 or 882 sq ft (759 or 799 sq ft RERA carpet) and a 3 BHK has 1,110 or 1,177 sq ft (1,019 or 1,043 sq ft RERA carpet). Prices start at ₹1.22 crore for a 2 BHK and ₹1.61 crore for a 3 BHK. Residents get a podium with a swimming pool, amphitheatre, play area and open cafeteria, and a clubhouse with a gym, library, crèche, music room, tuition room, yoga and Zumba studios, co-working space, podcast room, indoor games and a guest bedroom. The location is 5 minutes from Magarpatta and Seasons Mall, 7 minutes from World Trade Center Kharadi and about 20 minutes from Pune airport and the railway station. Mantra Melange is registered with MahaRERA under project name Mantra Kharadi Phase 1 (P52100079582), with a RERA completion date of April 2030.', '["Clubhouse", "Gymnasium", "Library", "Co-working Lounge", "Swimming Pool", "Landscaped Garden", "Kids'' Play Area", "Amphitheatre"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "P52100079582"}, {"label": "Direct Starting Price", "value": "₹1.22 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Kharadi, Pune"}]', '["MahaRERA: P52100079582", "0% Brokerage & Direct Builder Booking", "Kharadi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100079582', 14472, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc0yi3-d2qb7x.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc0zbz-butb1s.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc0zzc-7jyaep.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc10pj-dpcfg3.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc11fo-7e1exs.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc12bz-3xq0s5.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc1381-6e144a.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc141i-3ylj4w.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc14qv-57vvqd.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc15ak-3v6ow0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc1626-du4ljs.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc16mq-b62559.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc177e-ejph07.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc17sm-2q19di.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc186y-1aba4l.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc18xp-3h6w6z.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc19gy-fabxqi.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc1a1h-1sgop9.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc1alg-b0lic.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc1b4q-czx05e.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc1bnk-8bejeu.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/320265b2-aa9a-48cb-b5e9-150455175a36/gallery/mvjc1cdo-3sybn0.webp"]', 4.8, 100, 1, 1, 18.5497, 73.9326, '[{"type": "2 BHK", "carpetArea": "702 sq.ft", "priceRange": "₹1.22 Cr - ₹1.53 Cr"}, {"type": "3 BHK", "carpetArea": "981 sq.ft", "priceRange": "₹1.71 Cr - ₹2.20 Cr"}]', '["Clubhouse", "Gymnasium", "Library", "Co-working Lounge", "Swimming Pool", "Landscaped Garden", "Kids'' Play Area", "Amphitheatre"]', '[{"question": "Where is Mantra Melange located?", "answer": "Mantra Melange is strategically located in prime Kharadi, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Mantra Melange?", "answer": "Residences in Mantra Melange start from ₹1.22 Cr - ₹1.72 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Mantra Melange?", "answer": "Mantra Melange offers spacious 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Mantra Melange MahaRERA approved?", "answer": "Yes, Mantra Melange is officially registered under MahaRERA with registration number P52100079582. All approvals and certificates are verified."}, {"question": "What amenities are provided at Mantra Melange?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Gymnasium, Library, Co-working Lounge, Swimming Pool, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-shaligram-ravet', 'Shaligram The Mile', 'shaligram-ravet', 'b-shaligram-buildcon', 'Ravet', '₹1.38 Cr - ₹1.92 Cr', '₹1.38 Cr', '["3 BHK", "4 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/bed8b526-3c8c-426b-8e44-cf65c659dbbe/gallery/mvhovzr5-s99wh.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/bed8b526-3c8c-426b-8e44-cf65c659dbbe/gallery/mvhovzr5-s99wh.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-aurelia-kharadi-pune/Aurelia_Master_Plan_0a37b12d7c.webp', '["https://keystoneliv.com/public/uploads/property/3sc0FvlkSeRB8AoYR0SxcEtb6SinhQcIhFDRcaiY.webp", "https://keystoneliv.com/public/uploads/property/image (95).webp"]', 'Shaligram The Mile by Shaligram Group is a single landmark tower on the Aundh–Ravet BRTS Road in Ravet – the first high-rise you see entering Pune from Mumbai. On a 1.75-acre plot, it rises B2 + B1 + G + 36 floors with only 202 signature residences: 3 BHK homes of 1,124 to 1,301 sq ft and 4 BHK homes of 1,465 and 1,560 sq ft carpet area. Homes have a 10.5 ft floor-to-floor height, full-height glass façades, walk-in wardrobes, private sky decks and Vaastu-compliant layouts. Amenities are spread over three levels: a ground realm with gardens, gazebos, a jogging track, an amphitheatre, a kids'' play area and a multipurpose banquet hall; an indulgence level with a swimming pool and deck, baby pool, jacuzzi, gym, crèche and indoor games lounge; and a rooftop sky experience with a café, mini theatre, library and co-working area, yoga and meditation deck, sky walkway and stargazing deck. Ojas Multispecialty Hospital is about 2 minutes away, Global Hospital about 4 minutes, and Elpro City Square, Phoenix Mall of the Millennium and D-Mart Ravet about 10 minutes away. Launch prices start from ₹1.38 Cr for a 3 BHK and ₹1.80 Cr for a 4 BHK. MahaRERA PR1260002601415; RERA completion date December 2031.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Co-working Lounge", "Jogging Track", "Swimming Pool"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "PR1260002601415"}, {"label": "Direct Starting Price", "value": "₹1.38 Cr"}, {"label": "Configurations", "value": "3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Ravet, Pune"}]', '["MahaRERA: PR1260002601415", "0% Brokerage & Direct Builder Booking", "Ravet Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100021415', 12277, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/bed8b526-3c8c-426b-8e44-cf65c659dbbe/gallery/mvhovzr5-s99wh.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bed8b526-3c8c-426b-8e44-cf65c659dbbe/gallery/mvhow0qr-3of0g0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bed8b526-3c8c-426b-8e44-cf65c659dbbe/gallery/mvhow1ht-28g8zx.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bed8b526-3c8c-426b-8e44-cf65c659dbbe/gallery/mvhow22s-9cwzg2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bed8b526-3c8c-426b-8e44-cf65c659dbbe/gallery/mvhow2s8-3eicje.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bed8b526-3c8c-426b-8e44-cf65c659dbbe/gallery/mvhow3hp-3jlyil.webp"]', 4.8, 100, 1, 0, 18.652, 73.7403, '[{"type": "3 BHK", "carpetArea": "1036 sq.ft", "priceRange": "₹1.38 Cr"}, {"type": "4 BHK", "carpetArea": "1636 sq.ft", "priceRange": "₹1.92 Cr"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Co-working Lounge", "Jogging Track", "Swimming Pool"]', '[{"question": "Where is Shaligram The Mile located?", "answer": "Shaligram The Mile is strategically located in prime Ravet, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Shaligram The Mile?", "answer": "Residences in Shaligram The Mile start from ₹1.38 Cr - ₹1.92 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Shaligram The Mile?", "answer": "Shaligram The Mile offers spacious 3 BHK, 4 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Shaligram The Mile MahaRERA approved?", "answer": "Yes, Shaligram The Mile is officially registered under MahaRERA with registration number PR1260002601415. All approvals and certificates are verified."}, {"question": "What amenities are provided at Shaligram The Mile?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Clubhouse, Gymnasium, Rainwater Harvesting, Library, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-codename-light', 'Codename Light', 'codename-light', 'b-esson-landmarks', 'Mundhwa', '₹93.00 L - ₹1.22 Cr', '₹93.00 L', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/1d95631a-ef8e-4793-b94f-12fd3ff1902a/gallery/mvjeyoq9-3nr91v.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/1d95631a-ef8e-4793-b94f-12fd3ff1902a/gallery/mvjeyoq9-3nr91v.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-sierra-baner-sus-pune/Sierra_Master_Plan_6b71829c3a.webp', '["https://shapoorjirealestate.com/files/assets/jpegs/all_projects/wildernest/floorplans/3bhk-2.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/Oz85QLYWtUPkHjRU5N2NHLOOg2Z4WBzI9bJT6qeD.webp"]', 'Codename Light is a Vastu-compliant residential project in Keshav Nagar, Mundhwa, Pune, by Esson Landmarks, Unitary Properties and Suyog Group, on Keshav Nagar Road near Renuka Mata Mandir. Spread across 4.5 acres, it is planned around three elegantly rising towers with about 1.1 acres of lifestyle and amenity space. The homes are 2 BHK of 775 to 787 sq ft and 3 BHK of 993 to 995 sq ft (total carpet area including balconies), with wide balconies and efficient layouts that let in natural light. A 2 BHK comes with one car park and a 3 BHK with two. Indicative all-inclusive prices start at ₹93 lakh for a 2 BHK and ₹1.22 crore for a 3 BHK. More than 35 amenities include a rooftop swimming pool with vanishing edge and water cascade, kids pool, clubhouse and banquet hall, gym, yoga and Zumba rooms, spa and salon, amphitheatre and movie amphitheatre, temple court, party lawn, Miyawaki forest, play court and children''s play areas. The upcoming Keshav Nagar–Kharadi bridge is about 7 minutes away, Koregaon Park 10 minutes, Magarpatta City 12 minutes, EON IT Park 15 minutes and Pune Airport 20 minutes. The project is registered with MahaRERA as LIORA (PR1261012501453), valid until 31 March 2029.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Swimming Pool", "Power Backup", "24x7 Security"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1261012501453"}, {"label": "Direct Starting Price", "value": "₹93 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Mundhwa, Pune"}]', '["MahaRERA: PR1261012501453", "0% Brokerage & Direct Builder Booking", "Mundhwa Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100031453', 12000, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/1d95631a-ef8e-4793-b94f-12fd3ff1902a/gallery/mvjeyoq9-3nr91v.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1d95631a-ef8e-4793-b94f-12fd3ff1902a/gallery/mvjeyplu-1as14y.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1d95631a-ef8e-4793-b94f-12fd3ff1902a/gallery/mvjeyqc1-7gibqv.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1d95631a-ef8e-4793-b94f-12fd3ff1902a/gallery/mvjeyr57-4ht5ma.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1d95631a-ef8e-4793-b94f-12fd3ff1902a/gallery/mvjeyrtq-fnf1ms.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/1d95631a-ef8e-4793-b94f-12fd3ff1902a/gallery/mvjeysji-10csee.webp"]', 4.8, 100, 1, 1, 18.538, 73.9206, '[{"type": "2 BHK", "carpetArea": "728 sq.ft", "priceRange": "₹93.00 L"}, {"type": "3 BHK", "carpetArea": "1003 sq.ft", "priceRange": "₹1.22 Cr"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Library", "Swimming Pool", "Power Backup", "24x7 Security"]', '[{"question": "Where is Codename Light located?", "answer": "Codename Light is strategically located in prime Mundhwa, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Codename Light?", "answer": "Residences in Codename Light start from ₹93 L - ₹1.22 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Codename Light?", "answer": "Codename Light offers spacious 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Codename Light MahaRERA approved?", "answer": "Yes, Codename Light is officially registered under MahaRERA with registration number PR1261012501453. All approvals and certificates are verified."}, {"question": "What amenities are provided at Codename Light?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Clubhouse, Gymnasium, Rainwater Harvesting, Library, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-mangalam-starview', 'Mangalam Starview', 'mangalam-starview', 'b-mangalam-landmarks', 'Kiwale', '₹80.00 L - ₹1.02 Cr', '₹80.00 L', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/62c4f82a-4e0d-43ed-bb38-e8ccdf9df558/gallery/mvez09ey-de6zrx.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/62c4f82a-4e0d-43ed-bb38-e8ccdf9df558/gallery/mvez09ey-de6zrx.webp', 'https://keystoneliv.com/public/uploads/property/Ptw9XmFBU5IeYvADN8ruLftUvTCTToYOMifOkh2x.webp', '["https://keystoneliv.com/public/uploads/property/HNvTc3nVkYmFjSbMvb2D2yLmiDCkAwa79zcs9svU.webp", "https://keystoneliv.com/public/uploads/property/f9GMlttRsqc66dOt6VQurFR4i48juAfzCiUaFmOs.webp"]', 'Premium 2 & 3 BHK Apartments in Kiwale, Pune
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-prime-pinnacle', 'Prime Pinnacle', 'prime-pinnacle', 'b-viraj-corp', 'Wakad', '₹68.00 L - ₹2.23 Cr', '₹68.00 L', '["Smart Office", "Premium Office"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqa3t-4dghew.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqa3t-4dghew.webp', 'https://keystoneliv.com/public/uploads/property/nBIFK5yY27v8iGeOPunLCcGZJMSxZp8NlvxZwRKD.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1676437625251825814.jpg", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1734594164955974829.jpeg"]', 'Prime Pinnacle is a Grade A commercial tower by Viraj Corp on Datta Mandir Road in Wakad, Pune 411057, which the developer describes as the tallest commercial building in Wakad. The project is a single 15-storey tower offering boutique offices with glass partitions and doors, a grand double-height entrance lobby, high-speed elevators, a washroom in every unit and a rooftop cafeteria. Smart offices have a carpet area of 346 to 752 sq ft, while premium offices range from 1,277 to 2,489 sq ft, and each unit gets its own three-phase meter with 24x7 DG backup. Parking is handled through a multi-level robotic car parking system, and the building has 24x7 security with an intercom facility, a fire hydrant system and two common conference rooms. Asking prices on property portals in October 2026 start at ₹68 L for a Smart Office and ₹2.23 Cr for a Premium Office; confirm the current price sheet with the sales team. According to the developer, Wakad Metro Station is about 5 minutes away, Hinjewadi 8 minutes, Balewadi 10 minutes and Cognizant H2 11 minutes. The project is registered under MahaRERA number P52100077826, with possession reported for September 2027.', '["Power Backup", "24x7 Security", "Covered Parking"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100077826"}, {"label": "Direct Starting Price", "value": "₹68 L"}, {"label": "Configurations", "value": "Smart Office, Premium Office"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Wakad, Pune"}]', '["MahaRERA: P52100077826", "0% Brokerage & Direct Builder Booking", "Wakad Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100077826', 19653, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqa3t-4dghew.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqcft-1rjrzl.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqdvk-8994gu.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqf2j-d0h2pu.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqg51-cw6c2b.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqh4q-ewrp6j.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqi9d-4k1dbh.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqjmh-20o5r6.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqkir-c6sk1c.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/bfe0548a-333b-47f4-bf68-d1bebe86d984/gallery/mvghqlco-awuzu4.webp"]', 4.8, 100, 1, 1, 18.5994, 73.7682, '[{"type": "Smart Office", "carpetArea": "722 sq.ft", "priceRange": "₹68.00 L"}, {"type": "Premium Office", "carpetArea": "719 sq.ft", "priceRange": "₹68 L - ₹2.23 Cr"}]', '["Power Backup", "24x7 Security", "Covered Parking"]', '[{"question": "Where is Prime Pinnacle located?", "answer": "Prime Pinnacle is strategically located in prime Wakad, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Prime Pinnacle?", "answer": "Residences in Prime Pinnacle start from ₹68 L - ₹2.23 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Prime Pinnacle?", "answer": "Prime Pinnacle offers spacious Smart Office, Premium Office apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Prime Pinnacle MahaRERA approved?", "answer": "Yes, Prime Pinnacle is officially registered under MahaRERA with registration number P52100077826. All approvals and certificates are verified."}, {"question": "What amenities are provided at Prime Pinnacle?", "answer": "The development features world-class lifestyle amenities including Power Backup, 24x7 Security, Covered Parking, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-saheel-wakad-111', 'Luxton by Saheel', 'saheel-wakad-111', 'b-saheel-properties', 'Wakad', '₹1.06 Cr - ₹1.98 Cr', '₹1.06 Cr', '["2 BHK", "3 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbi877-8s23ib.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbi877-8s23ib.webp', 'https://keystoneliv.com/public/liv-thumbs/640/uploads/property/9fgd1dc8OsLM6h4q6lT60MbRpIA4vwCadScNvqMA.webp', '["https://keystoneliv.com/public/uploads/property/hgiRTenojaVcHglxBXqRVHfjihUs6wuNa8Yl46OW.png", "https://keystoneliv.com/public/uploads/property/c5iyPCgaCqPe2H7UgjtMuIlxz0gkapjWv7U5nlzE.webp", "https://www.koltepatil.com/assets/uploads/project_floor_plan/1688036267101676629.jpg"]', 'Luxton by Saheel is a residential project by Saheel Properties at Survey No. 111/1/2, next to Indira School, near Shani Mandir Road in Wakad, Pune. It is planned as three towers of about 30 floors on roughly 3 acres, with 2, 3 and 4 BHK homes. Carpet areas, including balconies as printed in the developer''s brochure, run from 753 to 859 sq ft for 2 BHK, 970 to 1,162 sq ft for 3 BHK and 1,457 sq ft for 4 BHK. Listed starting prices are about Rs 1.06 crore for 2 BHK, Rs 1.47 crore for 3 BHK and Rs 1.98 crore for 4 BHK; confirm final cost with the sales team. Highlights include a 4,000 sq ft entrance lobby, a rooftop club with a pool and aqua theatre, a gym, a yoga deck, a pickleball court, an open library and co-working space,. The developer lists the Mumbai-Bangalore Highway about one minute away, Hinjewadi IT Park and Phoenix Mall of the Millennium about ten minutes, and Baner-Balewadi High Street about fifteen minutes. MahaRERA number PM1260002502043; possession is listed for June 2030.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Swimming Pool", "Power Backup"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PM1260002502043"}, {"label": "Direct Starting Price", "value": "₹1.06 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Wakad, Pune"}]', '["MahaRERA: PM1260002502043", "0% Brokerage & Direct Builder Booking", "Wakad Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100062043', 14077, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbi877-8s23ib.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbi9hc-f7f9ef.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbib5p-dbr7p5.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbicaf-8x7cgh.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbidej-1ivzml.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbie9l-ftu8ty.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbif1b-clfyoy.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbifp5-6wa30o.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbigey-aa0g1a.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/adc7420a-f087-4832-b5b6-aaff3c37a461/gallery/mvfbih8q-5s3dgg.webp"]', 4.8, 100, 1, 1, 18.5987, 73.7734, '[{"type": "2 BHK", "carpetArea": "683 sq.ft", "priceRange": "₹1.06 Cr - ₹1.33 Cr"}, {"type": "3 BHK", "carpetArea": "1128 sq.ft", "priceRange": "₹1.48 Cr - ₹1.91 Cr"}, {"type": "4 BHK", "carpetArea": "1731 sq.ft", "priceRange": "₹1.98 Cr"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Swimming Pool", "Power Backup"]', '[{"question": "Where is Luxton by Saheel located?", "answer": "Luxton by Saheel is strategically located in prime Wakad, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Luxton by Saheel?", "answer": "Residences in Luxton by Saheel start from ₹1.06 Cr - ₹1.98 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Luxton by Saheel?", "answer": "Luxton by Saheel offers spacious 2 BHK, 3 BHK, 4 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Luxton by Saheel MahaRERA approved?", "answer": "Yes, Luxton by Saheel is officially registered under MahaRERA with registration number PM1260002502043. All approvals and certificates are verified."}, {"question": "What amenities are provided at Luxton by Saheel?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Clubhouse, Gymnasium, Library, Sports Court, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-panoreeva-greens', 'Panoreeva Greens', 'panoreeva-greens', 'b-avirat-developers', 'Chinchwad', '₹1.00 Cr', '₹1.00 Cr', '["3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw0ci-9m4jzc.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw0ci-9m4jzc.webp', 'https://keystoneliv.com/public/liv-thumbs/640/uploads/property/vX15hcMcA7HmLsjKOvGMFWIWDMSWoPEmMPAAVkXy.webp', '["https://keystoneliv.com/public/uploads/property/FI0pRYe4YtQiDClNaJlsXItZMlHcOGiWSdLu8YJw.webp"]', 'Panoreeva Greens is a riverside residential project by Avirat Developers at Survey No. 110, Walhekarwadi, Chinchwad, Pune 411033, beside the Pavana river and close to Chhatrapati Shivaji Chowk. Built on a land parcel of about 72,200 sq ft (roughly 1.66 acres), it is planned as five connected towers with rooftop amenity decks and around 300 apartments. The homes are 3 BHK residences with carpet areas of 864 sq ft and 903 sq ft, served by two lifts per wing with generator backup. Asking prices on property portals in October 2026 start at ₹1 Cr for a 3 BHK; confirm the current price sheet with the sales team. Amenities include a gymnasium, children''s play area, landscaped garden, EV charging points, a skywalk jogging track, a stargazing deck and an acupressure pathway. The developer''s brochure lists Aditya Birla Memorial Hospital about 4.4 km away, Bhosari MIDC about 4.5 km, Wakad IT Park about 5.5 km and the Hinjewadi IT hub about 10 km. The project is registered under MahaRERA number P52100078744, with possession scheduled for December 2028.', '["Gymnasium", "Jogging Track", "Power Backup", "24x7 Security", "Landscaped Garden", "Kids'' Play Area", "EV Charging"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100078744"}, {"label": "Direct Starting Price", "value": "₹1 Cr"}, {"label": "Configurations", "value": "3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Chinchwad, Pune"}]', '["MahaRERA: P52100078744", "0% Brokerage & Direct Builder Booking", "Chinchwad Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100078744', 11574, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw0ci-9m4jzc.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw2g4-760ndx.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw38t-g0alx8.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw3zn-3q09vn.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw4re-bz8uef.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw5el-2o9yru.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw5vv-67331t.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw6rs-6smp4u.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw7bc-b4oxel.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/17fc8bdb-26b0-4047-9313-5e050676841b/gallery/mvghw80v-bzs5yz.webp"]', 4.8, 100, 1, 0, 18.6346, 73.7795, '[{"type": "3 BHK", "carpetArea": "1074 sq.ft", "priceRange": "₹1.00 Cr"}]', '["Gymnasium", "Jogging Track", "Power Backup", "24x7 Security", "Landscaped Garden", "Kids'' Play Area", "EV Charging"]', '[{"question": "Where is Panoreeva Greens located?", "answer": "Panoreeva Greens is strategically located in prime Chinchwad, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Panoreeva Greens?", "answer": "Residences in Panoreeva Greens start from ₹1 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Panoreeva Greens?", "answer": "Panoreeva Greens offers spacious 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Panoreeva Greens MahaRERA approved?", "answer": "Yes, Panoreeva Greens is officially registered under MahaRERA with registration number P52100078744. All approvals and certificates are verified."}, {"question": "What amenities are provided at Panoreeva Greens?", "answer": "The development features world-class lifestyle amenities including Gymnasium, Jogging Track, Power Backup, 24x7 Security, Landscaped Garden, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-elementis-oro', 'Elementis ORO', 'elementis-oro', 'b-adi-group', 'Nigdi', '₹1.50 Cr - ₹1.90 Cr', '₹1.50 Cr', '["3 BHK"]', 'New Launch', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/e40babf9-1772-489e-a6cb-625300ca3252/gallery/mvhmmyfa-azmrba.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/e40babf9-1772-489e-a6cb-625300ca3252/gallery/mvhmmyfa-azmrba.webp', '/images/projects/anp-universe/master-layout.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1676437496513882194.jpg"]', 'Elementis ORO by ADI Group is a new launch in Pradhikaran, Nigdi – the successor to the developer''s Elementis project in the same neighbourhood. It is a boutique community of two towers with exclusive 3 BHK residences of 1,318 and 1,438 sq ft carpet area. Homes are three-side open, with spacious kitchens and dedicated store rooms, walk-in wardrobes, large living-room balconies and sit-outs, and dry balconies off the kitchen. Every apartment has 24x7 DG power backup, and the building has multi-level security with 24x7 CCTV, lifts, a fire-fighting system, a children''s play area, closed car parking, a sewage treatment plant, rainwater harvesting and landscaped greens. Pradhikaran is one of Pimpri-Chinchwad''s planned residential sectors, with wide roads, gardens and established schools, hospitals and markets close by. Prices start from ₹1.50 Cr and go up to ₹1.90 Cr, with a flexi-payment plan available. The project is registered with MahaRERA under PR1260002601161, with a RERA completion date of December 2030.', '["CCTV Surveillance", "Rainwater Harvesting", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"label": "Project Status", "value": "New Launch"}, {"label": "MahaRERA ID", "value": "PR1260002601161"}, {"label": "Direct Starting Price", "value": "₹1.50 Cr"}, {"label": "Configurations", "value": "3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Nigdi, Pune"}]', '["MahaRERA: PR1260002601161", "0% Brokerage & Direct Builder Booking", "Nigdi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100021161', 11380, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/e40babf9-1772-489e-a6cb-625300ca3252/gallery/mvhmmyfa-azmrba.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e40babf9-1772-489e-a6cb-625300ca3252/gallery/mvhmmz3d-cv5mrs.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e40babf9-1772-489e-a6cb-625300ca3252/gallery/mvhmmzlr-dmp6gq.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e40babf9-1772-489e-a6cb-625300ca3252/gallery/mvhn99f5-4avpyc.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/0cc7c1eb-b0b8-46a2-8135-af7b5aa30e87/gallery/msd1y7ws-acprh7.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/0cc7c1eb-b0b8-46a2-8135-af7b5aa30e87/gallery/msd1y5rp-5iy0o.webp"]', 4.8, 100, 1, 0, 18.6576, 73.766, '[{"type": "3 BHK Premium", "carpetArea": "1125 sq.ft", "priceRange": "₹1.50 Cr"}, {"type": "3 BHK Grande", "carpetArea": "1425 sq.ft", "priceRange": "₹1.90 Cr"}]', '["CCTV Surveillance", "Rainwater Harvesting", "Power Backup", "24x7 Security", "Landscaped Garden", "Covered Parking", "Kids'' Play Area"]', '[{"question": "Where is Elementis ORO located?", "answer": "Elementis ORO is strategically located in prime Nigdi, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Elementis ORO?", "answer": "Residences in Elementis ORO start from ₹1.50 Cr - ₹1.90 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Elementis ORO?", "answer": "Elementis ORO offers spacious 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Elementis ORO MahaRERA approved?", "answer": "Yes, Elementis ORO is officially registered under MahaRERA with registration number PR1260002601161. All approvals and certificates are verified."}, {"question": "What amenities are provided at Elementis ORO?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Rainwater Harvesting, Power Backup, 24x7 Security, Landscaped Garden, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-unique-youtopia', 'Unique Youtopia', 'unique-youtopia', 'b-unique-properties', 'Kharadi', '₹1.01 Cr - ₹1.37 Cr', '₹1.01 Cr', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8guz-31y41y.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8guz-31y41y.webp', 'https://keystoneliv.com/public/uploads/property/nBIFK5yY27v8iGeOPunLCcGZJMSxZp8NlvxZwRKD.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1676437625251825814.jpg", "/images/projects/anp-autograph/floor-plan-3bhk.webp"]', 'Unique Youtopia is a residential township in Central Kharadi, Pune, by Unique Properties in association with the Kodre family, on River Road. Phase IV, registered with MahaRERA as P52100080485, brings the A7 and A8 wings with 2 BHK homes of 748 to 761 sq ft and 3 BHK homes of 893 to 1,009 sq ft (total area including balconies). Prices start at about ₹1.01 crore for a 2 BHK and ₹1.22 crore for a 3 BHK, including one covered parking. The project spreads 45+ amenities over 5 recreation zones and more than 40,000 sq ft of open area: an infinity pool and clubhouse, indoor gym with AC, spa and steam room, party hall, badminton, table tennis and multipurpose courts, a cricket net, jogging and barefoot tracks, yoga cove, children''s play areas, a crèche, Wi-Fi workstations and a theatre area. Homes have 600 mm x 1200 mm vitrified flooring, smart biometric locks, video door phones and solar-heated water in all bathrooms. Zensar IT Park and World Trade Center are about 2 km away, EON IT Park 3 km, and Pune airport about 9 km. The RERA completion date for Phase IV is April 2029.', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "P52100080485"}, {"label": "Direct Starting Price", "value": "₹1.01 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Kharadi, Pune"}]', '["MahaRERA: P52100080485", "0% Brokerage & Direct Builder Booking", "Kharadi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100080485', 13529, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8guz-31y41y.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8hru-61kjw4.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8iig-4jkh1c.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8j92-20ss72.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8jxx-a1vmoo.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8kn1-5u9781.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8lhd-ck3y8.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8m68-fdaep7.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8mwl-5m1w0a.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8nma-8cevjb.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8o14-9o0pn2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8oql-243vdx.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/725beed8-203a-4b2b-83e9-ac91408cc883/gallery/mvjd8pa9-6k7ylk.webp"]', 4.8, 100, 1, 1, 18.5552, 73.9345, '[{"type": "2 BHK", "carpetArea": "750 sq.ft", "priceRange": "₹1.01 Cr - ₹1.26 Cr"}, {"type": "3 BHK", "carpetArea": "1051 sq.ft", "priceRange": "₹1.41 Cr - ₹1.82 Cr"}]', '["CCTV Surveillance", "Clubhouse", "Gymnasium", "Rainwater Harvesting", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool"]', '[{"question": "Where is Unique Youtopia located?", "answer": "Unique Youtopia is strategically located in prime Kharadi, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Unique Youtopia?", "answer": "Residences in Unique Youtopia start from ₹1.01 Cr - ₹1.37 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Unique Youtopia?", "answer": "Unique Youtopia offers spacious 2 BHK, 3 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Unique Youtopia MahaRERA approved?", "answer": "Yes, Unique Youtopia is officially registered under MahaRERA with registration number P52100080485. All approvals and certificates are verified."}, {"question": "What amenities are provided at Unique Youtopia?", "answer": "The development features world-class lifestyle amenities including CCTV Surveillance, Clubhouse, Gymnasium, Rainwater Harvesting, Sports Court, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-godrej-ivara', 'Godrej Ivara', 'godrej-ivara', 'b-godrej', 'Kharadi', '₹1.29 Cr - ₹3.19 Cr', '₹1.29 Cr', '["2 BHK", "3 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqju3k-4r5zbd.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqju3k-4r5zbd.webp', 'https://keystoneliv.com/public/uploads/property/P8QVGC64Hk3A8KQdGVAySetrgtwaNp3vYfH4zEou.webp', '["https://keystoneliv.com/public/uploads/property/c5iyPCgaCqPe2H7UgjtMuIlxz0gkapjWv7U5nlzE.webp", "https://keystoneliv.com/public/uploads/property/tJoMXAcz93Q3AzNSRbGl2rqXifgKmka5ixZgZ61W.webp", "https://keystoneliv.com/public/uploads/property/image (81).webp"]', 'Godrej Ivara by Godrej Properties is a large-format community in Kharadi, Pune, a few minutes from EON Free Zone and the World Trade Center. Spread over about 12.8 acres with 11 towers (A to K), it offers 2, 3 and 4 BHK homes from 729 to 1,580 sq ft, with around 6 acres of open, landscaped greens. Amenities cover about 1 lakh sq ft across two clubhouses and a landscaped podium: a 10,000 sq ft gym with CrossFit and strength zones beside a yoga and wellness spa with a temperature-controlled jacuzzi, a 20,000 sq ft co-working space with quiet pods, meeting "war rooms", hot desks and private enterprise suites, a 10,000 sq ft Mediterranean-themed café with indoor and alfresco dining, two banquet halls, indoor badminton and squash courts, a library, a crèche, a wellness and spa area, a lagoon-style lap pool with jacuzzi and kids'' pool, a floating deck with water features, an amphitheatre, multi-play, pickleball, half-basketball and box-cricket courts, a skate park, a pet park and an oval sports ground. Homes come with Kohler or equivalent sanitaryware, vitrified flooring, granite kitchen counters, sliding windows with mosquito mesh, a video door phone and solar water heating in the master bathroom, built to Godrej''s quality standards (IS 1786 and IS 13920 steel, M35 concrete and 1.5 m waterproofing in wet areas). EON Free Zone and the World Trade Center are about 0.5 km away, Commerzone about 1.4 km, Viman Nagar 8–12 minutes and Pune International Airport about 20 minutes. Prices start from ₹1.29 Cr for a 2 BHK (PLC and floor rise extra). MahaRERA PR1260002502426; RERA completion date December 2032.', '["Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "24x7 Security"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1260002502426"}, {"label": "Direct Starting Price", "value": "₹1.29 Cr"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Kharadi, Pune"}]', '["MahaRERA: PR1260002502426", "0% Brokerage & Direct Builder Booking", "Kharadi Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100062426', 17695, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqju3k-4r5zbd.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqjup8-ewh77d.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqjvde-5uxbca.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqjw23-a4tms0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqjwl0-4szzdj.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqjx50-cec322.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqjxqq-8k4h4q.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqjy5l-4zryd5.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqjz46-9xqdrk.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhqjzt5-8f8qvs.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhr9j1b-2c2zwd.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhr9kim-co7x1m.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhr9lfx-3u0x2d.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhr9me2-8ra0g6.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhr9n9x-68kz8n.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhr9o16-92jedj.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/5792a6e0-c6da-4bc5-ab9b-a5bf7c84fb5d/gallery/mvhr9oyf-87mx1i.webp"]', 4.8, 100, 1, 1, 18.5557, 73.9375, '[{"type": "2 BHK", "carpetArea": "754 sq.ft", "priceRange": "₹1.29 Cr - ₹1.61 Cr"}, {"type": "3 BHK", "carpetArea": "1073 sq.ft", "priceRange": "₹1.81 Cr - ₹2.32 Cr"}, {"type": "4 BHK", "carpetArea": "1560 sq.ft", "priceRange": "₹3.19 Cr"}]', '["Clubhouse", "Gymnasium", "Library", "Sports Court", "Co-working Lounge", "Jogging Track", "Swimming Pool", "24x7 Security"]', '[{"question": "Where is Godrej Ivara located?", "answer": "Godrej Ivara is strategically located in prime Kharadi, Pune, offering seamless connectivity to commercial centers, transit corridors, and essential social infrastructure."}, {"question": "What is the starting price for flats in Godrej Ivara?", "answer": "Residences in Godrej Ivara start from ₹1.29 Cr - ₹3.19 Cr with zero brokerage and direct builder inventory allocation through PROPSMART REALTY."}, {"question": "What unit configurations are available in Godrej Ivara?", "answer": "Godrej Ivara offers spacious 2 BHK, 3 BHK, 4 BHK apartments designed for maximum carpet area efficiency and natural ventilation."}, {"question": "Is Godrej Ivara MahaRERA approved?", "answer": "Yes, Godrej Ivara is officially registered under MahaRERA with registration number PR1260002502426. All approvals and certificates are verified."}, {"question": "What amenities are provided at Godrej Ivara?", "answer": "The development features world-class lifestyle amenities including Clubhouse, Gymnasium, Library, Sports Court, Co-working Lounge, multi-tier security systems, and high-speed elevators."}]', '');
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-vj-palladio-la-viento', 'VJ Palladio La Viento', 'vj-palladio-la-viento', 'b-vilas-javdekar', 'Mahalunge', '₹99.07 L - ₹1.52 Cr', '₹99.07 L', '["2 BHK", "3 BHK", "4 BHK"]', 'Under Construction', 'Residential', '2027', 'https://punehome.in/storage/v1/object/public/project-media/projects/e1c8ac64-4e65-460a-84c8-460f12548757/gallery/mvf7dh1w-4kkjja.webp', 'https://punehome.in/storage/v1/object/public/project-media/projects/e1c8ac64-4e65-460a-84c8-460f12548757/gallery/mvf7dh1w-4kkjja.webp', 'https://keystoneliv.com/public/liv-thumbs/640/uploads/property/iTt80ob6Q847pdqJo6QxQYX9jjyINihAoQvfFwpB.webp', '["https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1734594000266262849.jpeg", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/1676437291248393030.jpg", "https://www.koltepatil.com/assets/uploads/project_floor_plan/base_image/17284659891506445855.jpg"]', 'VJ Palladio La Viento is a residential project by Vilas Javdekar Developers at Baner-Mahalunge, near VIBGYOR High School, Pune. Spread over about 3.78 acres with roughly 75% open area, it has two 27-storey towers with 194 apartments. Homes come in 2, 3 and 4 BHK layouts with carpet areas from about 708 sq ft (2 BHK) to 1,086 sq ft (4 BHK), with listed prices starting around Rs 99 lakh; please confirm current pricing with the sales team. The towers are planned for cross-ventilation and carry a curved facade. A three-storey, Spanish-villa style Club LaViento anchors over 40 amenities across six landscaped zones, including a swimming pool with kids'' pool, jogging track, multipurpose court, open gym, amphitheatre-style seating and a pets'' area. The site lies between Baner, Sus and Balewadi, about 2.2 km from D-Mart and 2.3 km from the Sus-Pashan bridge, with the Mumbai-Pune bypass flyover about 3.6 km away. It is registered with MahaRERA under PR1260002501182, with a registered completion date of December 2029.', '["Clubhouse", "Gymnasium", "Sports Court", "Jogging Track", "Swimming Pool", "Power Backup", "24x7 Security", "Landscaped Garden"]', '[{"label": "Project Status", "value": "Under Construction"}, {"label": "MahaRERA ID", "value": "PR1260002501182"}, {"label": "Direct Starting Price", "value": "₹99.07 L"}, {"label": "Configurations", "value": "2 BHK, 3 BHK, 4 BHK"}, {"label": "Possession Date", "value": "2027"}, {"label": "Micro-Market", "value": "Mahalunge, Pune"}]', '["MahaRERA: PR1260002501182", "0% Brokerage & Direct Builder Booking", "Mahalunge Prime Residential Corridor", "Sanctioned Developer Payment Schedule"]', 'P52100061182', 13992, 'Verified', 'Pune', '["https://punehome.in/storage/v1/object/public/project-media/projects/e1c8ac64-4e65-460a-84c8-460f12548757/gallery/mvf7dh1w-4kkjja.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e1c8ac64-4e65-460a-84c8-460f12548757/gallery/mvf7dhz1-b2tpq2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e1c8ac64-4e65-460a-84c8-460f12548757/gallery/mvf7dip0-7hapre.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e1c8ac64-4e65-460a-84c8-460f12548757/gallery/mvf7djkg-48mzl0.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e1c8ac64-4e65-460a-84c8-460f12548757/gallery/mvf7dkhl-by3j3i.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e1c8ac64-4e65-460a-84c8-460f12548757/gallery/mvf7dlbv-9dtdy2.webp", "https://punehome.in/storage/v1/object/public/project-media/projects/e1c8ac64-4e65-460a-84c8-460f12548757/gallery/mvf7dm64-8n3ajd.webp", "https://punehome.in/storag