INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-paranjape-blue-ridge-promenade', 'Paranjape Blue Ridge - The Promenade', 'paranjape-blue-ridge-promenade', 'b-paranjape', 'Hinjewadi', '₹1.80 Cr - ₹2.50 Cr', '₹1.80 Cr', '["3 BHK", "4 BHK"]', 'Under Construction', 'Residential', 'December 2026', 'https://www.pscl.in/wp-content/uploads/2025/10/ANK440_7834a_LR.webp', 'https://www.pscl.in/wp-content/uploads/2025/10/ANK440_7834a_LR.webp', 'https://keystoneliv.com/public/uploads/property/5oObZb7synV62rPVYqZAbCYsgqNubnGbhVrvmYj8.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/neQCNkziS5bgoqGRmAb7yybVwaAKDFIUsnKt9779.webp", "https://keystoneliv.com/public/uploads/property/jnS1qblkmU2CpmWs6iYIug0TT9I1JmRAEizQVMsP.webp"]', 'The Promenade by Paranjape Schemes is a luxury waterfront high-rise development in the iconic 138-acre Blue Ridge Township, Hinjewadi Phase 1, Pune. Rising 32 storeys along the serene Mula riverfront, these limited-edition 3 and 4 BHK residences offer private elevator foyers, floor-to-ceiling glass balconies, Italian marble finishes, and unhindered river panoramas.
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-paranjape-blue-ridge-altius', 'Paranjape Blue Ridge - The Altius', 'paranjape-blue-ridge-altius', 'b-paranjape', 'Hinjewadi', '₹1.95 Cr - ₹4.00 Cr', '₹1.95 Cr', '["3 BHK", "4 BHK", "5 BHK"]', 'Under Construction', 'Residential', 'December 2027', 'https://www.pscl.in/wp-content/uploads/2025/10/Altius-scaled.webp', 'https://www.pscl.in/wp-content/uploads/2025/10/Altius-scaled.webp', 'https://keystoneliv.com/public/uploads/property/OrO96DlQ1BdtwMK7CAwta4xb2E56lGlQ1N3qwfrF.webp', '["https://keystoneliv.com/public/uploads/property/jnS1qblkmU2CpmWs6iYIug0TT9I1JmRAEizQVMsP.webp", "https://keystoneliv.com/public/uploads/property/zp0VEmpHjp3nxN9ZDMZAsjt8sftwy04Pt0zchCPr.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/WQDgrXOUlEW3lrJuTVXdijlc3HUZMVKaA76af70F.webp"]', 'The Altius (Tower 26) is the crown jewel architectural skyscraper within Paranjape Blue Ridge township in Hinjewadi, Pune. Soaring 36 storeys high, The Altius offers ultra-luxury 3, 4, and 5 BHK penthouses and grand residences designed for Pune''s corporate leadership and global CXOs.
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-paranjape-trident-towers', 'Paranjape Trident Towers', 'paranjape-trident-towers', 'b-paranjape', 'Hinjewadi', '₹43.00 L - ₹80.00 L', '₹43.00 L', '["1 BHK", "2 BHK"]', 'Under Construction', 'Residential', 'December 2026', 'https://www.pscl.in/wp-content/uploads/2025/10/Trident-Tower-scaled.webp', 'https://www.pscl.in/wp-content/uploads/2025/10/Trident-Tower-scaled.webp', 'https://keystoneliv.com/public/uploads/property/QUSiXbX1yIv3u1F0efgnLHyJgKsJfu0DIDG1r7Wi.webp', '["https://keystoneliv.com/public/uploads/property/elqlVrqhkL41pdaytkeF0xK9oc0oitS9ZctMJKZz.webp", "https://keystoneliv.com/public/uploads/property/cu7T1exp3WjBAuIjjcAQclhBnDwVt0x1lCTQkwlS.webp"]', 'Trident Towers by Paranjape Schemes is a high-tech residential landmark located on the Hinjewadi-Wakad Link Road. Engineered with modern Mivan shuttering technology, these smart 1 & 2 BHK homes are crafted specifically for young IT and engineering professionals.
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-paranjape-forest-trails-highgardens', 'Paranjape Forest Trails - Highgardens', 'paranjape-forest-trails-highgardens', 'b-paranjape', 'Bavdhan', '₹87.00 L - ₹1.71 Cr', '₹87.00 L', '["2 BHK", "3 BHK", "4 BHK"]', 'Under Construction', 'Residential', 'July 2028', 'https://www.pscl.in/wp-content/uploads/2025/10/Highgardens-scaled.webp', 'https://www.pscl.in/wp-content/uploads/2025/10/Highgardens-scaled.webp', 'https://keystoneliv.com/public/uploads/property/LRk6ujgc4OZvne3hIg9Oy1w5Ybq2LhGzE9FyFTTw.webp', '["https://keystoneliv.com/public/uploads/property/cu7T1exp3WjBAuIjjcAQclhBnDwVt0x1lCTQkwlS.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp", "https://keystoneliv.com/public/uploads/property/jnS1qblkmU2CpmWs6iYIug0TT9I1JmRAEizQVMsP.webp"]', 'Highgardens is a premier hillside residential enclave inside the celebrated 190+ acre Forest Trails Township in Bhugaon, just minutes from Bavdhan and Chandani Chowk. Highgardens introduces private terrace garden residences that seamlessly blend indoor luxury with lush Sahyadri nature.
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-paranjape-forest-trails-canopy', 'Paranjape Forest Trails - The Canopy', 'paranjape-forest-trails-canopy', 'b-paranjape', 'Bavdhan', '₹83.00 L - ₹1.21 Cr', '₹83.00 L', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', 'December 2029', 'https://www.pscl.in/wp-content/uploads/2025/10/Canopy-1-scaled.webp', 'https://www.pscl.in/wp-content/uploads/2025/10/Canopy-1-scaled.webp', 'https://keystoneliv.com/public/uploads/property/fx4tJjRmJedaJ69GSAzp9y1Po3iHhu7xv951qJNV.webp', '["https://keystoneliv.com/public/uploads/property/cu7T1exp3WjBAuIjjcAQclhBnDwVt0x1lCTQkwlS.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp"]', 'The Canopy (Sector R48) is a 24-storey high-rise biophilic residential tower nestled inside the 190-acre Forest Trails Township in Bhugaon, minutes from Bavdhan, Pune. Designed to sit under the verdant canopy of 34,000+ forest trees, every apartment offers cross ventilation and unobstructed valley perspectives.
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-paranjape-rivolo-residences', 'Paranjape Forest Trails - The Rivolo Residences', 'paranjape-rivolo-residences', 'b-paranjape', 'Bavdhan', '₹3.89 Cr - ₹5.70 Cr', '₹3.89 Cr', '["3 BHK", "4 BHK", "5 BHK"]', 'Under Construction', 'Residential', 'December 2027', 'https://keystoneliv.com/public/uploads/property/b5oceIMtghaxSSAiO2E5Dt4oVI3a7Uc6uRakqvre.webp', 'https://keystoneliv.com/public/uploads/property/b5oceIMtghaxSSAiO2E5Dt4oVI3a7Uc6uRakqvre.webp', 'https://keystoneliv.com/public/uploads/property/3dehuUq2Po5NML9mJlmIQO5xPl9IF2CTVSuFPjDO.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp", "https://keystoneliv.com/public/uploads/property/jnS1qblkmU2CpmWs6iYIug0TT9I1JmRAEizQVMsP.webp", "https://keystoneliv.com/public/uploads/property/zp0VEmpHjp3nxN9ZDMZAsjt8sftwy04Pt0zchCPr.webp"]', 'The Rivolo Residences represents the pinnacle of private villa luxury in Pune. Set upon high hill ridges inside the Forest Trails Township near Bavdhan, each standalone villa features a private garden, personal plunge pool provision, multi-tier entertainment terraces, and bespoke luxury interiors.
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-paranjape-orchard-residences', 'Paranjape Forest Trails - The Orchard Residences', 'paranjape-orchard-residences', 'b-paranjape', 'Bavdhan', '₹1.65 Cr - ₹2.40 Cr', '₹1.65 Cr', '["3 BHK", "4 BHK"]', 'Under Construction', 'Residential', 'March 2029', 'https://keystoneliv.com/public/uploads/property/6muqAWdRxTJUTEwNXQRGeBfgVIluqwTW2aig5Gly.webp', 'https://keystoneliv.com/public/uploads/property/6muqAWdRxTJUTEwNXQRGeBfgVIluqwTW2aig5Gly.webp', 'https://keystoneliv.com/public/uploads/property/Ptw9XmFBU5IeYvADN8ruLftUvTCTToYOMifOkh2x.webp', '["https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp", "https://keystoneliv.com/public/uploads/property/jnS1qblkmU2CpmWs6iYIug0TT9I1JmRAEizQVMsP.webp"]', 'The Orchard Residences (Sector R40) offers spacious low-density villaments and grand apartments overlooking fragrant mango and fruit groves in Forest Trails, Bhugaon near Bavdhan. Offering expansive carpet areas from 2,100 to 2,400+ sq. ft., these homes are crafted for discerning multi-generational families.
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-paranjape-athashri-b3', 'Paranjape Athashri B3 - Forest Trails', 'paranjape-athashri-b3', 'b-paranjape', 'Bavdhan', '₹80.00 L - ₹1.25 Cr', '₹80.00 L', '["2 BHK", "3 BHK"]', 'Under Construction', 'Residential', 'September 2029', 'https://keystoneliv.com/public/uploads/property/UPzmG4euaO1BOdmqRNMXOBWt8x0Bj8yXV84daLnk.webp', 'https://keystoneliv.com/public/uploads/property/UPzmG4euaO1BOdmqRNMXOBWt8x0Bj8yXV84daLnk.webp', 'https://keystoneliv.com/public/uploads/property/8KKQNl9pXNBZ6numJWe8UNpGknzVelIS0Qg1KIWp.webp', '["https://keystoneliv.com/public/uploads/property/cu7T1exp3WjBAuIjjcAQclhBnDwVt0x1lCTQkwlS.webp", "https://keystoneliv.com/public/liv-thumbs/640/uploads/property/dS3PCn4Zmfevi02ZqMfIVLhUbyT8IDY8hkxIqqzj.webp"]', 'Athashri B3 is the newest landmark phase of Paranjape Schemes'' globally acclaimed Athashri senior living brand, situated inside the Forest Trails Township in Bhugaon near Bavdhan, Pune. Specially conceptualized for senior citizens, it incorporates barrier-free anti-skid architectural design, emergency grab-bars, 24x7 doctor & paramedic on-campus response, and full-service community dining.
INSERT INTO projects (id, title, slug, builder_id, location, price_range, exact_price, configurations, status, type, possession_date, image, hero_image, master_layout, floor_plans, description, features, specs, highlights, rera_id, price_per_sqft, verification_status, city, images, rating, reviews_count, is_verified, is_featured, lat, lng, configuration_details, amenities, faqs, brochure_url) VALUES ('p-paranjape-athashri-baner', 'Paranjape Athashri Baner', 'paranjape-athashri-baner', 'b-paranjape', 'Baner', '₹50.00 L - ₹1.60 Cr', '₹50.00 L', '["1 BHK", "2 BHK"]', 'Ready to Move', 'Residential', 'Ready to Move', 'https://keystoneliv.com/public/uploads/property/aMobBGd7Ut8Rx6KGpdkdEhct7heEo0dv5pyVzWik.webp', 'https://keystoneliv.com/public/uploads/property/aMobBGd7Ut8Rx6KGpdkdEhct7heEo0dv5pyVzWik.webp', 'https://www.vtprealty.in/images/project/project-details/vtp-verve-baner-sus-pune/Verve_Master_Plan_4b72183c9a.webp', '["https://keystoneliv.com/public/uploads/property/elqlVrqhkL41pdaytkeF0xK9oc0oitS9ZctMJKZz.webp", "https://keystoneliv.com/public/uploads/property/cu7T1exp3WjBAuIjjcAQclhBnDwVt0x1lCTQkwlS.webp"]', 'Athashri Baner is Paranjape Schemes'' iconic pioneer retirement community on Pan Card Club Road, Baner, Pune. Established as India''s premier dedicated senior living habitat, Athashri Baner features specialized amenities like home-delivered meals, medical check-ups, housekeeping support, cultural clubs, and 24-hour security.
